def scan_dsa_ext_external_debt_nominal_1(*, dsa_ext_non_interest_current_account_deficit: data.Series[float | str | None], dsa_ext_net_fdi_negative_inflow: data.Series[float | str | None], dsa_ext_denominator_1_g_g: data.Series[float | str | None], dsa_ext_nominal_gdp_million_of_us_dollars: data.Series[float | str | None], dsa_ext_real_gdp_growth_in_percent: data.Series[float | str | None], dsa_ext_gdp_deflator_in_us_dollar_terms_change_in_percent: data.Series[float | str | None], dsa_ext_share_of_local_currency_denominated_external_debt_to_total_external_debt: data.Series[float | str | None], dsa_ext_share_of_local_currency_denominated_external_debt_to_total_external_debt_baseline: data.Series[float | str | None], dsa_ext_depreciation_of_nc_depreciation: data.Series[float | str | None], dsa_ext_o_w_interest_baseline: data.Series[float | str | None], dsa_ext_o_w_interest_additional_borrowing: data.Series[float | str | None], dsa_ext_of_which_public_and_publicly_guaranteed_ppg: data.Series[float | str | None], dsa_ext_of_which_private: data.Series[float | str | None], c4_mkt_fin_gfn_increase: data.Series[float | str | None], macro_debt_total_ext_debt_interest_due_include_interest: data.Series[float | str | None], pv_stress_bounds_t_g_0: data.Series[int | str | None], pv_stress_bounds_t_m_condition: data.Series[int | str | None], pv_stress_average_interest_rate_new_debt: data.Series[float | str | None], pv_stress_average_maturity_of_new_debt: data.Series[float | str | None], pv_stress_average_grace_period_new_debt: data.Series[float | str | None], pv_stress_t_g_0: data.Series[int | str | None], pv_stress_t_m_condition: data.Series[int | str | None]) -> ScanDsaExtExternalDebtNominal1Result:
    """Evaluate the recurrence group `dsa_ext_external_debt_nominal_1`, `dsa_ext_change_in_external_debt`, `dsa_ext_identified_net_debt_creating_flows`, `dsa_ext_endogenous_debt_dynamics_2`, `dsa_ext_contribution_from_nominal_interest_rate`, `dsa_ext_contribution_from_real_gdp_growth`, `dsa_ext_contribution_from_price_and_exchange_rate_changes`, `dsa_ext_residual_3`, `dsa_ext_effective_interest_rate_percent_4`, `dsa_ext_nominal_debt_baseline`, `dsa_ext_increase_baseline`, `dsa_ext_nominal_debt_stress`, `dsa_ext_increase_stress`, `dsa_ext_residual_gross_borrowing`, `dsa_ext_o_w_interest_stress`, `dsa_ext_new_interest_payments`, `dsa_ext_effective_rate`, `pv_stress_bounds_new_forex_borrowing_gross_usd`, `pv_stress_bounds_cumulative`, `pv_stress_bounds_stock_of_new_forex_debt_in_usd`, `pv_stress_bounds_interest`, `pv_stress_bounds_amortization`, `pv_stress_bounds_cumulative_selected_by_t_g_0`, `pv_stress_bounds_cumulative_selected_by_t_m_condition`, `pv_stress_new_forex_borrowing_gross_usd`, `pv_stress_cumulative`, `pv_stress_stock_of_new_forex_debt`, `pv_stress_interest`, `pv_stress_amortization`, `pv_stress_cumulative_selected_t_g_0`, `pv_stress_cumulative_selected_t_m_condition` and publish complete tensors."""
    def dsa_ext_external_debt_nominal_1_formula(scenario: str, time_period: int) -> float | str | None:
        if scenario in ('A1', 'B1', 'B3', 'B4', 'B5', 'B6_mkt', 'B6_nonmkt', 'C3') and time_period <= 2024:
            return as_measure(dsa_ext_external_debt_nominal_1['Baseline', time_period])
        elif scenario == 'Baseline':
            return as_measure((xl_add(dsa_ext_of_which_public_and_publicly_guaranteed_ppg[scenario, time_period], dsa_ext_of_which_private[scenario, time_period]) if xl_bool(xl_and(xl_isnumber(lambda: dsa_ext_of_which_public_and_publicly_guaranteed_ppg[scenario, time_period]), xl_isnumber(lambda: dsa_ext_of_which_private[scenario, time_period]))) else '…'))
        return as_measure(xl_add(dsa_ext_external_debt_nominal_1[scenario, time_period - 1], dsa_ext_change_in_external_debt[scenario, time_period]))

    dsa_ext_external_debt_nominal_1 = CoordinateReader('dsa_ext_external_debt_nominal_1', data.DSA_EXT_EXTERNAL_DEBT_NOMINAL_1.required, dsa_ext_external_debt_nominal_1_formula)
    def dsa_ext_change_in_external_debt_formula(scenario: str, time_period: int) -> float | str | None:
        if scenario == 'Baseline':
            return as_measure(xl_sub(dsa_ext_external_debt_nominal_1[scenario, time_period], dsa_ext_external_debt_nominal_1[scenario, time_period - 1]))
        return as_measure(xl_add(dsa_ext_identified_net_debt_creating_flows[scenario, time_period], dsa_ext_residual_3[scenario, time_period]))

    dsa_ext_change_in_external_debt = CoordinateReader('dsa_ext_change_in_external_debt', data.DSA_EXT_CHANGE_IN_EXTERNAL_DEBT.required, dsa_ext_change_in_external_debt_formula)
    def dsa_ext_identified_net_debt_creating_flows_formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure(xl_add(xl_add(dsa_ext_non_interest_current_account_deficit[scenario, time_period], dsa_ext_net_fdi_negative_inflow[scenario, time_period]), dsa_ext_endogenous_debt_dynamics_2[scenario, time_period]))

    dsa_ext_identified_net_debt_creating_flows = CoordinateReader('dsa_ext_identified_net_debt_creating_flows', data.DSA_EXT_IDENTIFIED_NET_DEBT_CREATING_FLOWS.required, dsa_ext_identified_net_debt_creating_flows_formula)
    def dsa_ext_endogenous_debt_dynamics_2_formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure(xl_add(xl_add(dsa_ext_contribution_from_nominal_interest_rate[scenario, time_period], dsa_ext_contribution_from_real_gdp_growth[scenario, time_period]), dsa_ext_contribution_from_price_and_exchange_rate_changes[scenario, time_period]))

    dsa_ext_endogenous_debt_dynamics_2 = CoordinateReader('dsa_ext_endogenous_debt_dynamics_2', data.DSA_EXT_ENDOGENOUS_DEBT_DYNAMICS_2.required, dsa_ext_endogenous_debt_dynamics_2_formula)
    def dsa_ext_contribution_from_nominal_interest_rate_formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure(xl_div(xl_mul(xl_div(dsa_ext_effective_interest_rate_percent_4[scenario, time_period], 100), dsa_ext_external_debt_nominal_1[scenario, time_period - 1]), dsa_ext_denominator_1_g_g[scenario, time_period]))

    dsa_ext_contribution_from_nominal_interest_rate = CoordinateReader('dsa_ext_contribution_from_nominal_interest_rate', data.DSA_EXT_CONTRIBUTION_FROM_NOMINAL_INTEREST_RATE.required, dsa_ext_contribution_from_nominal_interest_rate_formula)
    def dsa_ext_contribution_from_real_gdp_growth_formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure(xl_div(xl_mul(xl_neg(xl_div(dsa_ext_real_gdp_growth_in_percent[scenario, time_period], 100)), dsa_ext_external_debt_nominal_1[scenario, time_period - 1]), dsa_ext_denominator_1_g_g[scenario, time_period]))

    dsa_ext_contribution_from_real_gdp_growth = CoordinateReader('dsa_ext_contribution_from_real_gdp_growth', data.DSA_EXT_CONTRIBUTION_FROM_REAL_GDP_GROWTH.required, dsa_ext_contribution_from_real_gdp_growth_formula)
    def dsa_ext_contribution_from_price_and_exchange_rate_changes_formula(scenario: str, time_period: int) -> float | str | None:
        if scenario == 'Baseline':
            return as_measure(xl_add(xl_div(xl_mul(xl_neg(xl_mul(xl_div(dsa_ext_gdp_deflator_in_us_dollar_terms_change_in_percent[scenario, time_period], 100), xl_add(1, xl_div(dsa_ext_real_gdp_growth_in_percent[scenario, time_period], 100)))), dsa_ext_external_debt_nominal_1[scenario, time_period - 1]), dsa_ext_denominator_1_g_g[scenario, time_period]), xl_div(xl_mul(xl_mul(xl_mul(dsa_ext_share_of_local_currency_denominated_external_debt_to_total_external_debt_baseline[scenario, time_period - 1], xl_div(xl_neg(dsa_ext_depreciation_of_nc_depreciation[scenario, time_period]), 100)), xl_add(1, xl_div(dsa_ext_effective_interest_rate_percent_4[scenario, time_period], 100))), dsa_ext_external_debt_nominal_1[scenario, time_period - 1]), dsa_ext_denominator_1_g_g[scenario, time_period])))
        return as_measure(xl_add(xl_div(xl_mul(xl_neg(xl_mul(xl_div(dsa_ext_gdp_deflator_in_us_dollar_terms_change_in_percent[scenario, time_period], 100), xl_add(1, xl_div(dsa_ext_real_gdp_growth_in_percent[scenario, time_period], 100)))), dsa_ext_external_debt_nominal_1[scenario, time_period - 1]), dsa_ext_denominator_1_g_g[scenario, time_period]), xl_div(xl_mul(xl_mul(xl_mul(dsa_ext_share_of_local_currency_denominated_external_debt_to_total_external_debt[scenario, time_period - 1], xl_div(xl_neg(dsa_ext_depreciation_of_nc_depreciation[scenario, time_period]), 100)), xl_add(1, xl_div(dsa_ext_effective_interest_rate_percent_4[scenario, time_period], 100))), dsa_ext_external_debt_nominal_1[scenario, time_period - 1]), dsa_ext_denominator_1_g_g[scenario, time_period])))

    dsa_ext_contribution_from_price_and_exchange_rate_changes = CoordinateReader('dsa_ext_contribution_from_price_and_exchange_rate_changes', data.DSA_EXT_CONTRIBUTION_FROM_PRICE_AND_EXCHANGE_RATE_CHANGES.required, dsa_ext_contribution_from_price_and_exchange_rate_changes_formula)
    def dsa_ext_residual_3_formula(scenario: str, time_period: int) -> float | str | None:
        if scenario == 'A1':
            return as_measure(dsa_ext_residual_3['Baseline', time_period])
        elif scenario == 'Baseline':
            return as_measure(xl_sub(dsa_ext_change_in_external_debt[scenario, time_period], dsa_ext_identified_net_debt_creating_flows[scenario, time_period]))
        return as_measure(xl_div(xl_mul(dsa_ext_residual_3['Baseline', time_period], dsa_ext_nominal_gdp_million_of_us_dollars['Baseline', time_period]), dsa_ext_nominal_gdp_million_of_us_dollars[scenario, time_period]))

    dsa_ext_residual_3 = CoordinateReader('dsa_ext_residual_3', data.DSA_EXT_RESIDUAL_3.required, dsa_ext_residual_3_formula)
    def dsa_ext_effective_interest_rate_percent_4_formula(scenario: str, time_period: int) -> float | str | None:
        if scenario == 'Baseline':
            return as_measure((xl_mul(xl_div(macro_debt_total_ext_debt_interest_due_include_interest[time_period], xl_mul(xl_div(dsa_ext_external_debt_nominal_1[scenario, time_period - 1], 100), dsa_ext_nominal_gdp_million_of_us_dollars[scenario, time_period - 1])), 100) if xl_bool(xl_isnumber(lambda: macro_debt_total_ext_debt_interest_due_include_interest[time_period])) else '...'))
        return as_measure(dsa_ext_effective_rate[scenario, time_period])

    dsa_ext_effective_interest_rate_percent_4 = CoordinateReader('dsa_ext_effective_interest_rate_percent_4', data.DSA_EXT_EFFECTIVE_INTEREST_RATE_PERCENT_4.required, dsa_ext_effective_interest_rate_percent_4_formula)
    def dsa_ext_nominal_debt_baseline_formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure(xl_mul(xl_div(dsa_ext_external_debt_nominal_1['Baseline', time_period], 100), dsa_ext_nominal_gdp_million_of_us_dollars['Baseline', time_period]))

    dsa_ext_nominal_debt_baseline = CoordinateReader('dsa_ext_nominal_debt_baseline', data.DSA_EXT_NOMINAL_DEBT_BASELINE.required, dsa_ext_nominal_debt_baseline_formula)
    def dsa_ext_increase_baseline_formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure(xl_sub(dsa_ext_nominal_debt_baseline[scenario, time_period], dsa_ext_nominal_debt_baseline[scenario, time_period - 1]))

    dsa_ext_increase_baseline = CoordinateReader('dsa_ext_increase_baseline', data.DSA_EXT_INCREASE_BASELINE.required, dsa_ext_increase_baseline_formula)
    def dsa_ext_nominal_debt_stress_formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure(xl_mul(xl_div(dsa_ext_external_debt_nominal_1[scenario, time_period], 100), dsa_ext_nominal_gdp_million_of_us_dollars[scenario, time_period]))

    dsa_ext_nominal_debt_stress = CoordinateReader('dsa_ext_nominal_debt_stress', data.DSA_EXT_NOMINAL_DEBT_STRESS.required, dsa_ext_nominal_debt_stress_formula)
    def dsa_ext_increase_stress_formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure(xl_sub(dsa_ext_nominal_debt_stress[scenario, time_period], dsa_ext_nominal_debt_stress[scenario, time_period - 1]))

    dsa_ext_increase_stress = CoordinateReader('dsa_ext_increase_stress', data.DSA_EXT_INCREASE_STRESS.required, dsa_ext_increase_stress_formula)
    def dsa_ext_residual_gross_borrowing_formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure(xl_sub(dsa_ext_increase_stress[scenario, time_period], dsa_ext_increase_baseline[scenario, time_period]))

    dsa_ext_residual_gross_borrowing = CoordinateReader('dsa_ext_residual_gross_borrowing', data.DSA_EXT_RESIDUAL_GROSS_BORROWING.required, dsa_ext_residual_gross_borrowing_formula)
    def dsa_ext_o_w_interest_stress_formula(scenario: str, time_period: int) -> float | str | None:
        if scenario == 'A1':
            return as_measure(pv_stress_interest['Key variables at historical average', time_period])
        elif scenario == 'B1':
            return as_measure(pv_stress_bounds_interest['Bounds Test 1: Real GDP Growth Shock', time_period])
        elif scenario == 'B3':
            return as_measure(pv_stress_bounds_interest['Bound Test 2: Exports Shock', time_period])
        elif scenario == 'B4':
            return as_measure(pv_stress_bounds_interest['Bound Test 4: Other Flows Shock', time_period])
        elif scenario == 'B5':
            return as_measure(pv_stress_bounds_interest['Bounds Test 5: Exchange Rate Shock', time_period])
        elif scenario == 'B6_mkt':
            return as_measure(xl_add(pv_stress_bounds_interest['Bounds Test 6: Combined Shock for Market Access Countries', time_period], dsa_ext_o_w_interest_additional_borrowing[scenario, time_period]))
        elif scenario == 'B6_nonmkt':
            return as_measure(pv_stress_bounds_interest['Bounds Test 6: Combined Shock for Non-Market Access Countries', time_period])
