    dsa_ext_imports = CoordinateReader('dsa_ext_imports', data.DSA_EXT_IMPORTS.required, dsa_ext_imports_formula)
    def dsa_ext_net_current_transfers_negative_inflow_formula(scenario: str, time_period: int) -> float | str | None:
        if scenario == 'B4' and time_period == 2025:
            return as_measure((xl_max(xl_neg(xl_sub(dsa_ext_historical_statistics[scenario, 'Current official transfers in percent of GDP', 'Historical average'], xl_mul(b4_otherflows_ext_ii_key_macroeconomic_assumptions, dsa_ext_historical_statistics[scenario, 'Current official transfers in percent of GDP', 'Standard deviation']))), xl_add(dsa_ext_net_current_transfers_negative_inflow['Baseline', time_period], xl_mul(b4_otherflows_ext_ii_key_macroeconomic_assumptions, dsa_ext_historical_statistics[scenario, 'Current official transfers in percent of GDP', 'Standard deviation']))) if xl_bool(xl_eq(dsa_ext_standard_test_current_transfers_rule, input6_standard_size_threshold_option_whichever_is_lower)) else (xl_neg(xl_sub(dsa_ext_historical_statistics[scenario, 'Current official transfers in percent of GDP', 'Historical average'], xl_mul(b4_otherflows_ext_ii_key_macroeconomic_assumptions, dsa_ext_historical_statistics[scenario, 'Current official transfers in percent of GDP', 'Standard deviation']))) if xl_bool(xl_eq(dsa_ext_standard_test_current_transfers_rule, input6_standard_size_threshold_option_historical_average_only)) else xl_add(dsa_ext_net_current_transfers_negative_inflow['Baseline', time_period], xl_mul(b4_otherflows_ext_ii_key_macroeconomic_assumptions, dsa_ext_historical_statistics[scenario, 'Current official transfers in percent of GDP', 'Standard deviation'])))))
        elif scenario == 'B4' and time_period == 2026:
            return as_measure((xl_neg(xl_sub(dsa_ext_historical_statistics[scenario, 'Current official transfers in percent of GDP', 'Historical average'], xl_mul(b4_otherflows_ext_ii_key_macroeconomic_assumptions, dsa_ext_historical_statistics[scenario, 'Current official transfers in percent of GDP', 'Standard deviation']))) if xl_bool(xl_eq(dsa_ext_net_current_transfers_negative_inflow[scenario, time_period - 1], xl_neg(xl_sub(dsa_ext_historical_statistics[scenario, 'Current official transfers in percent of GDP', 'Historical average'], xl_mul(b4_otherflows_ext_ii_key_macroeconomic_assumptions, dsa_ext_historical_statistics[scenario, 'Current official transfers in percent of GDP', 'Standard deviation']))))) else xl_add(dsa_ext_net_current_transfers_negative_inflow['Baseline', time_period], xl_mul(b4_otherflows_ext_ii_key_macroeconomic_assumptions, dsa_ext_historical_statistics[scenario, 'Current official transfers in percent of GDP', 'Standard deviation']))))
        elif scenario == 'B6_mkt' and time_period == 2025:
            return as_measure((xl_max(xl_neg(xl_sub(dsa_ext_historical_statistics[scenario, 'Current official transfers in percent of GDP', 'Historical average'], xl_mul(b6_combo_mkt_ext_y1_includes_both_public_nominal_debt_baseline, dsa_ext_historical_statistics[scenario, 'Current official transfers in percent of GDP', 'Standard deviation']))), xl_add(dsa_ext_net_current_transfers_negative_inflow['Baseline', time_period], xl_mul(b6_combo_mkt_ext_y1_includes_both_public_nominal_debt_baseline, dsa_ext_historical_statistics[scenario, 'Current official transfers in percent of GDP', 'Standard deviation']))) if xl_bool(xl_eq(dsa_ext_standard_test_current_transfers_rule_b6_mkt, input6_standard_size_threshold_option_whichever_is_lower)) else (xl_neg(xl_sub(dsa_ext_historical_statistics[scenario, 'Current official transfers in percent of GDP', 'Historical average'], xl_mul(b6_combo_mkt_ext_y1_includes_both_public_nominal_debt_baseline, dsa_ext_historical_statistics[scenario, 'Current official transfers in percent of GDP', 'Standard deviation']))) if xl_bool(xl_eq(dsa_ext_standard_test_current_transfers_rule_b6_mkt, input6_standard_size_threshold_option_historical_average_only)) else xl_add(dsa_ext_net_current_transfers_negative_inflow['Baseline', time_period], xl_mul(b6_combo_mkt_ext_y1_includes_both_public_nominal_debt_baseline, dsa_ext_historical_statistics[scenario, 'Current official transfers in percent of GDP', 'Standard deviation'])))))
        elif scenario == 'B6_mkt' and time_period == 2026:
            return as_measure((xl_neg(xl_sub(dsa_ext_historical_statistics[scenario, 'Current official transfers in percent of GDP', 'Historical average'], xl_mul(b6_combo_mkt_ext_y1_includes_both_public_nominal_debt_baseline, dsa_ext_historical_statistics[scenario, 'Current official transfers in percent of GDP', 'Standard deviation']))) if xl_bool(xl_eq(dsa_ext_net_current_transfers_negative_inflow[scenario, time_period - 1], xl_neg(xl_sub(dsa_ext_historical_statistics[scenario, 'Current official transfers in percent of GDP', 'Historical average'], xl_mul(b6_combo_mkt_ext_y1_includes_both_public_nominal_debt_baseline, dsa_ext_historical_statistics[scenario, 'Current official transfers in percent of GDP', 'Standard deviation']))))) else xl_add(dsa_ext_net_current_transfers_negative_inflow['Baseline', time_period], xl_mul(b6_combo_mkt_ext_y1_includes_both_public_nominal_debt_baseline, dsa_ext_historical_statistics[scenario, 'Current official transfers in percent of GDP', 'Standard deviation']))))
        elif scenario == 'B6_nonmkt' and time_period == 2025:
            return as_measure((xl_max(xl_neg(xl_sub(dsa_ext_historical_statistics[scenario, 'Current official transfers in percent of GDP', 'Historical average'], xl_mul(b6_combo_nonmkt_ext_y7_long_run_constant_balance_that_stabilizes, dsa_ext_historical_statistics[scenario, 'Current official transfers in percent of GDP', 'Standard deviation']))), xl_add(dsa_ext_net_current_transfers_negative_inflow['Baseline', time_period], xl_mul(b6_combo_nonmkt_ext_y7_long_run_constant_balance_that_stabilizes, dsa_ext_historical_statistics[scenario, 'Current official transfers in percent of GDP', 'Standard deviation']))) if xl_bool(xl_eq(dsa_ext_standard_test_current_transfers_rule_b6_nonmkt, input6_standard_size_threshold_option_whichever_is_lower)) else (xl_neg(xl_sub(dsa_ext_historical_statistics[scenario, 'Current official transfers in percent of GDP', 'Historical average'], xl_mul(b6_combo_nonmkt_ext_y7_long_run_constant_balance_that_stabilizes, dsa_ext_historical_statistics[scenario, 'Current official transfers in percent of GDP', 'Standard deviation']))) if xl_bool(xl_eq(dsa_ext_standard_test_current_transfers_rule_b6_nonmkt, input6_standard_size_threshold_option_historical_average_only)) else xl_add(dsa_ext_net_current_transfers_negative_inflow['Baseline', time_period], xl_mul(b6_combo_nonmkt_ext_y7_long_run_constant_balance_that_stabilizes, dsa_ext_historical_statistics[scenario, 'Current official transfers in percent of GDP', 'Standard deviation'])))))
        elif scenario == 'B6_nonmkt' and time_period == 2026:
            return as_measure((xl_neg(xl_sub(dsa_ext_historical_statistics[scenario, 'Current official transfers in percent of GDP', 'Historical average'], xl_mul(b6_combo_nonmkt_ext_y7_long_run_constant_balance_that_stabilizes, dsa_ext_historical_statistics[scenario, 'Current official transfers in percent of GDP', 'Standard deviation']))) if xl_bool(xl_eq(dsa_ext_net_current_transfers_negative_inflow[scenario, time_period - 1], xl_neg(xl_sub(dsa_ext_historical_statistics[scenario, 'Current official transfers in percent of GDP', 'Historical average'], xl_mul(b6_combo_nonmkt_ext_y7_long_run_constant_balance_that_stabilizes, dsa_ext_historical_statistics[scenario, 'Current official transfers in percent of GDP', 'Standard deviation']))))) else xl_add(dsa_ext_net_current_transfers_negative_inflow['Baseline', time_period], xl_mul(b6_combo_nonmkt_ext_y7_long_run_constant_balance_that_stabilizes, dsa_ext_historical_statistics[scenario, 'Current official transfers in percent of GDP', 'Standard deviation']))))
        elif scenario == 'Baseline' and time_period == 2024:
            return as_measure(xl_mul(xl_div(xl_neg(macro_debt_us_dollars_by_year_k[time_period]), macro_debt_gdp_current_prices_u_s_dollars[time_period]), 100))
        elif scenario == 'Baseline' and time_period in (2014, 2015, 2016, 2017, 2018, 2019, 2020, 2021, 2022, 2023):
            return as_measure((xl_mul(xl_div(xl_neg(macro_debt_us_dollars_by_year_k[time_period]), macro_debt_gdp_current_prices_u_s_dollars[time_period]), 100) if xl_bool(xl_isnumber(lambda: xl_div(macro_debt_us_dollars_by_year_k[time_period], macro_debt_gdp_current_prices_u_s_dollars[time_period]))) else '...'))
        elif scenario == 'Baseline' and time_period in (2025, 2026, 2027, 2028, 2029, 2030, 2031, 2032, 2033, 2034, 2035, 2036, 2037, 2038, 2039, 2040, 2041, 2042, 2043, 2044):
            return as_measure(xl_mul(xl_div(xl_neg(macro_debt_us_dollars_by_year_v[time_period]), macro_debt_gdp_current_prices_u_s_dollars[time_period]), 100))
        return as_measure(xl_div(xl_mul(dsa_ext_net_current_transfers_negative_inflow['Baseline', time_period], dsa_ext_nominal_gdp_million_of_us_dollars['Baseline', time_period]), dsa_ext_nominal_gdp_million_of_us_dollars[scenario, time_period]))

    dsa_ext_net_current_transfers_negative_inflow = CoordinateReader('dsa_ext_net_current_transfers_negative_inflow', data.DSA_EXT_NET_CURRENT_TRANSFERS_NEGATIVE_INFLOW.required, dsa_ext_net_current_transfers_negative_inflow_formula)
