@publish(data.DSA_EXT_REVENUE_GDP_STRESS_STRESS.schema, cells=data.DSA_EXT_REVENUE_GDP_STRESS_STRESS.cells)
def dsa_ext_revenue_gdp_stress_stress(*, dsa_ext_government_revenues_excluding_grants_in_percent_of_gdp: data.Series[float | str | None], leftover_us_gdp_deflator: data.Series[float | str | None], c3_commodity_ext_ii_key_macroeconomic_assumptions: int | str) -> data.Series[float | str | None]:
    """Computes stressed external revenue-to-GDP values from baseline revenue, a US GDP deflator residual, and a commodity-price assumption key.

    Derives scenario- and year-keyed stress adjustments for external revenue/GDP in the LIC-DSF template.

    Args:
        dsa_ext_government_revenues_excluding_grants_in_percent_of_gdp: Baseline government revenues excluding grants in percent of GDP, as a typed series keyed by scenario and year.
        leftover_us_gdp_deflator: Residual US GDP deflator as a typed series keyed by scenario, used in the stress adjustment applied to baseline revenue.
        c3_commodity_ext_ii_key_macroeconomic_assumptions: C3 commodity external-II macroeconomic assumption key as an integer or string scalar, selecting the offsets and divisor in the 2028–2030 adjustment.

    Returns:
        Revenue/GDP (stress) as a typed series keyed by scenario and years from row 8 of C3_Commodity prices_ext.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        if time_period == 2028:
            return as_measure(xl_sub(dsa_ext_government_revenues_excluding_grants_in_percent_of_gdp['Baseline', time_period], xl_div(xl_mul(leftover_us_gdp_deflator[scenario], xl_sub(c3_commodity_ext_ii_key_macroeconomic_assumptions, 3)), xl_sub(c3_commodity_ext_ii_key_macroeconomic_assumptions, 2))))
        elif time_period == 2029:
            return as_measure(xl_sub(dsa_ext_government_revenues_excluding_grants_in_percent_of_gdp['Baseline', time_period], xl_div(xl_mul(leftover_us_gdp_deflator[scenario], xl_sub(c3_commodity_ext_ii_key_macroeconomic_assumptions, 4)), xl_sub(c3_commodity_ext_ii_key_macroeconomic_assumptions, 2))))
        elif time_period == 2030:
            return as_measure(xl_sub(dsa_ext_government_revenues_excluding_grants_in_percent_of_gdp['Baseline', time_period], xl_div(xl_mul(leftover_us_gdp_deflator[scenario], xl_sub(c3_commodity_ext_ii_key_macroeconomic_assumptions, 5)), xl_sub(c3_commodity_ext_ii_key_macroeconomic_assumptions, 2))))
        return as_measure(xl_sub(dsa_ext_government_revenues_excluding_grants_in_percent_of_gdp['Baseline', time_period], leftover_us_gdp_deflator[scenario]))

    return data.DSA_EXT_REVENUE_GDP_STRESS_STRESS.collect(evaluate(formula, data.DSA_EXT_REVENUE_GDP_STRESS_STRESS.required))

@publish(data.DSA_EXT_OF_WHICH_PUBLIC_AND_PUBLICLY_GUARANTEED_PPG.schema, cells=data.DSA_EXT_OF_WHICH_PUBLIC_AND_PUBLICLY_GUARANTEED_PPG.cells)
def dsa_ext_of_which_public_and_publicly_guaranteed_ppg(*, macro_debt_gdp_current_prices_u_s_dollars: data.Series[float | str | None], macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc: data.Series[float | str | None], macro_debt_total_public_ext_debt: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute the external debt "of which: public and publicly guaranteed (PPG)" ratio, expressing PPG external debt as a share of GDP in percent.

    Derive the of-which PPG debt-to-GDP series on the Chart Data external-debt ladder by converting national-currency external debt to a percent-of-GDP measure.

    Args:
        macro_debt_gdp_current_prices_u_s_dollars: data.Series of GDP at current prices in U.S. dollars, keyed by scenario and projected year; blank or template-snapshot cells appear as str or None.
        macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc: data.Series of the exchange rate in national currency per U.S. dollar, keyed by scenario and projected year; blank or template-snapshot cells appear as str or None.
        macro_debt_total_public_ext_debt: data.Series of total public external debt in the corresponding units, keyed by scenario and projected year; blank or template-snapshot cells appear as str or None.

    Returns:
        data.Series[float | str | None] of the of-which public and publicly guaranteed (PPG) external debt ratio in percent of GDP, keyed by scenario and year, carrying None/str where the underlying inputs are blank or non-numeric.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure((xl_div(xl_mul(100, macro_debt_total_public_ext_debt[time_period]), xl_mul(macro_debt_gdp_current_prices_u_s_dollars[time_period], macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc[time_period])) if xl_bool(xl_isnumber(lambda: xl_div(macro_debt_total_public_ext_debt[time_period], xl_mul(macro_debt_gdp_current_prices_u_s_dollars[time_period], macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc[time_period])))) else '…'))

    return data.DSA_EXT_OF_WHICH_PUBLIC_AND_PUBLICLY_GUARANTEED_PPG.collect(evaluate(formula, data.DSA_EXT_OF_WHICH_PUBLIC_AND_PUBLICLY_GUARANTEED_PPG.required))

