        pv_resfin_add_output_cumulative_selected_by_t_g_0=data.PV_RESFIN_ADD_OUTPUT_CUMULATIVE_SELECTED_BY_T_G_0.collect((coord, pv_resfin_add_output_cumulative_selected_by_t_g_0[coord]) for coord in data.PV_RESFIN_ADD_OUTPUT_CUMULATIVE_SELECTED_BY_T_G_0.required),
        pv_resfin_add_output_cumulative_selected_by_t_m_condition=data.PV_RESFIN_ADD_OUTPUT_CUMULATIVE_SELECTED_BY_T_M_CONDITION.collect((coord, pv_resfin_add_output_cumulative_selected_by_t_m_condition[coord]) for coord in data.PV_RESFIN_ADD_OUTPUT_CUMULATIVE_SELECTED_BY_T_M_CONDITION.required),
