@publish(data.DSA_PUB_TOTAL_PUBLIC_EXTERNAL_DEBT.schema, cells=data.DSA_PUB_TOTAL_PUBLIC_EXTERNAL_DEBT.cells)
def dsa_pub_total_public_external_debt(*, dsa_pub_exchange_rate_lc_per_us_dollar: data.Series[float | str | None], macro_debt_exchange_rate_national_currency_per_u_s_dollar: data.Series[float | str | None], macro_debt_total_public_ext_debt: data.Series[float | str | None], pv_resfin_pub_output_stock_of_new_forex_debt_in_usd: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute total public external debt in US dollars across the LIC-DSF scenario ladder.

    Provides the IDA21 DSA public-debt stress-chart series by converting local-currency public external debt to USD and adding residual-financing stock under each baseline, bound-test, and tailored-stress scenario.

    Args:
        dsa_pub_exchange_rate_lc_per_us_dollar: Local-currency-per-US-dollar exchange rate series for the public DSA, keyed by scenario and year.
        macro_debt_exchange_rate_national_currency_per_u_s_dollar: National-currency-per-US-dollar exchange-rate series from the macro-debt data, keyed by year.
        macro_debt_total_public_ext_debt: Total public external debt series (B1_GDP_pub) from the macro-debt data, keyed by year.
        pv_resfin_pub_output_stock_of_new_forex_debt_in_usd: Stock of new foreign-currency debt in USD from the public residual-financing PV block, keyed by external PPG medium- and long-term scenario and year.

    Returns:
        A data series of total public external debt in US dollars (float, str, or None per cell), keyed by scenario and year.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        if time_period == 2024:
            return as_measure(xl_mul(xl_div(macro_debt_total_public_ext_debt[time_period], macro_debt_exchange_rate_national_currency_per_u_s_dollar[time_period]), dsa_pub_exchange_rate_lc_per_us_dollar[scenario, time_period]))
        elif scenario == 'B1' and time_period >= 2025:
            return as_measure(xl_mul(xl_add(xl_div(macro_debt_total_public_ext_debt[time_period], macro_debt_exchange_rate_national_currency_per_u_s_dollar[time_period]), pv_resfin_pub_output_stock_of_new_forex_debt_in_usd['External PPG medium and long-term', 'Bounds Test 1: Real GDP Growth Shock', time_period]), dsa_pub_exchange_rate_lc_per_us_dollar[scenario, time_period]))
        elif scenario == 'B2_mkt' and time_period >= 2025:
            return as_measure(xl_mul(xl_add(xl_div(macro_debt_total_public_ext_debt[time_period], macro_debt_exchange_rate_national_currency_per_u_s_dollar[time_period]), pv_resfin_pub_output_stock_of_new_forex_debt_in_usd['External PPG medium and long-term', 'Bounds Test 2: Primary Balance Shock for Market Access Countries', time_period]), dsa_pub_exchange_rate_lc_per_us_dollar[scenario, time_period]))
        elif scenario == 'B6_mkt' and time_period >= 2025:
            return as_measure(xl_mul(xl_add(xl_div(macro_debt_total_public_ext_debt[time_period], macro_debt_exchange_rate_national_currency_per_u_s_dollar[time_period]), pv_resfin_pub_output_stock_of_new_forex_debt_in_usd['External PPG medium and long-term', 'Bounds Test 6: Combined Shock for Market Access Countries', time_period]), dsa_pub_exchange_rate_lc_per_us_dollar[scenario, time_period]))
        elif scenario == 'C1' and time_period >= 2025:
            return as_measure(xl_mul(xl_add(xl_div(macro_debt_total_public_ext_debt[time_period], macro_debt_exchange_rate_national_currency_per_u_s_dollar[time_period]), pv_resfin_pub_output_stock_of_new_forex_debt_in_usd['External PPG medium and long-term', 'Tailored Stress Test 1: Contingent Liability Shock', time_period]), dsa_pub_exchange_rate_lc_per_us_dollar[scenario, time_period]))
        elif scenario == 'B2_nonmkt' and time_period >= 2025:
            return as_measure(xl_mul(xl_add(xl_div(macro_debt_total_public_ext_debt[time_period], macro_debt_exchange_rate_national_currency_per_u_s_dollar[time_period]), pv_resfin_pub_output_stock_of_new_forex_debt_in_usd['External PPG medium and long-term', 'Bounds Test 2: Primary Balance Shock for non-market access countries', time_period]), dsa_pub_exchange_rate_lc_per_us_dollar[scenario, time_period]))
        elif scenario == 'B5' and time_period >= 2025:
            return as_measure(xl_mul(xl_add(xl_div(macro_debt_total_public_ext_debt[time_period], macro_debt_exchange_rate_national_currency_per_u_s_dollar[time_period]), pv_resfin_pub_output_stock_of_new_forex_debt_in_usd['External PPG medium and long-term', 'Bounds Test 5: Exchange Rate Shock', time_period]), dsa_pub_exchange_rate_lc_per_us_dollar[scenario, time_period]))
        elif scenario == 'B6_nonmkt' and time_period >= 2025:
            return as_measure(xl_mul(xl_add(xl_div(macro_debt_total_public_ext_debt[time_period], macro_debt_exchange_rate_national_currency_per_u_s_dollar[time_period]), pv_resfin_pub_output_stock_of_new_forex_debt_in_usd['External PPG medium and long-term', 'Bounds Test 6: Combined Shock for Non-Market Access Countries', time_period]), dsa_pub_exchange_rate_lc_per_us_dollar[scenario, time_period]))
        elif scenario == 'C2' and time_period >= 2025:
            return as_measure(xl_mul(xl_add(xl_div(macro_debt_total_public_ext_debt[time_period], macro_debt_exchange_rate_national_currency_per_u_s_dollar[time_period]), pv_resfin_pub_output_stock_of_new_forex_debt_in_usd['External PPG medium and long-term', 'CL1: Natural disaster', time_period]), dsa_pub_exchange_rate_lc_per_us_dollar[scenario, time_period]))
        elif scenario == 'C3' and time_period >= 2025:
            return as_measure(xl_mul(xl_add(xl_div(macro_debt_total_public_ext_debt[time_period], macro_debt_exchange_rate_national_currency_per_u_s_dollar[time_period]), pv_resfin_pub_output_stock_of_new_forex_debt_in_usd['External PPG medium and long-term', 'Tailored Stress Test 3. Commodity Price shock - Public', time_period]), dsa_pub_exchange_rate_lc_per_us_dollar[scenario, time_period]))
        return as_measure(xl_mul(xl_add(xl_div(macro_debt_total_public_ext_debt[time_period], macro_debt_exchange_rate_national_currency_per_u_s_dollar[time_period]), pv_resfin_pub_output_stock_of_new_forex_debt_in_usd['External PPG medium and long-term', 'Key variables at historical average', time_period]), dsa_pub_exchange_rate_lc_per_us_dollar[scenario, time_period]))

    return data.DSA_PUB_TOTAL_PUBLIC_EXTERNAL_DEBT.collect(evaluate(formula, data.DSA_PUB_TOTAL_PUBLIC_EXTERNAL_DEBT.required))

@publish(data.DSA_PUB_PRIMARY_DEFICIT_LOCAL_CURRENCY.schema, cells=data.DSA_PUB_PRIMARY_DEFICIT_LOCAL_CURRENCY.cells)
def dsa_pub_primary_deficit_local_currency(*, dsa_pub_primary_deficit: data.Series[float | str | None], dsa_pub_nominal_gdp_local_currency: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Convert the public primary deficit from percent of GDP to local-currency units.

    Scale the primary-deficit ratio (in percent) by nominal GDP in local currency to obtain the deficit denominated in local currency.

    Args:
        dsa_pub_primary_deficit: Primary deficit (B1_GDP_pub) as a percent-of-GDP series keyed by scenario and projection year, holding floats, strings, or blanks.
        dsa_pub_nominal_gdp_local_currency: Nominal GDP in local currency, keyed by scenario and projection year, holding floats, strings, or blanks.

    Returns:
        A data.Series of the primary deficit in local currency over scenario and year coordinates, with floats, strings, or blanks preserved from the inputs.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure(xl_mul(xl_div(dsa_pub_primary_deficit[scenario, time_period], 100), dsa_pub_nominal_gdp_local_currency[scenario, time_period]))

    return data.DSA_PUB_PRIMARY_DEFICIT_LOCAL_CURRENCY.collect(evaluate(formula, data.DSA_PUB_PRIMARY_DEFICIT_LOCAL_CURRENCY.required))

@publish(data.DSA_PUB_OTHER_DEBT_CREATING_FLOWS.schema, cells=data.DSA_PUB_OTHER_DEBT_CREATING_FLOWS.cells)
def dsa_pub_other_debt_creating_flows(*, baseline_pub_other_identified_debt_creating_flows: data.Series[float | str | None], baseline_pub_nominal_gdp_lc: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute public other debt-creating flows from baseline percent-of-GDP inputs.

    Derive the local-currency public other debt-creating flow series for DSA projections.

    Args:
        baseline_pub_other_identified_debt_creating_flows: Baseline other identified public debt-creating flows expressed as a percent-of-GDP series over scenario and projection-year coordinates.
        baseline_pub_nominal_gdp_lc: Baseline nominal GDP in local currency, keyed by the same scenario and projection-year coordinates.

    Returns:
        A data.Series[float | str | None] of public other debt-creating flows in local currency, matching the scenario and year coordinates of the inputs.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure(xl_mul(xl_div(baseline_pub_other_identified_debt_creating_flows[time_period], 100), baseline_pub_nominal_gdp_lc[time_period]))

    return data.DSA_PUB_OTHER_DEBT_CREATING_FLOWS.collect(evaluate(formula, data.DSA_PUB_OTHER_DEBT_CREATING_FLOWS.required))

@publish(data.DSA_PUB_PV_OF_PUBLIC_SECTOR_EXTERNAL_DEBT_END_OF_PERIOD.schema, cells=data.DSA_PUB_PV_OF_PUBLIC_SECTOR_EXTERNAL_DEBT_END_OF_PERIOD.cells)
def dsa_pub_pv_of_public_sector_external_debt_end_of_period(*, dsa_pub_exchange_rate_lc_per_us_dollar: data.Series[float | str | None], baseline_pub_exchange_rate_lc_per_us_dollar: data.Series[float | str | None], macro_debt_pv_of_public_sector_ext_debt_end_of_period: data.Series[float | str | None], pv_resfin_pub_output_new_forex_borrowing_gross_usd: data.Series[float | str | None], pv_resfin_pub_output_pv_of_new_forex_debt_in_usd: data.Series[float | str | None], pv_resfin_add_output_pv_of_new_forex_debt_in_usd: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Computes the scenario- and year-indexed present value of public sector external debt at end of period.

    Projects end-of-period PV of public sector external debt for each DSA scenario by restating baseline PV into local currency, adding scenario-specific residual-financing new borrowing, and converting at the scenario exchange rate.

    Args:
        dsa_pub_exchange_rate_lc_per_us_dollar: Public exchange rate in local currency per U.S. dollar for the scenario being projected, as a named-axis series over scenario and year coordinates.
        baseline_pub_exchange_rate_lc_per_us_dollar: Baseline public exchange rate in local currency per U.S. dollar, as a named-axis series over year coordinates, used to restate the macro-debt PV before applying the scenario rate.
        macro_debt_pv_of_public_sector_ext_debt_end_of_period: Workbook macro-debt series holding the present value of public sector external debt at end of period, as a named-axis series over year coordinates.
        pv_resfin_pub_output_new_forex_borrowing_gross_usd: Residual-financing output series for gross new foreign-currency borrowing in U.S. dollars, as a named-axis series over external-debt instrument, stress-scenario label, and year coordinates.
        pv_resfin_pub_output_pv_of_new_forex_debt_in_usd: Residual-financing output series for the present value of new foreign-currency debt in U.S. dollars, as a named-axis series over external-debt instrument, stress-scenario label, and year coordinates.
        pv_resfin_add_output_pv_of_new_forex_debt_in_usd: Additional residual-financing output series for the present value of new foreign-currency debt in U.S. dollars, as a named-axis series over external-debt instrument, stress-scenario label, and year coordinates.

    Returns:
        Scenario- and year-indexed series of the present value of public sector external debt at end of period, keyed by scenario and the projection years taken from row 7; values are numeric, text, or null where the workbook leaves the cell blank.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        if scenario == 'B2_mkt' and time_period == 2025:
            return as_measure(xl_mul(xl_add(xl_div(macro_debt_pv_of_public_sector_ext_debt_end_of_period[time_period], baseline_pub_exchange_rate_lc_per_us_dollar[time_period]), pv_resfin_pub_output_pv_of_new_forex_debt_in_usd['External PPG medium and long-term', 'Bounds Test 2: Primary Balance Shock for Market Access Countries', time_period]), dsa_pub_exchange_rate_lc_per_us_dollar[scenario, time_period]))
        elif time_period == 2024:
            return as_measure(xl_div(xl_mul(macro_debt_pv_of_public_sector_ext_debt_end_of_period[time_period], dsa_pub_exchange_rate_lc_per_us_dollar[scenario, time_period]), baseline_pub_exchange_rate_lc_per_us_dollar[time_period]))
        elif scenario == 'B2_mkt' and time_period >= 2026:
            return as_measure(xl_mul(xl_add(xl_add(xl_div(macro_debt_pv_of_public_sector_ext_debt_end_of_period[time_period], baseline_pub_exchange_rate_lc_per_us_dollar[time_period]), pv_resfin_pub_output_pv_of_new_forex_debt_in_usd['External PPG medium and long-term', 'Bounds Test 2: Primary Balance Shock for Market Access Countries', time_period]), pv_resfin_add_output_pv_of_new_forex_debt_in_usd['External PPG medium and long-term', 'Bounds Test 2: Primary Balance Shock for Market Access Countries', time_period]), dsa_pub_exchange_rate_lc_per_us_dollar[scenario, time_period]))
        elif scenario == 'B1' and time_period >= 2025:
            return as_measure(xl_mul(xl_add(xl_div(macro_debt_pv_of_public_sector_ext_debt_end_of_period[time_period], baseline_pub_exchange_rate_lc_per_us_dollar[time_period]), pv_resfin_pub_output_pv_of_new_forex_debt_in_usd['External PPG medium and long-term', 'Bounds Test 1: Real GDP Growth Shock', time_period]), dsa_pub_exchange_rate_lc_per_us_dollar[scenario, time_period]))
        elif scenario == 'B6_mkt' and time_period >= 2025:
            return as_measure(xl_mul(xl_add(xl_div(macro_debt_pv_of_public_sector_ext_debt_end_of_period[time_period], baseline_pub_exchange_rate_lc_per_us_dollar[time_period]), pv_resfin_pub_output_pv_of_new_forex_debt_in_usd['External PPG medium and long-term', 'Bounds Test 6: Combined Shock for Market Access Countries', time_period]), dsa_pub_exchange_rate_lc_per_us_dollar[scenario, time_period]))
        elif scenario == 'C1' and time_period >= 2025:
            return as_measure(xl_mul(xl_add(xl_div(macro_debt_pv_of_public_sector_ext_debt_end_of_period[time_period], baseline_pub_exchange_rate_lc_per_us_dollar[time_period]), pv_resfin_pub_output_pv_of_new_forex_debt_in_usd['External PPG medium and long-term', 'Tailored Stress Test 1: Contingent Liability Shock', time_period]), dsa_pub_exchange_rate_lc_per_us_dollar[scenario, time_period]))
        elif scenario == 'B2_nonmkt' and time_period >= 2025:
            return as_measure(xl_mul(xl_add(xl_div(macro_debt_pv_of_public_sector_ext_debt_end_of_period[time_period], baseline_pub_exchange_rate_lc_per_us_dollar[time_period]), pv_resfin_pub_output_pv_of_new_forex_debt_in_usd['External PPG medium and long-term', 'Bounds Test 2: Primary Balance Shock for non-market access countries', time_period]), dsa_pub_exchange_rate_lc_per_us_dollar[scenario, time_period]))
        elif scenario == 'B5' and time_period >= 2025:
            return as_measure(xl_mul(xl_add(xl_div(macro_debt_pv_of_public_sector_ext_debt_end_of_period[time_period], baseline_pub_exchange_rate_lc_per_us_dollar[time_period]), pv_resfin_pub_output_pv_of_new_forex_debt_in_usd['External PPG medium and long-term', 'Bounds Test 5: Exchange Rate Shock', time_period]), dsa_pub_exchange_rate_lc_per_us_dollar[scenario, time_period]))
        elif scenario == 'B6_nonmkt' and time_period >= 2025:
            return as_measure(xl_mul(xl_add(xl_div(macro_debt_pv_of_public_sector_ext_debt_end_of_period[time_period], baseline_pub_exchange_rate_lc_per_us_dollar[time_period]), pv_resfin_pub_output_new_forex_borrowing_gross_usd['External PPG medium and long-term', 'Bounds Test 6: Combined Shock for Non-Market Access Countries', time_period]), dsa_pub_exchange_rate_lc_per_us_dollar[scenario, time_period]))
        elif scenario == 'C2' and time_period >= 2025:
            return as_measure(xl_mul(xl_add(xl_div(macro_debt_pv_of_public_sector_ext_debt_end_of_period[time_period], baseline_pub_exchange_rate_lc_per_us_dollar[time_period]), pv_resfin_pub_output_pv_of_new_forex_debt_in_usd['External PPG medium and long-term', 'CL1: Natural disaster', time_period]), dsa_pub_exchange_rate_lc_per_us_dollar[scenario, time_period]))
        elif scenario == 'C3' and time_period >= 2025:
            return as_measure(xl_mul(xl_add(xl_div(macro_debt_pv_of_public_sector_ext_debt_end_of_period[time_period], baseline_pub_exchange_rate_lc_per_us_dollar[time_period]), pv_resfin_pub_output_pv_of_new_forex_debt_in_usd['External PPG medium and long-term', 'Tailored Stress Test 3. Commodity Price shock - Public', time_period]), dsa_pub_exchange_rate_lc_per_us_dollar[scenario, time_period]))
        return as_measure(xl_mul(xl_add(xl_div(macro_debt_pv_of_public_sector_ext_debt_end_of_period[time_period], baseline_pub_exchange_rate_lc_per_us_dollar[time_period]), pv_resfin_pub_output_pv_of_new_forex_debt_in_usd['External PPG medium and long-term', 'Key variables at historical average', time_period]), dsa_pub_exchange_rate_lc_per_us_dollar[scenario, time_period]))

    return data.DSA_PUB_PV_OF_PUBLIC_SECTOR_EXTERNAL_DEBT_END_OF_PERIOD.collect(evaluate(formula, data.DSA_PUB_PV_OF_PUBLIC_SECTOR_EXTERNAL_DEBT_END_OF_PERIOD.required))

@publish(data.DSA_PUB_DEBT_SERVICE_TO_REVENUE_AND_GRANTS_RATIO_IN_PERCENT.schema, cells=data.DSA_PUB_DEBT_SERVICE_TO_REVENUE_AND_GRANTS_RATIO_IN_PERCENT.cells)
def dsa_pub_debt_service_to_revenue_and_grants_ratio_in_percent(*, dsa_pub_revenue_and_grants: data.Series[float | str | None], dsa_pub_nominal_gdp_local_currency: data.Series[float | str | None], dsa_pub_of_which_short_term: data.Series[float | str | None], dsa_pub_amortization_excluding_st_domestic_debt: data.Series[float | str | None], dsa_pub_interest_expenditure: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute the public debt service-to-revenue-and-grants ratio in percent.

    Derive each scenario's and year's public DSA debt-service burden as a share of public revenue and grants.

    Args:
        dsa_pub_revenue_and_grants: Public revenue and grants for the scenario and year; paired with nominal GDP to form the ratio denominator.
        dsa_pub_nominal_gdp_local_currency: Nominal GDP in local currency for the scenario and year; multiplied with revenue and grants to scale the denominator.
        dsa_pub_of_which_short_term: Public debt of which short-term, read one period earlier to reflect the lagged stock added to the debt-service numerator.
        dsa_pub_amortization_excluding_st_domestic_debt: Public amortization excluding short-term domestic debt for the scenario and year; the base debt-service component.
        dsa_pub_interest_expenditure: Public interest expenditure for the scenario and year; added with amortization to the debt-service numerator.

    Returns:
        Float, str, or None series keyed by scenario and year holding the debt service-to-revenue-and-grants ratio in percent, computed as the sum of amortization, interest, and lagged short-term debt over revenue and grants times nominal GDP in local currency (scaled by 10000); A1 contributes zero when the computed quotient would be negative, and values are blank where the denominator is zero.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        if scenario == 'A1':
            return as_measure((0 if xl_bool(xl_lt(xl_div(xl_add(xl_add(dsa_pub_amortization_excluding_st_domestic_debt[scenario, time_period], dsa_pub_interest_expenditure[scenario, time_period]), dsa_pub_of_which_short_term[scenario, time_period - 1]), xl_mul(dsa_pub_revenue_and_grants[scenario, time_period], dsa_pub_nominal_gdp_local_currency[scenario, time_period])), 0)) else xl_div(xl_mul(10000, xl_add(xl_add(dsa_pub_amortization_excluding_st_domestic_debt[scenario, time_period], dsa_pub_interest_expenditure[scenario, time_period]), dsa_pub_of_which_short_term[scenario, time_period - 1])), xl_mul(dsa_pub_revenue_and_grants[scenario, time_period], dsa_pub_nominal_gdp_local_currency[scenario, time_period]))))
        return as_measure(xl_div(xl_mul(10000, xl_add(xl_add(dsa_pub_amortization_excluding_st_domestic_debt[scenario, time_period], dsa_pub_interest_expenditure[scenario, time_period]), dsa_pub_of_which_short_term[scenario, time_period - 1])), xl_mul(dsa_pub_revenue_and_grants[scenario, time_period], dsa_pub_nominal_gdp_local_currency[scenario, time_period])))

    return data.DSA_PUB_DEBT_SERVICE_TO_REVENUE_AND_GRANTS_RATIO_IN_PERCENT.collect(evaluate(formula, data.DSA_PUB_DEBT_SERVICE_TO_REVENUE_AND_GRANTS_RATIO_IN_PERCENT.required))

@publish(data.DSA_PUB_DEBT_SERVICE_TO_GDP_RATIO_IN_PERCENT.schema, cells=data.DSA_PUB_DEBT_SERVICE_TO_GDP_RATIO_IN_PERCENT.cells)
def dsa_pub_debt_service_to_gdp_ratio_in_percent(*, dsa_pub_nominal_gdp_local_currency: data.Series[float | str | None], dsa_pub_of_which_short_term: data.Series[float | str | None], dsa_pub_amortization_excluding_st_domestic_debt: data.Series[float | str | None], dsa_pub_interest_expenditure: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute the public debt service-to-GDP ratio (B1_GDP_pub) in percent across the standard scenario ladder.

    Derive the LIC-DSF public debt service-to-GDP indicator used by the Chart Data public-debt stress block.

    Args:
        dsa_pub_nominal_gdp_local_currency: Scenario- and year-keyed `data.Series` of public nominal GDP in local currency, supplying the ratio denominator.
        dsa_pub_of_which_short_term: Scenario- and year-keyed `data.Series` of the short-term share of public debt, included at a one-period lag (two-period lag under scenario C2).
        dsa_pub_amortization_excluding_st_domestic_debt: Scenario- and year-keyed `data.Series` of public amortization excluding short-term domestic debt, the principal component of debt service.
        dsa_pub_interest_expenditure: Scenario- and year-keyed `data.Series` of public interest expenditure, the interest component of debt service.

    Returns:
        `data.Series[float | str | None]` of the debt service-to-GDP ratio in percent, keyed by scenario and year over the projection grid; scenario A1 floors negative ratios at zero.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        if scenario == 'C2':
            return as_measure(xl_div(xl_mul(100, xl_add(xl_add(dsa_pub_amortization_excluding_st_domestic_debt[scenario, time_period], dsa_pub_interest_expenditure[scenario, time_period]), dsa_pub_of_which_short_term[scenario, time_period - 2])), dsa_pub_nominal_gdp_local_currency[scenario, time_period]))
        elif scenario == 'A1':
            return as_measure((0 if xl_bool(xl_lt(xl_div(xl_add(xl_add(dsa_pub_amortization_excluding_st_domestic_debt[scenario, time_period], dsa_pub_interest_expenditure[scenario, time_period]), dsa_pub_of_which_short_term[scenario, time_period - 1]), dsa_pub_nominal_gdp_local_currency[scenario, time_period]), 0)) else xl_div(xl_mul(100, xl_add(xl_add(dsa_pub_amortization_excluding_st_domestic_debt[scenario, time_period], dsa_pub_interest_expenditure[scenario, time_period]), dsa_pub_of_which_short_term[scenario, time_period - 1])), dsa_pub_nominal_gdp_local_currency[scenario, time_period])))
        return as_measure(xl_div(xl_mul(100, xl_add(xl_add(dsa_pub_amortization_excluding_st_domestic_debt[scenario, time_period], dsa_pub_interest_expenditure[scenario, time_period]), dsa_pub_of_which_short_term[scenario, time_period - 1])), dsa_pub_nominal_gdp_local_currency[scenario, time_period]))

    return data.DSA_PUB_DEBT_SERVICE_TO_GDP_RATIO_IN_PERCENT.collect(evaluate(formula, data.DSA_PUB_DEBT_SERVICE_TO_GDP_RATIO_IN_PERCENT.required))

@publish(data.DSA_PUB_PV_OF_PUBLIC_DEBT_TO_REVENUE_AND_GRANTS_RATIO.schema, cells=data.DSA_PUB_PV_OF_PUBLIC_DEBT_TO_REVENUE_AND_GRANTS_RATIO.cells)
def dsa_pub_pv_of_public_debt_to_revenue_and_grants_ratio(*, dsa_pub_pv_of_total_public_debt: data.Series[float | str | None], dsa_pub_revenue_and_grants: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute the PV of public debt-to-revenue and grants ratio (B1_GDP_pub) as a percentage.

    Derives the DSA public debt sustainability indicator by dividing PV of total public debt by revenue and grants and scaling to a percentage.

    Args:
        dsa_pub_pv_of_total_public_debt: Series of PV of total public debt, keyed by scenario and projection year, with values that may be float, str, or None.
        dsa_pub_revenue_and_grants: Series of revenue and grants, keyed by scenario and projection year, with values that may be float, str, or None.

    Returns:
        A data.Series[float | str | None] containing the PV of public debt-to-revenue and grants ratio (percentage), keyed by scenario and projection year.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure(xl_mul(xl_div(dsa_pub_pv_of_total_public_debt[scenario, time_period], dsa_pub_revenue_and_grants[scenario, time_period]), 100))

    return data.DSA_PUB_PV_OF_PUBLIC_DEBT_TO_REVENUE_AND_GRANTS_RATIO.collect(evaluate(formula, data.DSA_PUB_PV_OF_PUBLIC_DEBT_TO_REVENUE_AND_GRANTS_RATIO.required))

@publish(data.DSA_PUB_STANDARD_TEST_PARAMETER.schema, cells=data.DSA_PUB_STANDARD_TEST_PARAMETER.cells)
def dsa_pub_standard_test_parameter(*, in6opt_standard_historical_average_baseline_projection: str | int | float | bool, lookup_ida_terms_new: str, input6_standard_size_threshold_mode: Literal["New", "Old"], input6_standard_user_defined_threshold: data.Input6StandardUserDefinedThreshold, in6opt_standard_b1_real_gdp_growth_historical_average_baseline_projection: str | int | float | bool) -> data.Series[str | int | float | bool | None]:
    """Compute public standard-test DSA parameters from Input 6 threshold settings.

    Selects each scenario's standard-test threshold value from user-defined Input 6 settings or scalar fallbacks according to the IDA terms mode.

    Args:
        in6opt_standard_historical_average_baseline_projection: Scalar fallback value for the B1 real GDP growth standard-test threshold when the size-threshold mode does not match the IDA terms lookup.
        lookup_ida_terms_new: Scalar IDA terms label compared against the size-threshold mode to choose new versus old threshold handling.
        input6_standard_size_threshold_mode: Scalar literal mode selecting the new or old IDA terms basis for standard-test size thresholds.
        input6_standard_user_defined_threshold: Typed data.Input6StandardUserDefinedThreshold series of user-defined threshold sizes over scenario, indicator, and threshold-component coordinates.
        in6opt_standard_b1_real_gdp_growth_historical_average_baseline_projection: Scalar fallback value for non-B1 standard-test thresholds when the size-threshold mode does not match the IDA terms lookup.

    Returns:
        Typed data.Series[str | int | float | bool | None] of selected standard-test parameter values over the required scenario coordinates.
    """
    data.INPUT6_STANDARD_USER_DEFINED_THRESHOLD.schema.validate(input6_standard_user_defined_threshold)
    def formula(scenario: str) -> str | int | float | bool | None:
        SCENARIO_TO_INPUT6_STANDARD_USER_DEFINED_THRESHOLD_INDICATOR = {'B1': 'Size of real GDP growth shock, # of standard deviations', 'B2_mkt': 'Size of PB/GDP shock, # of standard deviations'}
        SCENARIO_TO_INPUT6_STANDARD_USER_DEFINED_THRESHOLD = {'B1': 'B1. Real GDP growth', 'B2_mkt': 'B2. Primary balance'}
        if scenario == 'B1':
            return as_measure((input6_standard_user_defined_threshold[f'{scenario}. Real GDP growth', SCENARIO_TO_INPUT6_STANDARD_USER_DEFINED_THRESHOLD_INDICATOR[scenario], 'Size'] if xl_bool(xl_eq(input6_standard_size_threshold_mode, lookup_ida_terms_new)) else in6opt_standard_historical_average_baseline_projection), 'str')
        return as_measure((input6_standard_user_defined_threshold[SCENARIO_TO_INPUT6_STANDARD_USER_DEFINED_THRESHOLD[scenario], SCENARIO_TO_INPUT6_STANDARD_USER_DEFINED_THRESHOLD_INDICATOR[scenario], 'Size'] if xl_bool(xl_eq(input6_standard_size_threshold_mode, lookup_ida_terms_new)) else in6opt_standard_b1_real_gdp_growth_historical_average_baseline_projection), 'str')

    return data.DSA_PUB_STANDARD_TEST_PARAMETER.collect(evaluate(formula, data.DSA_PUB_STANDARD_TEST_PARAMETER.required))

@publish(data.DSA_PUB_PV_OF_DEBT_GDP.schema, cells=data.DSA_PUB_PV_OF_DEBT_GDP.cells)
def dsa_pub_pv_of_debt_gdp(*, dsa_pub_nominal_gdp_local_currency: data.Series[float | str | None], dsa_pub_exchange_rate_lc_per_us_dollar: data.Series[float | str | None], dsa_pub_pv_of_public_sector_external_debt_end_of_period: data.Series[float | str | None], leftover_exchange_rate_pa: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute the public sector PV of debt-to-GDP ratio from component series.

    Derives the public DSA PV of debt-to-GDP ratio (B2_PB_mkt_pub) for each scenario and year by combining external debt, exchange rates, and nominal GDP.

    Args:
        dsa_pub_nominal_gdp_local_currency: Series of nominal GDP in local currency, keyed by scenario and year.
        dsa_pub_exchange_rate_lc_per_us_dollar: Series of exchange rates in local currency per US dollar, keyed by scenario and year.
        dsa_pub_pv_of_public_sector_external_debt_end_of_period: Series of end-of-period public sector external debt present value, keyed by scenario and year.
        leftover_exchange_rate_pa: Series of exchange rates in local currency per US dollar used to convert nominal GDP, keyed by scenario and year.

    Returns:
        Series of the public sector PV of debt-to-GDP ratio, keyed by scenario and year.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure(xl_mul(xl_div(xl_div(dsa_pub_pv_of_public_sector_external_debt_end_of_period[scenario, time_period], dsa_pub_exchange_rate_lc_per_us_dollar[scenario, time_period]), xl_div(dsa_pub_nominal_gdp_local_currency[scenario, time_period], leftover_exchange_rate_pa[scenario, time_period])), 100))

    return data.DSA_PUB_PV_OF_DEBT_GDP.collect(evaluate(formula, data.DSA_PUB_PV_OF_DEBT_GDP.required))

@publish(data.DSA_PUB_PV_OF_DEBT_EXPORTS.schema, cells=data.DSA_PUB_PV_OF_DEBT_EXPORTS.cells)
def dsa_pub_pv_of_debt_exports(*, dsa_pub_exchange_rate_lc_per_us_dollar: data.Series[float | str | None], dsa_pub_pv_of_public_sector_external_debt_end_of_period: data.Series[float | str | None], dsa_pub_exports_us_baseline: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute the PV of public sector external debt-to-exports ratio series from PV debt, exchange rate, and baseline exports.

    Derive the external debt burden indicator used in DSA stress charts and risk-rating signals.

    Args:
        dsa_pub_exchange_rate_lc_per_us_dollar: Scenario- and year-keyed series of local-currency-per-US-dollar exchange rates used to convert external debt stocks.
        dsa_pub_pv_of_public_sector_external_debt_end_of_period: Scenario- and year-keyed series of end-of-period PV of public sector external debt before currency conversion and export normalization.
        dsa_pub_exports_us_baseline: Scenario- and year-keyed series of baseline exports in US dollars, used as the denominator of the debt-exports ratio.

    Returns:
        A data.Series[float | str | None] of PV of debt-to-exports (B2_PB_mkt_pub), keyed by scenario and years from row 7; each value is a percentage or a float, str, or None placeholder.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure(xl_mul(xl_div(xl_div(dsa_pub_pv_of_public_sector_external_debt_end_of_period[scenario, time_period], dsa_pub_exchange_rate_lc_per_us_dollar[scenario, time_period]), dsa_pub_exports_us_baseline[scenario, time_period]), 100))

    return data.DSA_PUB_PV_OF_DEBT_EXPORTS.collect(evaluate(formula, data.DSA_PUB_PV_OF_DEBT_EXPORTS.required))

@publish(data.DSA_PUB_DEBT_SERVICE_EXPORTS.schema, cells=data.DSA_PUB_DEBT_SERVICE_EXPORTS.cells)
def dsa_pub_debt_service_exports(*, dsa_pub_exports_us_baseline: data.Series[float | str | None], macro_debt_ppg_interest_due: data.Series[float | str | None], macro_debt_main_assumptions_us_dollars_by_year_6: data.Series[float | str | None], pv_resfin_pub_output_total_debt_service_in_usd: data.Series[float | str | None], pv_resfin_add_output_interest: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Computes the public debt service-to-exports ratio (B2_PB_mkt_pub) across scenarios and projection years.

    Builds the debt service/exports series used in the LIC-DSF public-debt stress ladder, branching between the 2024 historical formula and the market-access and tailored-shock formulas for years from 2025.

    Args:
        dsa_pub_exports_us_baseline: Baseline public exports in US dollars, as a named-axis series over scenario and projection year.
        macro_debt_ppg_interest_due: Interest due on public and publicly guaranteed debt, as a series over projection year.
        macro_debt_main_assumptions_us_dollars_by_year_6: Main macro-debt assumptions in US dollars (year-6 row), as a series over projection year.
        pv_resfin_pub_output_total_debt_service_in_usd: Total public debt service in US dollars drawn from the PV residual-financing output, as a series keyed by debt-type, scenario, and year coordinates.
        pv_resfin_add_output_interest: Additional interest from the PV residual-financing output, as a series keyed by debt-type, scenario, and year coordinates.

    Returns:
        A named-axis series of debt service-to-exports ratios keyed by scenario and projection year (row 7 onward), holding float, str, or None values.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        if time_period == 2024:
            return as_measure(xl_mul(xl_div(xl_add(macro_debt_ppg_interest_due[time_period], macro_debt_main_assumptions_us_dollars_by_year_6[time_period]), dsa_pub_exports_us_baseline[scenario, time_period]), 100))
        elif scenario == 'B2_mkt' and time_period >= 2025:
            return as_measure(xl_mul(xl_div(xl_add(xl_add(xl_add(macro_debt_ppg_interest_due[time_period], macro_debt_main_assumptions_us_dollars_by_year_6[time_period]), pv_resfin_pub_output_total_debt_service_in_usd['External PPG medium and long-term', 'Bounds Test 2: Primary Balance Shock for non-market access countries', time_period]), pv_resfin_add_output_interest['External PPG medium and long-term', 'Bounds Test 2: Primary Balance Shock for Market Access Countries', time_period]), dsa_pub_exports_us_baseline[scenario, time_period]), 100))
        return as_measure(xl_mul(xl_div(xl_add(xl_add(macro_debt_ppg_interest_due[time_period], macro_debt_main_assumptions_us_dollars_by_year_6[time_period]), pv_resfin_pub_output_total_debt_service_in_usd['External PPG medium and long-term', 'Tailored Stress Test 1: Contingent Liability Shock', time_period]), dsa_pub_exports_us_baseline[scenario, time_period]), 100))

    return data.DSA_PUB_DEBT_SERVICE_EXPORTS.collect(evaluate(formula, data.DSA_PUB_DEBT_SERVICE_EXPORTS.required))

@publish(data.DSA_PUB_DEBT_SERVICE_REVENUE_EXCL_GRANTS.schema, cells=data.DSA_PUB_DEBT_SERVICE_REVENUE_EXCL_GRANTS.cells)
def dsa_pub_debt_service_revenue_excl_grants(*, dsa_pub_revenue: data.Series[float | str | None], macro_debt_ppg_interest_due: data.Series[float | str | None], macro_debt_national_currency_us_dollars: data.Series[float | str | None], macro_debt_main_assumptions_us_dollars_by_year_6: data.Series[float | str | None], pv_resfin_pub_output_total_debt_service_in_usd: data.Series[float | str | None], pv_resfin_add_output_interest: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute public debt service-to-revenue (excluding grants) ratios for the LIC-DSF template.

    Derive the B2_PB_mkt_pub series that feeds the public-debt stress ladder from revenue, interest due, and residual-financing inputs.

    Args:
        dsa_pub_revenue: data.Series of public revenue by scenario and year, used as the denominator of the debt-service-to-revenue ratio except in the B2_mkt 2024 case.
        macro_debt_ppg_interest_due: data.Series of interest due on public and publicly guaranteed debt by year in US dollars, contributing to the numerator.
        macro_debt_national_currency_us_dollars: data.Series of national-currency macro-debt amounts expressed in US dollars by year, substituted for public revenue as the denominator in the B2_mkt 2024 case.
        macro_debt_main_assumptions_us_dollars_by_year_6: data.Series of main-assumptions US dollar values by year (the 'by year' row 6 series), added to interest due in the numerator.
        pv_resfin_pub_output_total_debt_service_in_usd: data.Series of PV residual-financing public output total debt service in US dollars, keyed by debt type and stress scenario, added to the numerator for B2_mkt market-access projections.
        pv_resfin_add_output_interest: data.Series of PV residual-financing additional output interest, keyed by debt type and stress scenario, added to the numerator for B2_mkt market-access projections.

    Returns:
        data.Series[float | str | None] of public debt service-to-revenue (excluding grants) percentages, keyed by scenario and year from row 7.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        if scenario == 'B2_mkt' and time_period == 2024:
            return as_measure(xl_mul(xl_div(xl_add(macro_debt_ppg_interest_due[time_period], macro_debt_main_assumptions_us_dollars_by_year_6[time_period]), macro_debt_national_currency_us_dollars[time_period]), 100))
        elif scenario == 'C1' and time_period == 2024:
            return as_measure(xl_mul(xl_div(xl_add(macro_debt_ppg_interest_due[time_period], macro_debt_main_assumptions_us_dollars_by_year_6[time_period]), dsa_pub_revenue[scenario, time_period]), 100))
        elif scenario == 'B2_mkt' and time_period >= 2025:
            return as_measure(xl_mul(xl_div(xl_add(xl_add(xl_add(macro_debt_ppg_interest_due[time_period], macro_debt_main_assumptions_us_dollars_by_year_6[time_period]), pv_resfin_pub_output_total_debt_service_in_usd['External PPG medium and long-term', 'Bounds Test 2: Primary Balance Shock for non-market access countries', time_period]), pv_resfin_add_output_interest['External PPG medium and long-term', 'Bounds Test 2: Primary Balance Shock for Market Access Countries', time_period]), dsa_pub_revenue[scenario, time_period]), 100))
        return as_measure(xl_mul(xl_div(xl_add(xl_add(macro_debt_ppg_interest_due[time_period], macro_debt_main_assumptions_us_dollars_by_year_6[time_period]), pv_resfin_pub_output_total_debt_service_in_usd['External PPG medium and long-term', 'Tailored Stress Test 1: Contingent Liability Shock', time_period]), dsa_pub_revenue[scenario, time_period]), 100))

    return data.DSA_PUB_DEBT_SERVICE_REVENUE_EXCL_GRANTS.collect(evaluate(formula, data.DSA_PUB_DEBT_SERVICE_REVENUE_EXCL_GRANTS.required))

