@publish(data.DSA_PUB_REVENUE.schema, cells=data.DSA_PUB_REVENUE.cells)
def dsa_pub_revenue(*, dsa_pub_revenue_and_grants: data.Series[float | str | None], dsa_pub_of_which_grants: data.Series[float | str | None], dsa_pub_nominal_gdp_local_currency: data.Series[float | str | None], leftover_exchange_rate_pa: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute public revenue from revenue and grants, grants, nominal GDP, and exchange rate series.

    Implement the DSA public revenue identity for the LIC-DSF template.

    Args:
        dsa_pub_revenue_and_grants: A data.Series[float | str | None] of public revenue and grants (B2_PB_mkt_pub), keyed by scenario and time period.
        dsa_pub_of_which_grants: A data.Series[float | str | None] of grants included in public revenue, keyed by scenario and time period.
        dsa_pub_nominal_gdp_local_currency: A data.Series[float | str | None] of nominal GDP in local currency, keyed by scenario and time period.
        leftover_exchange_rate_pa: A data.Series[float | str | None] of period-average exchange rate (local currency per USD), keyed by scenario and time period.

    Returns:
        A data.Series[float | str | None] of computed public revenue, keyed by scenario and time period.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure(xl_mul(xl_div(xl_sub(dsa_pub_revenue_and_grants[scenario, time_period], dsa_pub_of_which_grants[scenario, time_period]), 100), xl_div(dsa_pub_nominal_gdp_local_currency[scenario, time_period], leftover_exchange_rate_pa[scenario, time_period])))

    return data.DSA_PUB_REVENUE.collect(evaluate(formula, data.DSA_PUB_REVENUE.required))

@publish(data.DSA_PUB_B2_PB_NON_MKT_PUB_PV_OF_DEBT_GDP.schema, cells=data.DSA_PUB_B2_PB_NON_MKT_PUB_PV_OF_DEBT_GDP.cells)
def dsa_pub_b2_pb_non_mkt_pub_pv_of_debt_gdp(*, dsa_pub_nominal_gdp_local_currency: data.Series[float | str | None], dsa_pub_exchange_rate_lc_per_us_dollar: data.Series[float | str | None], dsa_pub_pv_of_public_sector_external_debt_end_of_period: data.Series[float | str | None], leftover_exchange_rate_pa: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute the public non-market PV of debt-to-GDP ratio from nominal GDP, exchange rates, and external public debt stock.

    Projects the B2_PB_non_mkt_pub PV of Debt/GDP series over scenario-year coordinates using authored coordinate identities.

    Args:
        dsa_pub_nominal_gdp_local_currency: Series of nominal GDP in local currency, keyed by scenario and year.
        dsa_pub_exchange_rate_lc_per_us_dollar: Series of the local-currency-per-US-dollar exchange rate, keyed by scenario and year.
        dsa_pub_pv_of_public_sector_external_debt_end_of_period: Series of the end-of-period PV of public sector external debt, keyed by scenario and year.
        leftover_exchange_rate_pa: Series of the leftover period-average exchange rate applied to nominal GDP, keyed by scenario and year.

    Returns:
        Series of PV of Debt/GDP (B2_PB_non_mkt_pub), keyed by scenario and years from row 7.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure(xl_mul(xl_div(xl_div(dsa_pub_pv_of_public_sector_external_debt_end_of_period[scenario, time_period], dsa_pub_exchange_rate_lc_per_us_dollar[scenario, time_period]), xl_div(dsa_pub_nominal_gdp_local_currency[scenario, time_period], leftover_exchange_rate_pa[scenario, time_period])), 100))

    return data.DSA_PUB_B2_PB_NON_MKT_PUB_PV_OF_DEBT_GDP.collect(evaluate(formula, data.DSA_PUB_B2_PB_NON_MKT_PUB_PV_OF_DEBT_GDP.required))

@publish(data.DSA_PUB_B2_PB_NON_MKT_PUB_PV_OF_DEBT_EXPORTS.schema, cells=data.DSA_PUB_B2_PB_NON_MKT_PUB_PV_OF_DEBT_EXPORTS.cells)
def dsa_pub_b2_pb_non_mkt_pub_pv_of_debt_exports(*, dsa_pub_exchange_rate_lc_per_us_dollar: data.Series[float | str | None], dsa_pub_pv_of_public_sector_external_debt_end_of_period: data.Series[float | str | None], dsa_pub_b2_pb_non_mkt_pub_exports_us_baseline: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute the public-sector external debt PV-to-exports ratio by scenario and projection year.

    Derive the B2_PB_non_mkt_pub PV of debt-to-exports indicator from external debt, exchange-rate, and baseline export series.

    Args:
        dsa_pub_exchange_rate_lc_per_us_dollar: Exchange rate expressed as local currency units per U.S. dollar, as a scenario- and year-keyed data.Series of numeric values, blank strings, or nulls.
        dsa_pub_pv_of_public_sector_external_debt_end_of_period: PV of public-sector external debt at end of period, as a scenario- and year-keyed data.Series of numeric values, blank strings, or nulls.
        dsa_pub_b2_pb_non_mkt_pub_exports_us_baseline: Baseline exports in U.S. dollars for the non-market-financing public-debt scenario, as a scenario- and year-keyed data.Series of numeric values, blank strings, or nulls.

    Returns:
        A scenario- and year-keyed data.Series[float | str | None] containing the PV of public-sector external debt-to-exports ratio, keyed from row 7 of the DSA template.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure(xl_mul(xl_div(xl_div(dsa_pub_pv_of_public_sector_external_debt_end_of_period[scenario, time_period], dsa_pub_exchange_rate_lc_per_us_dollar[scenario, time_period]), dsa_pub_b2_pb_non_mkt_pub_exports_us_baseline[scenario, time_period]), 100))

    return data.DSA_PUB_B2_PB_NON_MKT_PUB_PV_OF_DEBT_EXPORTS.collect(evaluate(formula, data.DSA_PUB_B2_PB_NON_MKT_PUB_PV_OF_DEBT_EXPORTS.required))

