    def formula(scenario: str, time_period: int) -> float | str | None:
        if time_period == 2024:
            return as_measure(xl_mul(xl_div(xl_add(macro_debt_ppg_interest_due[time_period], macro_debt_main_assumptions_us_dollars_by_year_6[time_period]), dsa_pub_b2_pb_non_mkt_pub_exports_us_baseline[scenario, time_period]), 100))
        return as_measure(xl_mul(xl_div(xl_add(xl_add(macro_debt_ppg_interest_due[time_period], macro_debt_main_assumptions_us_dollars_by_year_6[time_period]), pv_resfin_pub_output_total_debt_service_in_usd['External PPG medium and long-term', 'Bounds Test 2: Primary Balance Shock for non-market access countries', time_period]), dsa_pub_b2_pb_non_mkt_pub_exports_us_baseline[scenario, time_period]), 100))

    return data.DSA_PUB_B2_PB_NON_MKT_PUB_DEBT_SERVICE_EXPORTS.collect(evaluate(formula, data.DSA_PUB_B2_PB_NON_MKT_PUB_DEBT_SERVICE_EXPORTS.required))

