    return data.DSA_PUB_B2_PB_NON_MKT_PUB_DEBT_SERVICE_REVENUE_EXCL_GRANTS.collect(evaluate(formula, data.DSA_PUB_B2_PB_NON_MKT_PUB_DEBT_SERVICE_REVENUE_EXCL_GRANTS.required))

