@publish(key=('SCENARIO',), domain=None, cells=data.DSA_PUB_OLD_NEW_SCENARIO_TOTAL_CELLS)
def dsa_pub_old_new_scenario_total(*, dsa_pub_input2_coverage: data.Series[float | str | None], in6opt_standard_scenario: int | str) -> float | str:
    """Computes the old/new-scenario contingent-liability coverage total from the Input 2 coverage series and the standard-scenario option flag.

    Returns either the standard-scenario constant value or the summed contingent-liability coverage across the general-government-to-financial-sector indicator span.

    Args:
        dsa_pub_input2_coverage: Coverage series over catalog coordinates (float, string, or None per leaf) from Input 2; the helper slices its 'Other general government' through 'Financial sector' rows at column C1 to aggregate the old/new-scenario contingent-liability total.
        in6opt_standard_scenario: Scalar option flag from Input 6 (integer or string); when evaluated as 0, the function returns the standard-scenario constant 10 instead of summing the coverage slice.

    Returns:
        Old/new-scenario contingent-liability coverage total as a float or string; yields 10 when the standard-scenario option is 0, otherwise the aggregated coverage value, or an XlError code string when evaluation fails.
    """
    _dsa_pub_old_new_scenario_total_table_0 = view(dsa_pub_input2_coverage, rows=span(data.INDICATOR_AXIS, 'Other general government', 'Financial sector'), cols=('C1',), cols_first=True)
    try:
        return as_measure((10 if xl_bool(xl_eq(in6opt_standard_scenario, 0)) else xl_sum(_dsa_pub_old_new_scenario_total_table_0)))
    except XlError as error:
        return error.code

@publish(data.DSA_PUB_INPUT2_COVERAGE.schema, cells=data.DSA_PUB_INPUT2_COVERAGE.cells)
def dsa_pub_input2_coverage(*, contingent_liability_financial_market_pct_gdp: float | str, in2_coverage_ppp: float | str, in2_coverage_other_elements_of_govt_not_captured_in_1: int | str, in2_coverage_soe_s_debt_guaranteed_not_guaranteed_government: int | str) -> data.Series[float | str | None]:
    """Map Input 2 contingent-liability coverage entries onto the DSA_PUB_INPUT2_COVERAGE series.

    Populate the Input 2 public debt coverage breakdown by assigning each economist-supplied coverage component to its indicator label on the collected series.

    Args:
        contingent_liability_financial_market_pct_gdp: Scalar financial-market contingent liability coverage, expressed as a percent of GDP; used as the fallback value for any indicator label not otherwise matched.
        in2_coverage_ppp: Scalar PPP coverage component from Input 2, reported as a percent of GDP or as a text placeholder when coverage is not applicable.
        in2_coverage_other_elements_of_govt_not_captured_in_1: Scalar coverage share for other general government elements not captured in Input 1, given as an integer-based measure or text placeholder.
        in2_coverage_soe_s_debt_guaranteed_not_guaranteed_government: Scalar coverage share for state-owned enterprise debt, both guaranteed and non-guaranteed government debt, given as an integer-based measure or text placeholder.

    Returns:
        A data.Series indexing the evaluated Input 2 coverage values over the required column Z indicator labels ('Other general government', 'SoEs', 'PPP', and the contingent-liability financial-market share as the default), each holding a float, str, or None.
    """
    def formula(scenario: str, indicator: str) -> float | str | None:
        if indicator == 'Other general government':
            return as_measure(in2_coverage_other_elements_of_govt_not_captured_in_1)
        elif indicator == 'SoEs':
            return as_measure(in2_coverage_soe_s_debt_guaranteed_not_guaranteed_government)
        elif indicator == 'PPP':
            return as_measure(in2_coverage_ppp)
        return as_measure(contingent_liability_financial_market_pct_gdp)

    return data.DSA_PUB_INPUT2_COVERAGE.collect(evaluate(formula, data.DSA_PUB_INPUT2_COVERAGE.required))

@publish(data.DSA_PUB_C2_NATURAL_DISASTER_PV_OF_DEBT_GDP.schema, cells=data.DSA_PUB_C2_NATURAL_DISASTER_PV_OF_DEBT_GDP.cells)
def dsa_pub_c2_natural_disaster_pv_of_debt_gdp(*, dsa_pub_nominal_gdp_local_currency: data.Series[float | str | None], dsa_pub_exchange_rate_lc_per_us_dollar: data.Series[float | str | None], dsa_pub_pv_of_public_sector_external_debt_end_of_period: data.Series[float | str | None], leftover_exchange_rate_pa: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute the C2 natural-disaster PV of public debt-to-GDP ratio as a scenario- and period-indexed series.

    Derive the natural-disaster scenario debt-to-GDP path from nominal GDP, exchange rates, and the end-of-period public external debt present value.

    Args:
        dsa_pub_nominal_gdp_local_currency: Nominal gross domestic product in local currency as a scenario- and period-indexed data.Series[float | str | None].
        dsa_pub_exchange_rate_lc_per_us_dollar: Exchange rate in local currency per U.S. dollar as a scenario- and period-indexed data.Series[float | str | None].
        dsa_pub_pv_of_public_sector_external_debt_end_of_period: Present value of public-sector external debt at end of period as a scenario- and period-indexed data.Series[float | str | None].
        leftover_exchange_rate_pa: Period-average exchange rate in local currency per U.S. dollar as a scenario- and period-indexed data.Series[float | str | None].

    Returns:
        A scenario- and period-indexed data.Series[float | str | None] containing the C2 natural-disaster PV of public debt-to-GDP ratio, expressed as a percentage.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure(xl_mul(xl_div(xl_div(dsa_pub_pv_of_public_sector_external_debt_end_of_period[scenario, time_period], dsa_pub_exchange_rate_lc_per_us_dollar[scenario, time_period]), xl_div(dsa_pub_nominal_gdp_local_currency[scenario, time_period], leftover_exchange_rate_pa[scenario, time_period])), 100))

    return data.DSA_PUB_C2_NATURAL_DISASTER_PV_OF_DEBT_GDP.collect(evaluate(formula, data.DSA_PUB_C2_NATURAL_DISASTER_PV_OF_DEBT_GDP.required))

@publish(data.DSA_PUB_C2_NATURAL_DISASTER_PV_OF_DEBT_EXPORTS.schema, cells=data.DSA_PUB_C2_NATURAL_DISASTER_PV_OF_DEBT_EXPORTS.cells)
def dsa_pub_c2_natural_disaster_pv_of_debt_exports(*, dsa_pub_exchange_rate_lc_per_us_dollar: data.Series[float | str | None], dsa_pub_pv_of_public_sector_external_debt_end_of_period: data.Series[float | str | None], dsa_pub_c2_natural_disaster_exports_us_baseline: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute the present value of public sector external debt relative to exports under the C2 natural disaster scenario.

    Derive the baseline PV-of-debt-to-exports ratio for the C2 natural disaster tailored stress test from exchange-rate, debt-stock, and export inputs.

    Args:
        dsa_pub_exchange_rate_lc_per_us_dollar: Exchange rate expressed in local currency per US dollar, as a named-axis series over scenario and time-period coordinates.
        dsa_pub_pv_of_public_sector_external_debt_end_of_period: Present value of public sector external debt at the end of the period, as a named-axis series over scenario and time-period coordinates.
        dsa_pub_c2_natural_disaster_exports_us_baseline: Baseline exports in US dollars under the C2 natural disaster scenario, as a named-axis series over scenario and time-period coordinates.

    Returns:
        A data.Series[float | str | None] holding the PV of debt-to-exports ratio for the C2 natural disaster scenario, keyed by scenario and years from row 7.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure(xl_mul(xl_div(xl_div(dsa_pub_pv_of_public_sector_external_debt_end_of_period[scenario, time_period], dsa_pub_exchange_rate_lc_per_us_dollar[scenario, time_period]), dsa_pub_c2_natural_disaster_exports_us_baseline[scenario, time_period]), 100))

    return data.DSA_PUB_C2_NATURAL_DISASTER_PV_OF_DEBT_EXPORTS.collect(evaluate(formula, data.DSA_PUB_C2_NATURAL_DISASTER_PV_OF_DEBT_EXPORTS.required))

@publish(data.DSA_PUB_C2_NATURAL_DISASTER_DEBT_SERVICE_EXPORTS.schema, cells=data.DSA_PUB_C2_NATURAL_DISASTER_DEBT_SERVICE_EXPORTS.cells)
def dsa_pub_c2_natural_disaster_debt_service_exports(*, dsa_pub_c2_natural_disaster_exports_us_baseline: data.Series[float | str | None], macro_debt_ppg_interest_due: data.Series[float | str | None], macro_debt_main_assumptions_us_dollars_by_year_6: data.Series[float | str | None], pv_resfin_pub_output_total_debt_service_in_usd: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Computes the C2 Natural disaster debt service-to-exports ratio series by scenario and year.

    Derives the natural-disaster debt service/exports indicator from interest due, main macro-debt assumptions, baseline natural-disaster exports, and residual-financing public debt service.

    Args:
        dsa_pub_c2_natural_disaster_exports_us_baseline: data.Series[float | str | None]: Baseline natural-disaster exports in US dollars, keyed by scenario and year; used as the denominator.
        macro_debt_ppg_interest_due: data.Series[float | str | None]: Public and publicly guaranteed debt interest due by year; contributes to the ratio numerator.
        macro_debt_main_assumptions_us_dollars_by_year_6: data.Series[float | str | None]: Macro-debt main assumptions in US dollars by year from the year-6 series; contributes to the ratio numerator.
        pv_resfin_pub_output_total_debt_service_in_usd: data.Series[float | str | None]: Public external PPG medium- and long-term debt service under the CL1 natural-disaster label, in US dollars by year; added to the numerator for non-2024 periods.

    Returns:
        data.Series[float | str | None]: Natural-disaster debt service-to-exports ratio, in percent, keyed by scenario and year.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        if time_period == 2024:
            return as_measure(xl_mul(xl_div(xl_add(macro_debt_ppg_interest_due[time_period], macro_debt_main_assumptions_us_dollars_by_year_6[time_period]), dsa_pub_c2_natural_disaster_exports_us_baseline[scenario, time_period]), 100))
        return as_measure(xl_mul(xl_div(xl_add(xl_add(macro_debt_ppg_interest_due[time_period], macro_debt_main_assumptions_us_dollars_by_year_6[time_period]), pv_resfin_pub_output_total_debt_service_in_usd['External PPG medium and long-term', 'CL1: Natural disaster', time_period]), dsa_pub_c2_natural_disaster_exports_us_baseline[scenario, time_period]), 100))

