@publish(data.DSA_PUB_C2_NATURAL_DISASTER_DEBT_SERVICE_REVENUE_EXCL_GRANTS.schema, cells=data.DSA_PUB_C2_NATURAL_DISASTER_DEBT_SERVICE_REVENUE_EXCL_GRANTS.cells)
def dsa_pub_c2_natural_disaster_debt_service_revenue_excl_grants(*, dsa_pub_c2_natural_disaster_revenue: data.Series[float | str | None], macro_debt_ppg_interest_due: data.Series[float | str | None], macro_debt_main_assumptions_us_dollars_by_year_6: data.Series[float | str | None], pv_resfin_pub_output_total_debt_service_in_usd: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute the C2 natural-disaster debt service-to-revenue ratio excluding grants.

    Populate the natural-disaster indicator in the public DSA debt-service ladder.

    Args:
        dsa_pub_c2_natural_disaster_revenue: Natural-disaster revenue series over catalog scenario and year coordinates, providing the denominator of the ratio.
        macro_debt_ppg_interest_due: PPG interest due series in US dollars by projection year, contributing to the numerator.
        macro_debt_main_assumptions_us_dollars_by_year_6: Main macro assumptions in US dollars by year, contributing to the numerator.
        pv_resfin_pub_output_total_debt_service_in_usd: Public output total debt service series in US dollars keyed by scenario/row and year, added to the numerator for projection years after 2024.

    Returns:
        A data.Series[float | str | None] of the debt service-to-revenue ratio in percent, keyed by scenario and projection year, preserving blanks and non-numeric entries.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        if time_period == 2024:
            return as_measure(xl_mul(xl_div(xl_add(macro_debt_ppg_interest_due[time_period], macro_debt_main_assumptions_us_dollars_by_year_6[time_period]), dsa_pub_c2_natural_disaster_revenue[scenario, time_period]), 100))
        return as_measure(xl_mul(xl_div(xl_add(xl_add(macro_debt_ppg_interest_due[time_period], macro_debt_main_assumptions_us_dollars_by_year_6[time_period]), pv_resfin_pub_output_total_debt_service_in_usd['External PPG medium and long-term', 'CL1: Natural disaster', time_period]), dsa_pub_c2_natural_disaster_revenue[scenario, time_period]), 100))

    return data.DSA_PUB_C2_NATURAL_DISASTER_DEBT_SERVICE_REVENUE_EXCL_GRANTS.collect(evaluate(formula, data.DSA_PUB_C2_NATURAL_DISASTER_DEBT_SERVICE_REVENUE_EXCL_GRANTS.required))

@publish(data.DSA_PUB_C2_NATURAL_DISASTER_EXPORTS_US_BASELINE.schema, cells=data.DSA_PUB_C2_NATURAL_DISASTER_EXPORTS_US_BASELINE.cells)
def dsa_pub_c2_natural_disaster_exports_us_baseline(*, macro_debt_exports_of_goods_services: data.Series[float | str | None], dsa_pub_c2_natural_disaster_exports_growth_rate: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Project the C2 natural-disaster baseline exports of goods and services (US$).

    Build the baseline exports series for the C2 natural-disaster public-debt DSA scenario, anchoring on reported exports in 2024 and rolling each projection year forward with the scenario growth rate.

    Args:
        macro_debt_exports_of_goods_services: Exports of goods and services (US$) series over catalog coordinates, read at 2024 to seed the baseline projection.
        dsa_pub_c2_natural_disaster_exports_growth_rate: Exports growth rate (percent) series over scenario and year coordinates, applied to the prior year's baseline level to roll the projection forward.

    Returns:
        Exports of goods and services (US$) baseline series for the C2 natural-disaster scenario, keyed by scenario and year, equal to the 2024 historical value and grown thereafter by the scenario growth rate.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        if time_period == 2024:
            return as_measure(macro_debt_exports_of_goods_services[time_period])
        return as_measure(xl_mul(dsa_pub_c2_natural_disaster_exports_us_baseline[scenario, time_period - 1], xl_add(1, xl_div(dsa_pub_c2_natural_disaster_exports_growth_rate[scenario, time_period], 100))))

    dsa_pub_c2_natural_disaster_exports_us_baseline = CoordinateReader('dsa_pub_c2_natural_disaster_exports_us_baseline', data.DSA_PUB_C2_NATURAL_DISASTER_EXPORTS_US_BASELINE.required, formula)
    return data.DSA_PUB_C2_NATURAL_DISASTER_EXPORTS_US_BASELINE.collect((coord, dsa_pub_c2_natural_disaster_exports_us_baseline[coord]) for coord in data.DSA_PUB_C2_NATURAL_DISASTER_EXPORTS_US_BASELINE.required)

@publish(data.DSA_PUB_C2_NATURAL_DISASTER_EXPORTS_GROWTH_RATE.schema, cells=data.DSA_PUB_C2_NATURAL_DISASTER_EXPORTS_GROWTH_RATE.cells)
def dsa_pub_c2_natural_disaster_exports_growth_rate(*, dsa_ext_growth_of_exports_of_g_s_us_dollar_terms_in_percent: data.Series[float | str | None], leftover_real_interest_rate: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute the C2 natural-disaster exports growth rate series.

    Derive the natural-disaster exports growth path by carrying the baseline export growth forward and applying the 2025 residual-interest-rate adjustment.

    Args:
        dsa_ext_growth_of_exports_of_g_s_us_dollar_terms_in_percent: data.Series[float | str | None] of export growth rates for goods and services in U.S. dollar terms, in percent, keyed by scenario and projection year; the Baseline coordinate supplies the path.
        leftover_real_interest_rate: data.Series[float | str | None] of leftover real interest rates keyed by scenario, used for the 2025 adjustment.

    Returns:
        data.Series[float | str | None] of C2 natural-disaster exports growth rates keyed by scenario and projection year, equal to the baseline exports growth rate except in 2025 where the leftover real interest rate is subtracted.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        if time_period == 2025:
            return as_measure(xl_sub(dsa_ext_growth_of_exports_of_g_s_us_dollar_terms_in_percent['Baseline', time_period], leftover_real_interest_rate[scenario]))
        return as_measure(dsa_ext_growth_of_exports_of_g_s_us_dollar_terms_in_percent['Baseline', time_period])

    return data.DSA_PUB_C2_NATURAL_DISASTER_EXPORTS_GROWTH_RATE.collect(evaluate(formula, data.DSA_PUB_C2_NATURAL_DISASTER_EXPORTS_GROWTH_RATE.required))

@publish(data.DSA_PUB_C2_NATURAL_DISASTER_REVENUE.schema, cells=data.DSA_PUB_C2_NATURAL_DISASTER_REVENUE.cells)
def dsa_pub_c2_natural_disaster_revenue(*, dsa_pub_revenue_and_grants: data.Series[float | str | None], dsa_pub_of_which_grants: data.Series[float | str | None], dsa_pub_nominal_gdp_local_currency: data.Series[float | str | None], leftover_exchange_rate_pa: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute the C2 natural-disaster public revenue series from revenue, grant, GDP, and exchange-rate inputs.

    Derive the natural-disaster-scenario public revenue measure over the scenario-by-year grid by netting grants out of total revenue and scaling nominal GDP to local-currency terms.

    Args:
        dsa_pub_revenue_and_grants: Keyword-only data.Series[float | str | None] of published public revenue and grants, keyed by scenario and projection year.
        dsa_pub_of_which_grants: Keyword-only data.Series[float | str | None] of the grant portion included in public revenue and grants, keyed by scenario and projection year.
        dsa_pub_nominal_gdp_local_currency: Keyword-only data.Series[float | str | None] of nominal GDP in local currency, keyed by scenario and projection year.
        leftover_exchange_rate_pa: Keyword-only data.Series[float | str | None] of the period-average exchange rate leftover, keyed by scenario and projection year.

    Returns:
        A data.Series[float | str | None] of natural-disaster public revenue keyed by scenario and projection year.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure(xl_mul(xl_div(xl_sub(dsa_pub_revenue_and_grants[scenario, time_period], dsa_pub_of_which_grants[scenario, time_period]), 100), xl_div(dsa_pub_nominal_gdp_local_currency[scenario, time_period], leftover_exchange_rate_pa[scenario, time_period])))

    return data.DSA_PUB_C2_NATURAL_DISASTER_REVENUE.collect(evaluate(formula, data.DSA_PUB_C2_NATURAL_DISASTER_REVENUE.required))

