@publish(data.INPUT4_DISCOUNT_RATE.schema, cells=data.INPUT4_DISCOUNT_RATE.cells)
def input4_discount_rate(*, discount_rate: float | str) -> data.Series[float | str | None]:
    """Build the Input 4 discount-rate series across external instrument rows.

    Assign the supplied discount rate to the IMF instrument row and propagate that IMF rate to every other external instrument row so the full instrument-indexed series can be collected.

    Args:
        discount_rate: Discount rate scalar or text label applied to the IMF row and, in turn, to all other external instrument rows.

    Returns:
        A `data.Series` over external instrument coordinates holding the resulting `float | str | None` discount rate for each row.
    """
    def formula(instrument: str) -> float | str | None:
        if instrument == 'IMF':
            return as_measure(discount_rate)
        return as_measure(input4_discount_rate['IMF'])

    input4_discount_rate = CoordinateReader('input4_discount_rate', data.INPUT4_DISCOUNT_RATE.required, formula)
    return data.INPUT4_DISCOUNT_RATE.collect((coord, input4_discount_rate[coord]) for coord in data.INPUT4_DISCOUNT_RATE.required)

