@publish(data.INPUT5_PROJECTION_YEARS.schema, cells=data.INPUT5_PROJECTION_YEARS.cells)
def input5_projection_years(*, macro_debt_data: int | str) -> data.Series[int | str | None]:
    """Compute the Input 5 projection-year axis, including the pre-projection year.

    Return the projection-year sequence for Input 5 row 5, seeded by macro-debt data in the pre-projection year.

    Args:
        macro_debt_data: Scalar macro-debt data value (int or str) that anchors the pre-projection year in the Input 5 projection-year axis.

    Returns:
        data.Series[int | str | None] over the projection-year coordinate, containing the derived year labels with the pre-projection year in H.
    """
    def formula(time_period: int) -> int | str | None:
        if time_period == 2023:
            return as_measure(xl_sub(input5_projection_years[time_period + 1], 1), 'int')
        elif time_period == 2024:
            return as_measure(macro_debt_data, 'int')
        return as_measure(xl_add(input5_projection_years[time_period - 1], 1), 'int')

    input5_projection_years = CoordinateReader('input5_projection_years', data.INPUT5_PROJECTION_YEARS.required, formula)
    return data.INPUT5_PROJECTION_YEARS.collect((coord, input5_projection_years[coord]) for coord in data.INPUT5_PROJECTION_YEARS.required)

