@publish(data.INPUT5_INSTRUMENT_TERMS_INSTRUMENT_LABEL.schema, cells=data.INPUT5_INSTRUMENT_TERMS_INSTRUMENT_LABEL.cells)
def input5_instrument_terms_instrument_label(*, translation_input_5_domestic_financing_locally_issued_debt: data.Series[str | None], translation_input_5_domestic_financing_central_bank_financing: data.Series[str | None], translation_input_5_domestic_financing_t_bills_denominated_in_local_currency: data.Series[str | None], translation_input_5_domestic_financing_t_bills_denominated_in_foreign_currency: data.Series[str | None], translation_input_5_domestic_financing_mlt_debt: data.Series[str | None], translation_input_5_domestic_financing_denominated_in_local_currency_lc: data.Series[str | None], translation_input_5_domestic_financing_bonds_1_to_3_years_lc: data.Series[str | None], translation_input_5_domestic_financing_bonds_4_to_7_years_lc: data.Series[str | None], translation_input_5_domestic_financing_bonds_beyond_7_years_lc: data.Series[str | None], translation_input_5_domestic_financing_bonds_1_to_3_years_fx: data.Series[str | None], translation_input_5_domestic_financing_bonds_4_to_7_years_fx: data.Series[str | None], translation_input_5_domestic_financing_bonds_beyond_7_years_fx: data.Series[str | None], input5_definition_of_external_domestic_debt: str | int | float | bool, external_domestic_debt_definition: str, start_debt_sustainability_analysis_m: int | str, lookup_afg_ap: str | int | float | bool, lookup_hti: str | int | float | bool, lookup_hnd: str | int | float | bool, translation_st_debt: data.Series[str | int | float | bool | None], lookup_afg: str | int | float | bool) -> data.Series[str | int | float | bool | None]:
    """Build the instrument-label series for Input 5 domestic financing terms.

    Resolve each Input 5 instrument-terms label from workbook translation cells, debt-definition lookups, and the analysis start year.

    Args:
        translation_input_5_domestic_financing_locally_issued_debt: Translation series holding the locally issued domestic debt label, aligned to the Input 5 instrument-coordinate grid.
        translation_input_5_domestic_financing_central_bank_financing: Translation series holding the central bank financing label for domestic debt.
        translation_input_5_domestic_financing_t_bills_denominated_in_local_currency: Translation series holding the label for T-bills denominated in local currency.
        translation_input_5_domestic_financing_t_bills_denominated_in_foreign_currency: Translation series holding the label for T-bills denominated in foreign currency.
        translation_input_5_domestic_financing_mlt_debt: Translation series holding the label for medium- and long-term (MLT) domestic debt.
        translation_input_5_domestic_financing_denominated_in_local_currency_lc: Translation series holding the label for debt denominated in local currency (LC).
        translation_input_5_domestic_financing_bonds_1_to_3_years_lc: Translation series holding the label for local-currency bonds with 1 to 3 year maturities.
        translation_input_5_domestic_financing_bonds_4_to_7_years_lc: Translation series holding the label for local-currency bonds with 4 to 7 year maturities.
        translation_input_5_domestic_financing_bonds_beyond_7_years_lc: Translation series holding the label for local-currency bonds with maturities beyond 7 years.
        translation_input_5_domestic_financing_bonds_1_to_3_years_fx: Translation series holding the label for foreign-currency bonds with 1 to 3 year maturities.
        translation_input_5_domestic_financing_bonds_4_to_7_years_fx: Translation series holding the label for foreign-currency bonds with 4 to 7 year maturities.
        translation_input_5_domestic_financing_bonds_beyond_7_years_fx: Translation series holding the label for foreign-currency bonds with maturities beyond 7 years.
        input5_definition_of_external_domestic_debt: Scalar selector indicating which external/domestic debt definition governs the FX-denomination label.
        external_domestic_debt_definition: Scalar debt-definition string tested against the Input 5 selector to choose between the AFG/AP and HTI/HND lookup branches.
        start_debt_sustainability_analysis_m: Scalar start year of the debt sustainability analysis, used as the axis step for the language and maturity lookups.
        lookup_afg_ap: Scalar lookup label returned for the residents-held row when the debt definition matches.
        lookup_hti: Scalar lookup label for the FX-denomination row when the debt definition matches.
        lookup_hnd: Scalar fallback lookup label for the FX-denomination row when the debt definition does not match.
        translation_st_debt: Translated short-term debt series keyed by the maturity axis, supplying the short-term debt row label.
        lookup_afg: Scalar lookup key compared against the external/domestic debt definition selector.

    Returns:
        A data.Series[str | int | float | bool | None] over the input5.instrument_terms instrument-label coordinate (holders non-residents and residents), giving the resolved instrument label for each coordinate.
    """
    data.TRANSLATION_INPUT_5_DOMESTIC_FINANCING_LOCALLY_ISSUED_DEBT.schema.validate(translation_input_5_domestic_financing_locally_issued_debt)
    data.TRANSLATION_INPUT_5_DOMESTIC_FINANCING_CENTRAL_BANK_FINANCING.schema.validate(translation_input_5_domestic_financing_central_bank_financing)
    data.TRANSLATION_INPUT_5_DOMESTIC_FINANCING_T_BILLS_DENOMINATED_IN_LOCAL_CURRENCY.schema.validate(translation_input_5_domestic_financing_t_bills_denominated_in_local_currency)
    data.TRANSLATION_INPUT_5_DOMESTIC_FINANCING_T_BILLS_DENOMINATED_IN_FOREIGN_CURRENCY.schema.validate(translation_input_5_domestic_financing_t_bills_denominated_in_foreign_currency)
    data.TRANSLATION_INPUT_5_DOMESTIC_FINANCING_MLT_DEBT.schema.validate(translation_input_5_domestic_financing_mlt_debt)
    data.TRANSLATION_INPUT_5_DOMESTIC_FINANCING_DENOMINATED_IN_LOCAL_CURRENCY_LC.schema.validate(translation_input_5_domestic_financing_denominated_in_local_currency_lc)
    data.TRANSLATION_INPUT_5_DOMESTIC_FINANCING_BONDS_1_TO_3_YEARS_LC.schema.validate(translation_input_5_domestic_financing_bonds_1_to_3_years_lc)
    data.TRANSLATION_INPUT_5_DOMESTIC_FINANCING_BONDS_4_TO_7_YEARS_LC.schema.validate(translation_input_5_domestic_financing_bonds_4_to_7_years_lc)
    data.TRANSLATION_INPUT_5_DOMESTIC_FINANCING_BONDS_BEYOND_7_YEARS_LC.schema.validate(translation_input_5_domestic_financing_bonds_beyond_7_years_lc)
    data.TRANSLATION_INPUT_5_DOMESTIC_FINANCING_BONDS_1_TO_3_YEARS_FX.schema.validate(translation_input_5_domestic_financing_bonds_1_to_3_years_fx)
    data.TRANSLATION_INPUT_5_DOMESTIC_FINANCING_BONDS_4_TO_7_YEARS_FX.schema.validate(translation_input_5_domestic_financing_bonds_4_to_7_years_fx)
    data.TRANSLATION_INPUT_5_DOMESTIC_FINANCING_BONDS_BEYOND_7_YEARS_FX.schema.validate(translation_input_5_domestic_financing_bonds_beyond_7_years_fx)
    def formula(instrument: str, holder: str) -> str | int | float | bool | None:
        if instrument == 'Locally-issued debt' and holder == 'residents':
            return as_measure(translation_input_5_domestic_financing_locally_issued_debt[axis_step(data.LANGUAGE_AXIS, 'English', start_debt_sustainability_analysis_m)], 'str')
        elif instrument == 'Held by residents' and holder == 'residents':
            return as_measure((lookup_afg_ap if xl_bool(xl_eq(external_domestic_debt_definition, lookup_afg)) else ''), 'str')
        elif instrument == 'Central bank financing' and holder == 'residents':
            return as_measure(translation_input_5_domestic_financing_central_bank_financing[axis_step(data.LANGUAGE_AXIS, 'English', start_debt_sustainability_analysis_m)], 'str')
        elif instrument == 'Short-term debt' and holder == 'residents':
            return as_measure(translation_st_debt[axis_step(('Maturity', 'Échéance', 'Vencimento', 'Vencimiento'), 'Maturity', start_debt_sustainability_analysis_m)], 'str')
        elif instrument == 'T-bills (denominated in local currency)' and holder == 'residents':
            return as_measure(translation_input_5_domestic_financing_t_bills_denominated_in_local_currency[axis_step(data.LANGUAGE_AXIS, 'English', start_debt_sustainability_analysis_m)], 'str')
        elif instrument == 'T-bills (denominated in foreign currency)' and holder == 'residents':
            return as_measure(translation_input_5_domestic_financing_t_bills_denominated_in_foreign_currency[axis_step(data.LANGUAGE_AXIS, 'English', start_debt_sustainability_analysis_m)], 'str')
        elif instrument == 'MLT debt' and holder == 'residents':
            return as_measure(translation_input_5_domestic_financing_mlt_debt[axis_step(data.LANGUAGE_AXIS, 'English', start_debt_sustainability_analysis_m)], 'str')
        elif instrument == 'Denominated in local currency (LC)' and holder == 'residents':
            return as_measure(translation_input_5_domestic_financing_denominated_in_local_currency_lc[axis_step(data.LANGUAGE_AXIS, 'English', start_debt_sustainability_analysis_m)], 'str')
        elif instrument == 'Bonds (1 to 3 years)-LC' and holder == 'residents':
            return as_measure(translation_input_5_domestic_financing_bonds_1_to_3_years_lc[axis_step(data.LANGUAGE_AXIS, 'English', start_debt_sustainability_analysis_m)], 'str')
        elif instrument == 'Bonds (4 to 7 years)-LC' and holder == 'residents':
            return as_measure(translation_input_5_domestic_financing_bonds_4_to_7_years_lc[axis_step(data.LANGUAGE_AXIS, 'English', start_debt_sustainability_analysis_m)], 'str')
        elif instrument == 'Bonds (beyond 7 years)-LC' and holder == 'residents':
            return as_measure(translation_input_5_domestic_financing_bonds_beyond_7_years_lc[axis_step(data.LANGUAGE_AXIS, 'English', start_debt_sustainability_analysis_m)], 'str')
        elif instrument == 'Denominated in foreign currency (FX)' and holder == 'residents':
            return as_measure((lookup_hti if xl_bool(xl_eq(input5_definition_of_external_domestic_debt, lookup_afg)) else lookup_hnd), 'str')
        elif instrument == 'Bonds (1 to 3 years)-FX' and holder == 'residents':
            return as_measure(translation_input_5_domestic_financing_bonds_1_to_3_years_fx[axis_step(data.LANGUAGE_AXIS, 'English', start_debt_sustainability_analysis_m)], 'str')
        elif instrument == 'Bonds (4 to 7 years)-FX' and holder == 'residents':
            return as_measure(translation_input_5_domestic_financing_bonds_4_to_7_years_fx[axis_step(data.LANGUAGE_AXIS, 'English', start_debt_sustainability_analysis_m)], 'str')
        elif instrument == 'Bonds (beyond 7 years)-FX' and holder == 'residents':
            return as_measure(translation_input_5_domestic_financing_bonds_beyond_7_years_fx[axis_step(data.LANGUAGE_AXIS, 'English', start_debt_sustainability_analysis_m)], 'str')
        return as_measure(input5_instrument_terms_instrument_label[instrument, 'residents'], 'str')

    input5_instrument_terms_instrument_label = CoordinateReader('input5_instrument_terms_instrument_label', data.INPUT5_INSTRUMENT_TERMS_INSTRUMENT_LABEL.required, formula)
    return data.INPUT5_INSTRUMENT_TERMS_INSTRUMENT_LABEL.collect((coord, input5_instrument_terms_instrument_label[coord]) for coord in data.INPUT5_INSTRUMENT_TERMS_INSTRUMENT_LABEL.required)

@publish(data.INPUT5_INTERNAL_INTEREST_RATE_ON_DOMESTIC_DEBT.schema, cells=data.INPUT5_INTERNAL_INTEREST_RATE_ON_DOMESTIC_DEBT.cells)
def input5_internal_interest_rate_on_domestic_debt(*, input5_interest_rate_on_domestic_debt: data.Input5InterestRateOnDomesticDebt, input5_interest_rate_on_domestic_debt_fx_long: data.Input5InterestRateOnDomesticDebtFxLong) -> data.Series[float | str | None]:
    """Lift the internal interest rate on domestic debt from Input 5 instrument terms.

    Derive each instrument/holder/year cell, carrying the prior-period rate forward and applying FX-long and non-resident 2024–2029 overrides.

    Args:
        input5_interest_rate_on_domestic_debt: Input 5 interest rate on domestic debt series indexed over instrument, holder, and time-period coordinates.
        input5_interest_rate_on_domestic_debt_fx_long: Input 5 FX-long interest rate on domestic debt series indexed over the same instrument, holder, and time-period coordinates.

    Returns:
        data.Series[float | str | None] of the internal interest rate on domestic debt, one value per required instrument/holder/time-period coordinate.
    """
    data.INPUT5_INTEREST_RATE_ON_DOMESTIC_DEBT.schema.validate(input5_interest_rate_on_domestic_debt)
    data.INPUT5_INTEREST_RATE_ON_DOMESTIC_DEBT_FX_LONG.schema.validate(input5_interest_rate_on_domestic_debt_fx_long)
    def formula(instrument: str, holder: str, time_period: int) -> float | str | None:
        if instrument == 'Central bank financing' and holder == 'residents' and time_period == 2030:
            return as_measure(input5_interest_rate_on_domestic_debt['Central bank financing', 'residents', time_period - 1])
        elif instrument in ('Bonds (4 to 7 years)-FX', 'Bonds (beyond 7 years)-FX') and holder == 'residents' and time_period == 2030:
            return as_measure(input5_interest_rate_on_domestic_debt_fx_long[instrument, holder, time_period - 1])
        elif instrument in ('T-bills (denominated in local currency)', 'T-bills (denominated in foreign currency)', 'Bonds (1 to 3 years)-LC', 'Bonds (4 to 7 years)-LC', 'Bonds (beyond 7 years)-LC', 'Bonds (1 to 3 years)-FX') and holder == 'residents' and time_period == 2030:
            return as_measure(input5_interest_rate_on_domestic_debt[instrument, holder, time_period - 1])
        elif instrument in ('Bonds (4 to 7 years)-FX', 'Bonds (beyond 7 years)-FX') and holder == 'non-residents' and time_period in (2024, 2025, 2026, 2027, 2028, 2029):
            return as_measure(input5_interest_rate_on_domestic_debt_fx_long[instrument, 'residents', time_period])
        elif instrument == 'Central bank financing' and holder == 'residents' and time_period in (2031, 2032, 2033, 2034, 2035, 2036, 2037, 2038, 2039, 2040, 2041, 2042, 2043, 2044):
            return as_measure(input5_internal_interest_rate_on_domestic_debt['Central bank financing', 'residents', time_period - 1])
        elif instrument in ('T-bills (denominated in local currency)', 'T-bills (denominated in foreign currency)', 'Bonds (1 to 3 years)-LC', 'Bonds (4 to 7 years)-LC', 'Bonds (beyond 7 years)-LC', 'Bonds (1 to 3 years)-FX') and holder == 'non-residents' and time_period in (2024, 2025, 2026, 2027, 2028, 2029):
            return as_measure(input5_interest_rate_on_domestic_debt[instrument, 'residents', time_period])
        return as_measure(input5_internal_interest_rate_on_domestic_debt[instrument, holder, time_period - 1])

    input5_internal_interest_rate_on_domestic_debt = CoordinateReader('input5_internal_interest_rate_on_domestic_debt', data.INPUT5_INTERNAL_INTEREST_RATE_ON_DOMESTIC_DEBT.required, formula)
    return data.INPUT5_INTERNAL_INTEREST_RATE_ON_DOMESTIC_DEBT.collect((coord, input5_internal_interest_rate_on_domestic_debt[coord]) for coord in data.INPUT5_INTERNAL_INTEREST_RATE_ON_DOMESTIC_DEBT.required)

