@publish(data.INPUT5_PUBLIC_GFNS_1_PRIMARY_DEFICIT.schema, cells=data.INPUT5_PUBLIC_GFNS_1_PRIMARY_DEFICIT.cells)
def input5_public_gfns_1_primary_deficit(*, macro_debt_public_sector_revenues_including_grants: data.Series[float | str | None], macro_debt_public_sector_primary_expenditure: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute the Input 5 public-sector primary deficit series.

    Derives the public sector primary deficit by subtracting public sector revenues including grants from primary expenditure across the projection grid.

    Args:
        macro_debt_public_sector_revenues_including_grants: Public sector revenues including grants as a data.Series over catalog coordinates, carrying float values, string labels, or None for blank cells.
        macro_debt_public_sector_primary_expenditure: Public sector primary expenditure as a data.Series over catalog coordinates, carrying float values, string labels, or None for blank cells.

    Returns:
        data.Series[float | str | None] holding the primary deficit keyed by projection years, with the same coordinate layout as the input series.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure(xl_sub(macro_debt_public_sector_primary_expenditure[time_period], macro_debt_public_sector_revenues_including_grants[time_period]))

    return data.INPUT5_PUBLIC_GFNS_1_PRIMARY_DEFICIT.collect(evaluate(formula, data.INPUT5_PUBLIC_GFNS_1_PRIMARY_DEFICIT.required))

@publish(data.INPUT5_PUBLIC_GFNS_2_DEBT_SERVICES_FROM_EXISTING_DEBT.schema, cells=data.INPUT5_PUBLIC_GFNS_2_DEBT_SERVICES_FROM_EXISTING_DEBT.cells)
def input5_public_gfns_2_debt_services_from_existing_debt(*, input5_public_gfns_2_debt_services_from_existing_debt_domestic_including_st_debt_from_previous_year: data.Series[float | str | None], input5_public_gfns_2_debt_services_from_existing_debt_external_debt_mlt: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Sums the domestic and external debt-service components from existing public GFNs debt into a single series keyed by projection years.

    Produces the Input 5 total debt service from existing debt by elementwise addition of its domestic and external components.

    Args:
        input5_public_gfns_2_debt_services_from_existing_debt_domestic_including_st_debt_from_previous_year: Domestic debt service from existing debt, including short-term debt carried over from the previous year, as a named-axis series over projection years whose values may be float, str, or None.
        input5_public_gfns_2_debt_services_from_existing_debt_external_debt_mlt: External debt service from existing debt at medium- and long-term maturity, as a named-axis series over projection years whose values may be float, str, or None.

    Returns:
        A named-axis series over projection years giving total debt service from existing debt, formed by elementwise addition of the domestic and external components; values may be float, str, or None.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure(xl_add(input5_public_gfns_2_debt_services_from_existing_debt_domestic_including_st_debt_from_previous_year[time_period], input5_public_gfns_2_debt_services_from_existing_debt_external_debt_mlt[time_period]))

    return data.INPUT5_PUBLIC_GFNS_2_DEBT_SERVICES_FROM_EXISTING_DEBT.collect(evaluate(formula, data.INPUT5_PUBLIC_GFNS_2_DEBT_SERVICES_FROM_EXISTING_DEBT.required))

@publish(data.INPUT5_PUBLIC_GFNS_2_DEBT_SERVICES_FROM_EXISTING_DEBT_DOMESTIC_INCLUDING_ST_DEBT_FROM_PREVIOUS_YEAR.schema, cells=data.INPUT5_PUBLIC_GFNS_2_DEBT_SERVICES_FROM_EXISTING_DEBT_DOMESTIC_INCLUDING_ST_DEBT_FROM_PREVIOUS_YEAR.cells)
def input5_public_gfns_2_debt_services_from_existing_debt_domestic_including_st_debt_from_previous_year(*, input5_old_debt_debt_service_from_old_debt_residency_based: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Map residency-based old-debt debt service to the Input 5 domestic existing-debt debt-service series.

    Derive the Input 5 public GFNS 2 domestic debt-service series from the existing-debt residency-based source.

    Args:
        input5_old_debt_debt_service_from_old_debt_residency_based: Residency-based debt service from old debt, as a data series keyed by projection years.

    Returns:
        The Input 5 public GFNS 2 debt services from existing debt / domestic, including short-term debt from the previous year, keyed by projection years.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure(input5_old_debt_debt_service_from_old_debt_residency_based[time_period])

    return data.INPUT5_PUBLIC_GFNS_2_DEBT_SERVICES_FROM_EXISTING_DEBT_DOMESTIC_INCLUDING_ST_DEBT_FROM_PREVIOUS_YEAR.collect(evaluate(formula, data.INPUT5_PUBLIC_GFNS_2_DEBT_SERVICES_FROM_EXISTING_DEBT_DOMESTIC_INCLUDING_ST_DEBT_FROM_PREVIOUS_YEAR.required))

@publish(data.INPUT5_PUBLIC_GFNS_2_DEBT_SERVICES_FROM_EXISTING_DEBT_EXTERNAL_DEBT_MLT.schema, cells=data.INPUT5_PUBLIC_GFNS_2_DEBT_SERVICES_FROM_EXISTING_DEBT_EXTERNAL_DEBT_MLT.cells)
def input5_public_gfns_2_debt_services_from_existing_debt_external_debt_mlt(*, input5_macro_nominal_exchange_rate_average_lcu_usd: data.Series[float | str | None], ext_debt_total_including_locally_issued: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute debt services from existing debt / external debt (MLT) on Input 5, keyed by projection year.

    Convert the external debt stock including locally issued debt into an external debt-service (MLT) path using the Input 5 average nominal exchange rate.

    Args:
        input5_macro_nominal_exchange_rate_average_lcu_usd: Average nominal exchange rate (LCU per USD) series over the Input 5 projection-year grid; entries may be floats, or str/None placeholders where the grid is blank.
        ext_debt_total_including_locally_issued: Series of total external debt including locally issued debt over the same projection-year grid, with float values or str/None blanks.

    Returns:
        data.Series[float | str | None] of debt services from existing debt / external debt (MLT) on Input 5, whose keys are the projection years and whose values are the per-year products of the two inputs (blanks preserved as str or None).
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure(xl_mul(ext_debt_total_including_locally_issued[time_period], input5_macro_nominal_exchange_rate_average_lcu_usd[time_period]))

    return data.INPUT5_PUBLIC_GFNS_2_DEBT_SERVICES_FROM_EXISTING_DEBT_EXTERNAL_DEBT_MLT.collect(evaluate(formula, data.INPUT5_PUBLIC_GFNS_2_DEBT_SERVICES_FROM_EXISTING_DEBT_EXTERNAL_DEBT_MLT.required))

@publish(data.INPUT5_PUBLIC_GFNS_2_DEBT_SERVICES_FROM_EXISTING_DEBT_OW_IMF.schema, cells=data.INPUT5_PUBLIC_GFNS_2_DEBT_SERVICES_FROM_EXISTING_DEBT_OW_IMF.cells)
def input5_public_gfns_2_debt_services_from_existing_debt_ow_imf(*, ext_debt_old_mlt_debt_service: data.Series[float | str | None], input5_macro_nominal_exchange_rate_average_lcu_usd: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Computes Input 5 public GFNS 2 debt services from existing debt owed to the IMF by converting old external MLT debt service at the average LCU/USD exchange rate.

    Derives the projection-year debt-service series for existing IMF debt within the public GFNS Input 5 block.

    Args:
        ext_debt_old_mlt_debt_service: Typed data series of old external medium- and long-term debt service, indexed over catalog coordinates including the IMF creditor dimension and keyed by projection years.
        input5_macro_nominal_exchange_rate_average_lcu_usd: Typed data series of Input 5 macro nominal average exchange rates in local currency units per U.S. dollar, keyed by projection years.

    Returns:
        Typed data series of Input 5 public GFNS 2 debt services from existing debt o/w IMF, keyed by projection years; values are the IMF old external MLT debt service converted to local currency using the average LCU/USD exchange rate, or None where formula inputs are unavailable.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure(xl_mul(ext_debt_old_mlt_debt_service['IMF', time_period], input5_macro_nominal_exchange_rate_average_lcu_usd[time_period]))

    return data.INPUT5_PUBLIC_GFNS_2_DEBT_SERVICES_FROM_EXISTING_DEBT_OW_IMF.collect(evaluate(formula, data.INPUT5_PUBLIC_GFNS_2_DEBT_SERVICES_FROM_EXISTING_DEBT_OW_IMF.required))

