    def formula(time_period: int) -> float | str | None:
        return as_measure((xl_add((0 if xl_bool(xl_eq(input5_maturity_central_bank, 1)) else input5_new_issuance['Central bank financing', 'residents', time_period]), input5_new_issuance_mlt_debt['residents', time_period]) if xl_bool(xl_eq(input5_definition_of_external_domestic_debt, lookup_afg)) else xl_add((0 if xl_bool(xl_eq(input5_maturity_central_bank, 1)) else input5_new_issuance['Central bank financing', 'residents', time_period]), input5_new_issuance_denominated_in_local_currency_lc['residents', time_period])))

    return data.INPUT5_DISBURSEMENTS_PUBLIC_DOMESTIC_MLT_DISBURSEMENTS_RESIDENCY_BASED.collect(evaluate(formula, data.INPUT5_DISBURSEMENTS_PUBLIC_DOMESTIC_MLT_DISBURSEMENTS_RESIDENCY_BASED.required))

