    def formula(holder: str, time_period: int) -> float | str | None:
        if time_period == 2023:
            return as_measure((input3_domestic_outstanding_of_existing_debt['local', holder, time_period] if xl_bool(xl_isnumber(lambda: input3_domestic_outstanding_of_existing_debt['local', holder, time_period])) else 0))
