@publish(data.CHART_PROJECTION_YEARS.schema, cells=data.CHART_PROJECTION_YEARS.cells)
def chart_projection_years(*, macro_debt_main_assumptions_further_details: int | str, macro_debt_further_details: data.Series[int | str | None]) -> data.Series[int | str | None]:
    """Build the Chart Data projection-year series from Macro-Debt_Data assumptions and further details.

    Map projection-year values from Macro-Debt_Data onto the Chart Data row 35 year axis.

    Args:
        macro_debt_main_assumptions_further_details: Scalar int | str projection-year value used for 2024 in the chart projection-year series.
        macro_debt_further_details: Named-axis data.Series[int | str | None] of Macro-Debt projection-year details indexed by year, supplying all non-2024 chart values.

    Returns:
        Named-axis data.Series[int | str | None] over CHART_PROJECTION_YEARS with the 2024 scalar and per-year further-details values.
    """
    def formula(time_period: int) -> int | str | None:
        if time_period == 2024:
            return as_measure(macro_debt_main_assumptions_further_details, 'int')
        return as_measure(macro_debt_further_details[time_period], 'int')

    return data.CHART_PROJECTION_YEARS.collect(evaluate(formula, data.CHART_PROJECTION_YEARS.required))

