@publish(data.CHART_INTERNAL_CHART_DATA_PV_OF_DEBT_TO_GDP_RATIO_PV_DEBT_TO_GDP_STRESS_PATH.schema, cells=data.CHART_INTERNAL_CHART_DATA_PV_OF_DEBT_TO_GDP_RATIO_PV_DEBT_TO_GDP_STRESS_PATH.cells)
def chart_internal_chart_data_pv_of_debt_to_gdp_ratio_pv_debt_to_gdp_stress_path(*, dsa_pub_pv_of_total_public_debt: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Map public PV debt stress scenarios to the Chart Data PV debt-to-GDP stress-path series.

    Selects B2 and B6 market and non-market stress paths from the public PV of total public debt series and reindexes them onto the Chart Data stress-path coordinate.

    Args:
        dsa_pub_pv_of_total_public_debt: Public PV of total public debt series keyed by scenario and time period, supplying the B2/B6 market and non-market stress-path values.

    Returns:
        A data.Series[float | str | None] of PV of Debt-to-GDP Ratio on Chart Data, keyed by scenario and stress_path.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        if scenario == 'B2.1 Primary balance Market':
            return as_measure(dsa_pub_pv_of_total_public_debt['B2_mkt', time_period])
        elif scenario == 'B2.2 Primary balance Non-Market':
            return as_measure(dsa_pub_pv_of_total_public_debt['B2_nonmkt', time_period])
        elif scenario == 'B6.1 Combination of B1-B5 Market':
            return as_measure(dsa_pub_pv_of_total_public_debt['B6_mkt', time_period])
        return as_measure(dsa_pub_pv_of_total_public_debt['B6_nonmkt', time_period])

    return data.CHART_INTERNAL_CHART_DATA_PV_OF_DEBT_TO_GDP_RATIO_PV_DEBT_TO_GDP_STRESS_PATH.collect(evaluate(formula, data.CHART_INTERNAL_CHART_DATA_PV_OF_DEBT_TO_GDP_RATIO_PV_DEBT_TO_GDP_STRESS_PATH.required))

