@publish(data.EXT_DEBT_MARGINAL_SHARE_DOMESTIC_MLT.schema, cells=data.EXT_DEBT_MARGINAL_SHARE_DOMESTIC_MLT.cells)
def ext_debt_marginal_share_domestic_mlt(*, input5_disbursements_public_domestic_mlt_disbursements_residency_based: data.Series[float | str | None], ext_debt_new_disbursements_public_total: data.Series[float | str | None], ext_debt_exchange_rate_period_average: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute the yearly marginal share of domestic medium- and long-term public disbursements in total new public external debt disbursements.

    Derive the residual-financing share of domestic MLT debt after converting disbursements at the period-average exchange rate.

    Args:
        input5_disbursements_public_domestic_mlt_disbursements_residency_based: Residency-based domestic medium- and long-term public disbursements from Input 5, as a typed series over catalog coordinates.
        ext_debt_new_disbursements_public_total: Total new public external debt disbursements for the period, as a typed series over catalog coordinates.
        ext_debt_exchange_rate_period_average: Period-average exchange rate used to convert domestic disbursements into the external-debt numerator, as a typed series over catalog coordinates.

    Returns:
        A typed series of yearly domestic medium- and long-term marginal shares, computed as domestic MLT disbursements converted by the period-average exchange rate and divided by total new public external disbursements.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure(xl_div(xl_div(input5_disbursements_public_domestic_mlt_disbursements_residency_based[time_period], ext_debt_exchange_rate_period_average[time_period]), ext_debt_new_disbursements_public_total[time_period]))

    return data.EXT_DEBT_MARGINAL_SHARE_DOMESTIC_MLT.collect(evaluate(formula, data.EXT_DEBT_MARGINAL_SHARE_DOMESTIC_MLT.required))

