@publish(data.EXT_DEBT_PV_OLD_MLT_BY_INSTRUMENT.schema, cells=data.EXT_DEBT_PV_OLD_MLT_BY_INSTRUMENT.cells)
def ext_debt_pv_old_mlt_by_instrument(*, input4_discount_rate: data.Series[float | str | None], ext_debt_old_mlt_debt_service: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Present value of old MLT debt by financing instrument.

    Computes each instrument's present value of old MLT debt, rolling up sub-instruments into their parent groups and discounting remaining debt service streams.

    Args:
        input4_discount_rate: Discount rate input, a named-axis series of per-instrument rates over the financing-instrument coordinate, used to discount each instrument's remaining debt service.
        ext_debt_old_mlt_debt_service: Old MLT debt service by financing instrument and projection year, a named-axis series over the instrument and time-period coordinates from which each instrument's future service stream is taken.

    Returns:
        A named-axis series of present values over the financing-instrument coordinate, with parent instruments aggregating their sub-instruments and undiscounted values carried through where applicable.
    """
    def formula(instrument: str, time_period: int) -> float | str | None:
        if instrument == 'Multilaterals':
            return as_measure(xl_sum(view(ext_debt_pv_old_mlt_by_instrument, rows=('IMF', 'IDA - regular', 'IDA - 50Y loans', 'IDA - SML', 'MULTI1', 'MULTI2'), cols=(time_period,))))
