@publish(data.EXT_DEBT_PV_OLD_LOCALLY_ISSUED.schema, cells=data.EXT_DEBT_PV_OLD_LOCALLY_ISSUED.cells)
def ext_debt_pv_old_locally_issued(*, ext_debt_locally_issued_evolution: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute the present value of old locally issued external debt.

    Derive present-value terms for old locally issued external debt under the assumption of a zero grant element.

    Args:
        ext_debt_locally_issued_evolution: Evolution of locally issued external debt as a named-axis series over catalog time coordinates; values are floats, strings, or None.

    Returns:
        A named-axis series over catalog time coordinates containing the present value of old locally issued external debt; entries are floats, strings, or None.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure(ext_debt_locally_issued_evolution[time_period])

    return data.EXT_DEBT_PV_OLD_LOCALLY_ISSUED.collect(evaluate(formula, data.EXT_DEBT_PV_OLD_LOCALLY_ISSUED.required))

