def imported_country_code(*, in1_basics_country_code: int | str) -> int | str:
    """Return the IMF country code imported from Input 1.

    Expose Input 1's country identifier as a scalar value for downstream bindings.

    Args:
        in1_basics_country_code: IMF country code copied from Input 1, supplied as a scalar integer code or string label.

    Returns:
        The IMF country code as an int or str; if the value cannot be measured as an int, the corresponding XL error code string is returned.
    """
    try:
        return as_measure(in1_basics_country_code, 'int')
    except XlError as error:
        return error.code

@publish(data.IMPORTED_CLASSIFICATION_YEARS.schema, cells=data.IMPORTED_CLASSIFICATION_YEARS.cells)
def imported_classification_years(*, classification_cpia_reported_years: data.Series[int | str | None]) -> data.Series[int | str | None]:
    """Derive imported classification-window years from CPIA-reported years by anchoring 2024 and extending the series backward and forward one year at a time.

    Build the classification-window year series aligned to the projection vintage for downstream LIC-DSF extraction.

    Args:
        classification_cpia_reported_years: Keyword-only typed data.Series[int | str | None] of CPIA-reported classification years over catalog coordinates; its 2024 value anchors the derived imported classification years.

    Returns:
        A typed data.Series[int | str | None] of imported classification-window years aligned to the projection vintage on row 37, with non-anchor years filled from the recursively derived ±1 offsets.
    """
    data.CLASSIFICATION_CPIA_REPORTED_YEARS.schema.validate(classification_cpia_reported_years)
    def formula(time_period: int) -> int | str | None:
        if time_period == 2024:
            return as_measure(classification_cpia_reported_years[2024], 'int')
        elif time_period >= 2025:
            return as_measure(xl_add(imported_classification_years[time_period - 1], 1), 'int')
        return as_measure(xl_sub(imported_classification_years[time_period + 1], 1), 'int')

    imported_classification_years = CoordinateReader('imported_classification_years', data.IMPORTED_CLASSIFICATION_YEARS.required, formula)
    return data.IMPORTED_CLASSIFICATION_YEARS.collect((coord, imported_classification_years[coord]) for coord in data.IMPORTED_CLASSIFICATION_YEARS.required)

