@publish(data.IMPORTED_CLASSIFICATION_IDS.schema, cells=data.IMPORTED_CLASSIFICATION_IDS.cells)
def imported_classification_ids(*, imported_series_stub_cpia: str, imported_series_stub_gr_a: str, imported_series_stub_res_a: str, imported_series_stub_wgr: str, imported_components: data.Series[int | str | None]) -> data.Series[str | int | float | bool | None]:
    """Build indicator-specific classification lookup keys by concatenating series stubs with imported component values.

    Map imported indicator and time-period coordinates to the INDEX/MATCH keys used for classification lookups.

    Args:
        imported_series_stub_cpia: Scalar string stub prefix for the CPIA indicator classification key.
        imported_series_stub_gr_a: Scalar string stub prefix for the real growth rate indicator classification key.
        imported_series_stub_res_a: Scalar string stub prefix for the import coverage of reserves indicator classification key.
        imported_series_stub_wgr: Scalar string stub prefix for the weighted growth rate indicator classification key.
        imported_components: Typed data.Series[int | str | None] of component identifiers, indexed by required catalog coordinates, supplying the year or component suffix for each constructed classification key.

    Returns:
        Typed data.Series[str | int | float | bool | None] of constructed classification lookup keys (prefix plus year) used by INDEX/MATCH, indexed by the required IMPORTED_CLASSIFICATION_IDS coordinates.
    """
    def formula(indicator: str, time_period: int) -> str | int | float | bool | None:
        if indicator == 'CPIA':
            return as_measure(xl_concat(imported_series_stub_cpia, imported_components[time_period]), 'str')
        elif indicator == 'Real growth rate \n(in percent)':
            return as_measure(xl_concat(imported_series_stub_gr_a, imported_components[time_period]), 'str')
        elif indicator == 'Import coverage of reserves\n(in percent)':
            return as_measure(xl_concat(imported_series_stub_res_a, imported_components[time_period]), 'str')
        return as_measure(xl_concat(imported_series_stub_wgr, imported_components[time_period]), 'str')

    return data.IMPORTED_CLASSIFICATION_IDS.collect(evaluate(formula, data.IMPORTED_CLASSIFICATION_IDS.required))

