@publish(key=(), domain=None, cells=data.IMPORTED_EUROBOND_HEADER_CELLS)
def imported_eurobond_header(*, trigger_right_headers: data.Series[str | None]) -> str | int | float | bool:
    """Extracts the Eurobond column header from the Trigger right-header series.

    Resolves the dynamic Eurobond column title used for imported-Eurobond extraction.

    Args:
        trigger_right_headers: A typed data.Series[str | None] of Eurobond column titles copied from Trigger, where each element is a string or None for missing labels.

    Returns:
        The Eurobond header as a string when present, otherwise the captured Excel error code as an int, float, or bool.
    """
    data.TRIGGER_RIGHT_HEADERS.schema.validate(trigger_right_headers)
    try:
        return as_measure(trigger_right_headers['Eurobond'], 'str')
    except XlError as error:
        return error.code

