@publish(data.IMPORTED_CPIA_YEAR_HEADERS.schema, cells=data.IMPORTED_CPIA_YEAR_HEADERS.cells)
def imported_cpia_year_headers(*, probability_scenario_years: data.Series[int | str | None]) -> data.Series[int | str | None]:
    """Compute imported CPIA year headers.

    Produce the year-header series for the CPIA row used by the probability approach.

    Args:
        probability_scenario_years: Series of probability-scenario years over catalog coordinates, with integer, string, or None values.

    Returns:
        Series of imported CPIA year headers over catalog coordinates, with integer, string, or None values.
    """
    def formula(time_period: int) -> int | str | None:
        if time_period == 2024:
            return as_measure(probability_scenario_years[time_period], 'int')
        elif time_period >= 2025:
            return as_measure(xl_add(imported_cpia_year_headers[time_period - 1], 1), 'int')
        return as_measure(xl_sub(imported_cpia_year_headers[time_period + 1], 1), 'int')

    imported_cpia_year_headers = CoordinateReader('imported_cpia_year_headers', data.IMPORTED_CPIA_YEAR_HEADERS.required, formula)
    return data.IMPORTED_CPIA_YEAR_HEADERS.collect((coord, imported_cpia_year_headers[coord]) for coord in data.IMPORTED_CPIA_YEAR_HEADERS.required)

@publish(data.PROBABILITY_DEBT_CARRYING_CAPACITY_PATHS.schema, cells=data.PROBABILITY_DEBT_CARRYING_CAPACITY_PATHS.cells)
def probability_debt_carrying_capacity_paths(*, probability_background_macro: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute probability-approach debt-carrying-capacity paths from averaged background macro indicators.

    Populates each required probability coordinate with capacity paths derived from averaged CPIA, growth, reserves, remittances, and world growth inputs.

    Args:
        probability_background_macro: Background macro series containing CPIA, real GDP growth, reserves/imports, remittances/GDP, and world economic growth, with float, str, or None values averaged over the probability horizon.

    Returns:
        A data.Series[float | str | None] of probability debt-carrying-capacity paths indexed by the required probability coordinates, using the averaged background macro measures.
    """
    def formula(indicator: str, time_period: int) -> float | str | None:
        if indicator == 'CPIA' and time_period == 2024:
            return as_measure(xl_average(view(probability_background_macro, rows=(indicator,), cols=span(data.TIME_PERIOD_AXIS, time_period - 5, time_period + 10))))
        elif indicator == 'Real GDP Growth' and time_period == 2024:
            return as_measure(xl_average(view(probability_background_macro, rows=('Real growth rate',), cols=span(data.TIME_PERIOD_AXIS, time_period - 5, time_period + 10))))
        elif indicator == 'Reserves' and time_period == 2024:
            return as_measure(xl_average(view(probability_background_macro, rows=(f'{indicator} / imports ratio',), cols=span(data.TIME_PERIOD_AXIS, time_period - 5, time_period + 10))))
        elif indicator == 'Remittances' and time_period == 2024:
            return as_measure(xl_average(view(probability_background_macro, rows=('Remitances / GDP ratio',), cols=span(data.TIME_PERIOD_AXIS, time_period - 5, time_period + 10))))
        elif indicator == 'World Growth' and time_period == 2024:
            return as_measure(xl_average(view(probability_background_macro, rows=('World economic growth rate',), cols=span(data.TIME_PERIOD_AXIS, time_period - 5, time_period + 10))))
        return as_measure(probability_debt_carrying_capacity_paths[indicator, 2024])

    probability_debt_carrying_capacity_paths = CoordinateReader('probability_debt_carrying_capacity_paths', data.PROBABILITY_DEBT_CARRYING_CAPACITY_PATHS.required, formula)
    return data.PROBABILITY_DEBT_CARRYING_CAPACITY_PATHS.collect((coord, probability_debt_carrying_capacity_paths[coord]) for coord in data.PROBABILITY_DEBT_CARRYING_CAPACITY_PATHS.required)

