@publish(data.REALISM1_EXTERNAL_YEAR_HEADERS.schema, cells=data.REALISM1_EXTERNAL_YEAR_HEADERS.cells)
def realism1_external_year_headers(*, output_submit_first_projection_year: int | str) -> data.Series[int | str | None]:
    """Compute the Realism 1 external forecast-error year headers.

    Populates the coordinate-indexed year-header series used to align external forecast-error calculations across projection years.

    Args:
        output_submit_first_projection_year: Scalar first-projection-year value, supplied as an integer year or string representation; it anchors the 2024 header, with surrounding headers derived by one-year offsets.

    Returns:
        A data.Series[int | str | None] mapping each catalog coordinate to its external forecast-error year header, with null values where a header is not required.
    """
    def formula(time_period: int) -> int | str | None:
        if time_period == 2024:
            return as_measure(output_submit_first_projection_year, 'int')
        elif time_period <= 2023:
            return as_measure(xl_sub(realism1_external_year_headers[time_period + 1], 1), 'int')
        return as_measure(xl_add(realism1_external_year_headers[time_period - 1], 1), 'int')

    realism1_external_year_headers = CoordinateReader('realism1_external_year_headers', data.REALISM1_EXTERNAL_YEAR_HEADERS.required, formula)
    return data.REALISM1_EXTERNAL_YEAR_HEADERS.collect((coord, realism1_external_year_headers[coord]) for coord in data.REALISM1_EXTERNAL_YEAR_HEADERS.required)

@publish(data.REALISM1_PUBLIC_YEAR_HEADERS.schema, cells=data.REALISM1_PUBLIC_YEAR_HEADERS.cells)
def realism1_public_year_headers(*, realism1_current_vintage_year: int | str) -> data.Series[int | str | None]:
    """Compute public forecast-error year headers for the Realism 1 tool.

    Anchor the 2024 column to the current vintage year and recursively extend the year sequence backwards and forwards across the catalog time-period coordinates.

    Args:
        realism1_current_vintage_year: Current vintage year (int or str) that supplies the 2024 header; earlier time periods are derived by decrementing and later periods by incrementing from it.

    Returns:
        A typed series over time-period coordinates whose values are the derived year headers (int or str), with None for unresolved or out-of-range periods.
    """
    def formula(time_period: int) -> int | str | None:
        if time_period == 2024:
            return as_measure(realism1_current_vintage_year, 'int')
        elif time_period <= 2023:
            return as_measure(xl_sub(realism1_public_year_headers[time_period + 1], 1), 'int')
        return as_measure(xl_add(realism1_public_year_headers[time_period - 1], 1), 'int')

    realism1_public_year_headers = CoordinateReader('realism1_public_year_headers', data.REALISM1_PUBLIC_YEAR_HEADERS.required, formula)
    return data.REALISM1_PUBLIC_YEAR_HEADERS.collect((coord, realism1_public_year_headers[coord]) for coord in data.REALISM1_PUBLIC_YEAR_HEADERS.required)

