    return data.BASELINE_PUB_RECOGNITION_OF_CONTINGENT_LIAB_E_G_BANK.collect(evaluate(formula, data.BASELINE_PUB_RECOGNITION_OF_CONTINGENT_LIAB_E_G_BANK.required))

