@publish(key=(), domain=None, cells=data.IN6_TAILORED_SHARE_OF_COMMODITIES_IN_TOTAL_EXPORTS_OF_GOODS_CELLS)
def in6_tailored_share_of_commodities_in_total_exports_of_goods(*, input6_tailored_params_2: data.Series[float | str | None]) -> float | str:
    """Compute the share of commodities in total exports of goods and services from component export shares.

    Derives the Input 6 tailored commodity-share single-cell anchor by summing the fuel and non-fuel export share components.

    Args:
        input6_tailored_params_2: Keyword-only typed data.Series over catalog coordinates carrying the fuel and non-fuel export share components used to total the commodity share; values may be float, str, or None.

    Returns:
        Scalar float share of commodities in total exports of goods and services, or a string error code if evaluation raises an XlError.
    """
    try:
        return as_measure(xl_add(input6_tailored_params_2['fuel_share_exports'], input6_tailored_params_2['nonfuel_share_exports']))
    except XlError as error:
        return error.code

@publish(key=(), domain=None, cells=data.IN6_TAILORED_ADJUSTED_SHARE_OF_COMMODITIES_IN_TOTAL_EXPORTS_CELLS)
def in6_tailored_adjusted_share_of_commodities_in_total_exports(*, in6_tailored_adjusted_share_of_fuel_in_exports_of_g_s: data.Series[float | str | None], in6_tailored_adjusted_share_of_non_fuel_in_exports_of_g_s: data.Series[float | str | None]) -> float | str:
    """Compute the tailored adjusted share of commodities in total exports.

    Adds the fuel and non-fuel export-share series at their 'User defined' coordinate to obtain the commodity total.

    Args:
        in6_tailored_adjusted_share_of_fuel_in_exports_of_g_s: data.Series[float | str | None] of the tailored adjusted share of fuel in exports of goods and services, evaluated at the 'User defined' coordinate.
        in6_tailored_adjusted_share_of_non_fuel_in_exports_of_g_s: data.Series[float | str | None] of the tailored adjusted share of non-fuel in exports of goods and services, evaluated at the 'User defined' coordinate.

    Returns:
        The scalar float sum of the fuel and non-fuel shares at the 'User defined' coordinate, or the spreadsheet error code string if the addition raises XlError.
    """
    try:
        return as_measure(xl_add(in6_tailored_adjusted_share_of_fuel_in_exports_of_g_s['User defined'], in6_tailored_adjusted_share_of_non_fuel_in_exports_of_g_s['User defined']))
    except XlError as error:
        return error.code

@dataclass(frozen=True, slots=True)
class ScanIn6TailoredAdjustedShareOfFuelInExportsOfGSResult:
    """Complete named results of one recurrence group evaluation."""
    in6_tailored_adjusted_share_of_fuel_in_exports_of_g_s: data.Series[float | str | None]
    in6_tailored_adjusted_share_of_non_fuel_in_exports_of_g_s: data.Series[float | str | None]
    in6_tailored_average_of_prices_shock_default: float | str
    input6_tailored_params_2: data.Series[float | str | None]

def scan_in6_tailored_adjusted_share_of_fuel_in_exports_of_g_s(*, input6_tailored_tests_enabled: Literal["Off", "On"], in6_tailored_price_shock_non_fuel: data.Series[float | str | None], in6_tailored_natdisaster_shock_size_default: float | str, in6_tailored_commodity_close_gap_default: float | str, in6_tailored_share_of_fuel_in_exports_of_g_s_default: float | str, in6_tailored_share_of_non_fuel_in_exports_of_g_s_default: float | str, in6_tailored_mitigating_factor_fuel_default: float | str, in6_tailored_mitigating_factor_non_fuel_default: float | str, in6_tailored_mkt_fin_borrowing_cost_default: float | str, in6_tailored_mkt_fin_maturity_defaults: data.Series[float | str | None], in6_tailored_mkt_fin_fx_depreciation_default: float | str, input6_tailored_params_fuel_label: str | int | float | bool) -> ScanIn6TailoredAdjustedShareOfFuelInExportsOfGSResult:
    """Evaluate the recurrence group `in6_tailored_adjusted_share_of_fuel_in_exports_of_g_s`, `in6_tailored_adjusted_share_of_non_fuel_in_exports_of_g_s`, `in6_tailored_average_of_prices_shock_default`, `input6_tailored_params_2` and publish complete tensors."""
    def in6_tailored_adjusted_share_of_fuel_in_exports_of_g_s_formula(variant: str) -> float | str | None:
        if variant == 'Default':
            return as_measure(xl_max(0, xl_sub(in6_tailored_share_of_fuel_in_exports_of_g_s_default, in6_tailored_mitigating_factor_fuel_default)))
        return as_measure(xl_max(0, xl_sub(input6_tailored_params_2['fuel_share_exports'], input6_tailored_params_2['fuel_price'])))

    in6_tailored_adjusted_share_of_fuel_in_exports_of_g_s = CoordinateReader('in6_tailored_adjusted_share_of_fuel_in_exports_of_g_s', data.IN6_TAILORED_ADJUSTED_SHARE_OF_FUEL_IN_EXPORTS_OF_G_S.required, in6_tailored_adjusted_share_of_fuel_in_exports_of_g_s_formula)
    def in6_tailored_adjusted_share_of_non_fuel_in_exports_of_g_s_formula(variant: str) -> float | str | None:
        if variant == 'Default':
            return as_measure(xl_max(0, xl_sub(in6_tailored_share_of_non_fuel_in_exports_of_g_s_default, in6_tailored_mitigating_factor_non_fuel_default)))
        return as_measure(xl_max(0, xl_sub(input6_tailored_params_2['nonfuel_share_exports'], input6_tailored_params_2['nonfuel_price'])))

    in6_tailored_adjusted_share_of_non_fuel_in_exports_of_g_s = CoordinateReader('in6_tailored_adjusted_share_of_non_fuel_in_exports_of_g_s', data.IN6_TAILORED_ADJUSTED_SHARE_OF_NON_FUEL_IN_EXPORTS_OF_G_S.required, in6_tailored_adjusted_share_of_non_fuel_in_exports_of_g_s_formula)
    def in6_tailored_average_of_prices_shock_default_formula() -> float | str:
        return as_measure(((xl_div(xl_add(xl_mul(input6_tailored_params_fuel_label, in6_tailored_adjusted_share_of_fuel_in_exports_of_g_s['Default']), xl_mul(in6_tailored_price_shock_non_fuel['Default'], in6_tailored_adjusted_share_of_non_fuel_in_exports_of_g_s['Default'])), xl_add(in6_tailored_adjusted_share_of_fuel_in_exports_of_g_s['Default'], in6_tailored_adjusted_share_of_non_fuel_in_exports_of_g_s['Default'])) if xl_bool(xl_isnumber(lambda: xl_div(xl_add(xl_mul(input6_tailored_params_fuel_label, in6_tailored_adjusted_share_of_fuel_in_exports_of_g_s['Default']), xl_mul(in6_tailored_price_shock_non_fuel['Default'], in6_tailored_adjusted_share_of_non_fuel_in_exports_of_g_s['Default'])), xl_add(in6_tailored_adjusted_share_of_fuel_in_exports_of_g_s['Default'], in6_tailored_adjusted_share_of_non_fuel_in_exports_of_g_s['Default'])))) else 0) if xl_bool(xl_eq(input6_tailored_tests_enabled, 'On')) else 0))

    in6_tailored_average_of_prices_shock_default = CoordinateReader('in6_tailored_average_of_prices_shock_default', Domain.product(), in6_tailored_average_of_prices_shock_default_formula)
    def input6_tailored_params_2_formula(parameter: str) -> float | str | None:
        PARAMETER_TO_IN6_TAILORED_MKT_FIN_MATURITY_DEFAULTS_INDICATOR = {'new_maturity_if_gt_5y_1': 'If original maturity is greater than 5 years, new maturity is', 'new_maturity_if_gt_5y_2': 'If original maturity is less than 5 years, new maturity is shortened by', 'new_maturity_if_gt_5y_3': 'Shortening of grace period, for 3 years: shortened by'}
        if parameter == 'mkt_ppg_debt_gdp_shock':
            return as_measure(in6_tailored_natdisaster_shock_size_default)
        elif parameter == 'commodity_export_gdp_gap_years':
            return as_measure(in6_tailored_commodity_close_gap_default)
        elif parameter == 'fuel_share_exports':
            return as_measure(in6_tailored_share_of_fuel_in_exports_of_g_s_default)
        elif parameter == 'nonfuel_share_exports':
            return as_measure(in6_tailored_share_of_non_fuel_in_exports_of_g_s_default)
        elif parameter == 'avg_price_shock':
            return as_measure(in6_tailored_average_of_prices_shock_default[()])
        elif parameter == 'fuel_price':
            return as_measure(in6_tailored_mitigating_factor_fuel_default)
        elif parameter == 'nonfuel_price':
            return as_measure(in6_tailored_mitigating_factor_non_fuel_default)
        elif parameter == 'mkt_financing_shock_on':
            return as_measure(in6_tailored_mkt_fin_borrowing_cost_default)
        elif parameter == 'fx_depreciation':
            return as_measure(in6_tailored_mkt_fin_fx_depreciation_default)
        return as_measure(in6_tailored_mkt_fin_maturity_defaults[PARAMETER_TO_IN6_TAILORED_MKT_FIN_MATURITY_DEFAULTS_INDICATOR[parameter]])

    input6_tailored_params_2 = CoordinateReader('input6_tailored_params_2', data.INPUT6_TAILORED_PARAMS_2.required, input6_tailored_params_2_formula)
    return ScanIn6TailoredAdjustedShareOfFuelInExportsOfGSResult(
        in6_tailored_adjusted_share_of_fuel_in_exports_of_g_s=data.IN6_TAILORED_ADJUSTED_SHARE_OF_FUEL_IN_EXPORTS_OF_G_S.collect((coord, in6_tailored_adjusted_share_of_fuel_in_exports_of_g_s[coord]) for coord in data.IN6_TAILORED_ADJUSTED_SHARE_OF_FUEL_IN_EXPORTS_OF_G_S.required),
        in6_tailored_adjusted_share_of_non_fuel_in_exports_of_g_s=data.IN6_TAILORED_ADJUSTED_SHARE_OF_NON_FUEL_IN_EXPORTS_OF_G_S.collect((coord, in6_tailored_adjusted_share_of_non_fuel_in_exports_of_g_s[coord]) for coord in data.IN6_TAILORED_ADJUSTED_SHARE_OF_NON_FUEL_IN_EXPORTS_OF_G_S.required),
        in6_tailored_average_of_prices_shock_default=in6_tailored_average_of_prices_shock_default[()],
        input6_tailored_params_2=data.INPUT6_TAILORED_PARAMS_2.collect((coord, input6_tailored_params_2[coord]) for coord in data.INPUT6_TAILORED_PARAMS_2.required),
    )

@publish(data.IN6_TAILORED_PRICE_SHOCK_NON_FUEL.schema, cells=data.IN6_TAILORED_PRICE_SHOCK_NON_FUEL.cells)
def in6_tailored_price_shock_non_fuel(*, in6_tailored_commodity_group_price_shock: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute the non-fuel tailored price shock.

    Derive the Input 6 non-fuel tailored commodity price shock from the four tailored commodity-group price shocks.

    Args:
        in6_tailored_commodity_group_price_shock: Tailored commodity-group price shock series over the non-fuel commodity groups, with values that may be numeric, text, or None.

    Returns:
        A data.Series[float | str | None] of the non-fuel tailored price shock, keyed by column labels from row 16; each value is 0 when all four commodity-group shocks are blank, otherwise the average of the four non-fuel commodity-group shocks.
    """
    def formula(variant: str) -> float | str | None:
        return as_measure((0 if xl_bool(xl_and(xl_eq(in6_tailored_commodity_group_price_shock['1) Base metal (e.g., iron, copper, nickel, bauxite, etc.)', variant], ''), xl_eq(in6_tailored_commodity_group_price_shock['2) Precious metal (e.g., gold, silver, platinum, etc.)', variant], ''), xl_eq(in6_tailored_commodity_group_price_shock['3) Grain (e.g., wheat, corn, soybeans, etc.)', variant], ''), xl_eq(in6_tailored_commodity_group_price_shock['4) Other agricultural commodities (e.g., coffee, cocoa, tea, etc.)', variant], ''))) else xl_average(view(in6_tailored_commodity_group_price_shock, rows=span(data.COMMODITY_AXIS, '1) Base metal (e.g., iron, copper, nickel, bauxite, etc.)', '4) Other agricultural commodities (e.g., coffee, cocoa, tea, etc.)'), cols=(variant,)))))

    return data.IN6_TAILORED_PRICE_SHOCK_NON_FUEL.collect(evaluate(formula, data.IN6_TAILORED_PRICE_SHOCK_NON_FUEL.required))

@publish(data.IN6_TAILORED_COMMODITY_GROUP_PRICE_SHOCK.schema, cells=data.IN6_TAILORED_COMMODITY_GROUP_PRICE_SHOCK.cells)
def in6_tailored_commodity_group_price_shock(*, input6_commodity_group_relevant: data.Input6CommodityGroupRelevant, imported_commodity_prices: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute tailored non-fuel commodity-group price shocks.

    Derive Input 6 tailored commodity-group price shocks from relevance selections and imported commodity price percent changes.

    Args:
        input6_commodity_group_relevant: Named-axis tensor over commodity groups containing the Input 6 commodity-group relevance selections, interpreted through the template's Yes/No logic.
        imported_commodity_prices: Named-axis tensor over imported commodity prices and measures, providing the percent-change values used after mapping each relevant commodity group to its imported commodity.

    Returns:
        data.Series of tailored non-fuel commodity-group price shocks keyed by commodity group and Default/User-defined variant; entries are mapped imported price percent changes for relevant groups, otherwise blanks, with User-defined variants mirroring Default.
    """
    data.INPUT6_COMMODITY_GROUP_RELEVANT.schema.validate(input6_commodity_group_relevant)
    def formula(commodity: str, variant: str) -> float | str | None:
        COMMODITY_TO_IMPORTED_COMMODITY_PRICES = {'1) Base metal (e.g., iron, copper, nickel, bauxite, etc.)': 'Copper', '2) Precious metal (e.g., gold, silver, platinum, etc.)': 'Gold', '3) Grain (e.g., wheat, corn, soybeans, etc.)': 'Wheat', '4) Other agricultural commodities (e.g., coffee, cocoa, tea, etc.)': 'Coffee'}
        if variant == 'Default':
            return as_measure((imported_commodity_prices[COMMODITY_TO_IMPORTED_COMMODITY_PRICES[commodity], '% change'] if xl_bool(xl_eq(input6_commodity_group_relevant[commodity], 'Yes')) else ''))
        return as_measure(in6_tailored_commodity_group_price_shock[commodity, 'Default'])

    in6_tailored_commodity_group_price_shock = CoordinateReader('in6_tailored_commodity_group_price_shock', data.IN6_TAILORED_COMMODITY_GROUP_PRICE_SHOCK.required, formula)
    return data.IN6_TAILORED_COMMODITY_GROUP_PRICE_SHOCK.collect((coord, in6_tailored_commodity_group_price_shock[coord]) for coord in data.IN6_TAILORED_COMMODITY_GROUP_PRICE_SHOCK.required)

