@publish(data.MACRO_DEBT_TOTAL_PUBLIC_DOMESTIC_DEBT_INTEREST_DUE.schema, cells=data.MACRO_DEBT_TOTAL_PUBLIC_DOMESTIC_DEBT_INTEREST_DUE.cells)
def macro_debt_total_public_domestic_debt_interest_due(*, input5_summary_interest_payment: data.Series[float | str | None], macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc: data.Series[float | str | None], input3_local_currency_domestic_debt: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Converts total public domestic debt interest due to US dollars on the Macro-Debt_Data year grid.

    Produces the Macro-Debt series for total public domestic debt interest due by dividing local-currency interest amounts by the national-currency-per-US-dollar exchange rate, using historical interest through 2023 and the Input 5 summary interest payment thereafter.

    Args:
        input5_summary_interest_payment: data.Series[float | str | None]: Summary interest payment series, keyed by projection year, supplying the interest payment amounts from 2024 onward.
        macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc: data.Series[float | str | None]: National currency per US dollar exchange rate series, keyed by projection year, used to convert local-currency interest amounts into US dollars.
        input3_local_currency_domestic_debt: data.Series[float | str | None]: Local-currency domestic debt series, keyed by projection year, whose 'Interest' coordinate supplies the interest due amounts for years through 2023.

    Returns:
        data.Series[float | str | None]: Total public domestic debt interest due expressed in US dollars, keyed by projection years from row 1.
    """
    def formula(time_period: int) -> float | str | None:
        if time_period <= 2023:
            return as_measure((xl_div(input3_local_currency_domestic_debt['Interest', time_period], macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc[time_period]) if xl_bool(xl_isnumber(lambda: xl_div(input3_local_currency_domestic_debt['Interest', time_period], macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc[time_period]))) else 0))
        return as_measure(xl_div(input5_summary_interest_payment[time_period], macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc[time_period]))

    return data.MACRO_DEBT_TOTAL_PUBLIC_DOMESTIC_DEBT_INTEREST_DUE.collect(evaluate(formula, data.MACRO_DEBT_TOTAL_PUBLIC_DOMESTIC_DEBT_INTEREST_DUE.required))

@publish(data.MACRO_DEBT_TOTAL_EXTERNAL_AMORTIZATION_DUE_INCLUDE.schema, cells=data.MACRO_DEBT_TOTAL_EXTERNAL_AMORTIZATION_DUE_INCLUDE.cells)
def macro_debt_total_external_amortization_due_include(*, macro_debt_mlt_private_ext_debt_amortization: data.Series[float | str | None], macro_debt_main_assumptions_us_dollars_by_year_6: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute total external amortization due include by summing MLT private external debt amortization with the main-assumptions US-dollar series.

    Derives the total external amortization due include path on the Macro-Debt_Data year grid.

    Args:
        macro_debt_mlt_private_ext_debt_amortization: Medium- and long-term private external debt amortization, as a US-dollar Macro-Debt_Data series keyed by projection years from row 1.
        macro_debt_main_assumptions_us_dollars_by_year_6: Main-assumptions US-dollar amounts by year 6, as a Macro-Debt_Data series keyed by projection years from row 1.

    Returns:
        A US-dollar Macro-Debt_Data series keyed by projection years from row 1, holding the total external amortization due include by year.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure(xl_add(macro_debt_main_assumptions_us_dollars_by_year_6[time_period], macro_debt_mlt_private_ext_debt_amortization[time_period]))

    return data.MACRO_DEBT_TOTAL_EXTERNAL_AMORTIZATION_DUE_INCLUDE.collect(evaluate(formula, data.MACRO_DEBT_TOTAL_EXTERNAL_AMORTIZATION_DUE_INCLUDE.required))

