@publish(data.MACRO_DEBT_TOTAL_MLT_PUBLIC_DOMESTIC_DEBT_AMORTIZATION_DEBT.schema, cells=data.MACRO_DEBT_TOTAL_MLT_PUBLIC_DOMESTIC_DEBT_AMORTIZATION_DEBT.cells)
def macro_debt_total_mlt_public_domestic_debt_amortization_debt(*, input5_summary_principal_payment: data.Series[float | str | None], macro_debt_public_domestic_st: data.Series[float | str | None], macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute total MLT public domestic debt amortization in U.S. dollars from principal payments, prior domestic debt stock, and the national-currency-per-USD exchange rate.

    Derive the per-year amortization debt series used by the LIC-DSF macro-debt engine as an inverted-tree helper.

    Args:
        input5_summary_principal_payment: Keyword-only series of Input 5 summary principal-payment amounts, typed as data.Series[float | str | None] and keyed by projection-year catalog coordinates.
        macro_debt_public_domestic_st: Keyword-only series of public domestic debt stock values, typed as data.Series[float | str | None] and keyed by projection-year catalog coordinates, with the prior period's value used by the calculation.
        macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc: Keyword-only series of exchange rates expressed as national currency per U.S. dollar, typed as data.Series[float | str | None] and keyed by projection-year catalog coordinates.

    Returns:
        A data.Series[float | str | None] in U.S. dollars over the Macro-Debt_Data projection-year coordinate grid, containing per-year total MLT public domestic debt amortization debt values or string/blank sentinels.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure(xl_div(xl_sub(input5_summary_principal_payment[time_period], macro_debt_public_domestic_st[time_period - 1]), macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc[time_period]))

    return data.MACRO_DEBT_TOTAL_MLT_PUBLIC_DOMESTIC_DEBT_AMORTIZATION_DEBT.collect(evaluate(formula, data.MACRO_DEBT_TOTAL_MLT_PUBLIC_DOMESTIC_DEBT_AMORTIZATION_DEBT.required))

