@publish(data.MACRO_DEBT_PUBLIC_SECTOR_INTEREST_EXPENDITURE.schema, cells=data.MACRO_DEBT_PUBLIC_SECTOR_INTEREST_EXPENDITURE.cells)
def macro_debt_public_sector_interest_expenditure(*, macro_debt_ppg_interest_due: data.Series[float | str | None], macro_debt_total_public_domestic_debt_interest_due: data.Series[float | str | None], macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute public sector interest expenditure from PPG and total public domestic debt interest due, converted by the national-currency-per-U.S.-dollar exchange rate.

    Materialize the Macro-Debt_Data public-sector interest expenditure series used by downstream fiscal and debt calculations.

    Args:
        macro_debt_ppg_interest_due: National Currency (Macro-Debt_Data) series, keyed by projection years from row 1, of public and publicly guaranteed interest due; values are float, str, or None.
        macro_debt_total_public_domestic_debt_interest_due: National Currency (Macro-Debt_Data) series, keyed by projection years from row 1, of total public domestic debt interest due; values are float, str, or None.
        macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc: National Currency (Macro-Debt_Data) series, keyed by projection years from row 1, of the exchange rate in national currency per U.S. dollar; values are float, str, or None.

    Returns:
        A data.Series[float | str | None] on Macro-Debt_Data, keyed by projection years from row 1, giving public sector interest expenditure in national currency.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure(xl_mul(xl_add(macro_debt_ppg_interest_due[time_period], macro_debt_total_public_domestic_debt_interest_due[time_period]), macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc[time_period]))

    return data.MACRO_DEBT_PUBLIC_SECTOR_INTEREST_EXPENDITURE.collect(evaluate(formula, data.MACRO_DEBT_PUBLIC_SECTOR_INTEREST_EXPENDITURE.required))

