@publish(data.MACRO_DEBT_EXCHANGE_RATE_DOLLAR_NC.schema, cells=data.MACRO_DEBT_EXCHANGE_RATE_DOLLAR_NC.cells)
def macro_debt_exchange_rate_dollar_nc(*, macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Invert a national-currency-per-U.S.-dollar exchange-rate series into a dollar-per-national-currency series.

    Provides the Macro-Debt exchange-rate series aligned to projection-year coordinates for downstream debt calculations.

    Args:
        macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc: National-currency-per-U.S.-dollar exchange-rate series keyed by projection years, with scalar numeric values or blank/text placeholders preserved.

    Returns:
        A data.Series[float | str | None] of reciprocal exchange-rate values keyed by the Macro-Debt projection-year coordinates.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure(xl_div(1, macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc[time_period]))

    return data.MACRO_DEBT_EXCHANGE_RATE_DOLLAR_NC.collect(evaluate(formula, data.MACRO_DEBT_EXCHANGE_RATE_DOLLAR_NC.required))

@publish(data.MACRO_DEBT_DEPRECIATION_OF_NC_DEPRECIATION.schema, cells=data.MACRO_DEBT_DEPRECIATION_OF_NC_DEPRECIATION.cells)
def macro_debt_depreciation_of_nc_depreciation(*, macro_debt_exchange_rate_dollar_nc: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute depreciation of the national currency from the macro-debt exchange-rate series.

    Derive the yearly NC depreciation measure used in Macro-Debt_Data projections.

    Args:
        macro_debt_exchange_rate_dollar_nc: Named-axis data.Series of the Macro-Debt_Data exchange rate (dollar per NC) keyed by projection years, whose entries may be float, str, or None.

    Returns:
        Named-axis data.Series[float | str | None] of NC depreciation (positive indicates depreciation) keyed by projection years, preserving blank or non-numeric sentinels.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure((xl_mul(xl_neg(100), xl_sub(xl_div(macro_debt_exchange_rate_dollar_nc[time_period], macro_debt_exchange_rate_dollar_nc[time_period - 1]), 1)) if xl_bool(xl_isnumber(lambda: xl_mul(xl_neg(100), xl_sub(xl_div(macro_debt_exchange_rate_dollar_nc[time_period], macro_debt_exchange_rate_dollar_nc[time_period - 1]), 1)))) else '...'))

    return data.MACRO_DEBT_DEPRECIATION_OF_NC_DEPRECIATION.collect(evaluate(formula, data.MACRO_DEBT_DEPRECIATION_OF_NC_DEPRECIATION.required))

@publish(key=(), domain=None, cells=data.START_DEBT_SUSTAINABILITY_ANALYSIS_CELLS)
def start_debt_sustainability_analysis(*, start_working_language: Literal["English", "Espa\u00f1ol", "Fran\u00e7ais", "Portugues"], lookup_language_native_name: data.Series[str | None], lookup_language_english_name: data.Series[str | None]) -> str | int | float | bool:
    """Return the English-language name for a selected working language.

    Resolve the single-cell language lookup used by the debt sustainability analysis start anchor.

    Args:
        start_working_language: Selected working language, restricted to English, Español, Français, or Portugues.
        lookup_language_native_name: Named-axis series over catalog language coordinates holding native language names, with nulls allowed.
        lookup_language_english_name: Named-axis series over catalog language coordinates holding English language names, with nulls allowed.

    Returns:
        A scalar string giving the matched English language name, or the spreadsheet error code when the lookup fails; the str | int | float | bool annotation reflects the lookup and error-result surface.
    """
    data.LOOKUP_LANGUAGE_NATIVE_NAME.schema.validate(lookup_language_native_name)
    data.LOOKUP_LANGUAGE_ENGLISH_NAME.schema.validate(lookup_language_english_name)
    _start_debt_sustainability_analysis_table_0 = lazy_table(((view(lookup_language_native_name, rows=data.LANGUAGE_AXIS.keys), view(lookup_language_english_name, rows=data.LANGUAGE_AXIS.keys)),))
    try:
        return as_measure(xl_vlookup(start_working_language, _start_debt_sustainability_analysis_table_0, 2, False), 'str')
    except XlError as error:
        return error.code

@publish(key=(), domain=None, cells=data.START_DEBT_SUSTAINABILITY_ANALYSIS_M_CELLS)
def start_debt_sustainability_analysis_m(*, start_debt_sustainability_analysis: str | int | float | bool) -> int | str:
    """Compute the START debt sustainability analysis language anchor as a numeric code.

    Resolve the single-cell Debt Sustainability Analysis (START) selection to the language index used by the authored workbook identities.

    Args:
        start_debt_sustainability_analysis: Scalar language selector whose English, French, and Portuguese values map to 0, 1, and 2; any other value maps to 3.

    Returns:
        Integer language code (0 for English, 1 for French, 2 for Portuguese, 3 otherwise), or the XlError code string when evaluation fails.
    """
    try:
        return as_measure((0 if xl_bool(xl_eq(start_debt_sustainability_analysis, 'English')) else (1 if xl_bool(xl_eq(start_debt_sustainability_analysis, 'French')) else (2 if xl_bool(xl_eq(start_debt_sustainability_analysis, 'Portuguese')) else 3))), 'int')
    except XlError as error:
        return error.code

