@publish(data.C4_MARKET_PATH_NOMINAL_GDP_STRESS.schema, cells=data.C4_MARKET_PATH_NOMINAL_GDP_STRESS.cells)
def c4_market_path_nominal_gdp_stress(*, c4_market_path_nominal_gdp: float | str, c4_mkt_fin_nominal_gdp: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute the C4 market-path nominal GDP stress series under the C4_Market scenario.

    Combine the 2024 scalar anchor with the market-financing nominal GDP projection series to produce the apply_market_financing_shock C4 stress path.

    Args:
        c4_market_path_nominal_gdp: Scalar C4 market-path nominal GDP value (float or string label) anchored to time period 2024.
        c4_mkt_fin_nominal_gdp: Named-axis data.Series of C4 market-financing nominal GDP values (float, string, or None) over catalog time periods, used for all years other than 2024.

    Returns:
        Named-axis data.Series[float | str | None] of the C4_Market nominal GDP stress path over catalog time periods, with the 2024 entry taken from the scalar anchor and later entries from the market-financing nominal GDP series.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        if time_period == 2024:
            return as_measure(c4_market_path_nominal_gdp)
        return as_measure(c4_mkt_fin_nominal_gdp[time_period])

    return data.C4_MARKET_PATH_NOMINAL_GDP_STRESS.collect(evaluate(formula, data.C4_MARKET_PATH_NOMINAL_GDP_STRESS.required))

