def c4_market_instruments(*, input4_grace_period: data.Input4GracePeriod, input4_loan_maturity: data.Input4LoanMaturity) -> data.Series[int | str | None]:
    """Build C4 commercial-loan instrument terms from grace-period and loan-maturity inputs.

    Populate C4 market instruments by using grace-period values for the 2023 period and loan-maturity values for all other periods.

    Args:
        input4_grace_period: Keyword-only grace-period series for C4 commercial-loan instruments, providing the 2023 term values.
        input4_loan_maturity: Keyword-only loan-maturity series for C4 commercial-loan instruments, providing term values for periods other than 2023.

    Returns:
        A data.Series[int | str | None] over C4 instrument and time-period coordinates, containing grace-period values for 2023 and loan-maturity values otherwise.
    """
    data.INPUT4_GRACE_PERIOD.schema.validate(input4_grace_period)
    data.INPUT4_LOAN_MATURITY.schema.validate(input4_loan_maturity)
    def formula(instrument: str, time_period: int) -> int | str | None:
        if time_period == 2023:
            return as_measure(input4_grace_period[instrument], 'int')
        return as_measure(input4_loan_maturity[instrument], 'int')

    return data.C4_MARKET_INSTRUMENTS.collect(evaluate(formula, data.C4_MARKET_INSTRUMENTS.required))

