@publish(data.INPUT6_STANDARD_PARAMS.schema, cells=data.INPUT6_STANDARD_PARAMS.cells)
def input6_standard_params(*, input6_standard_b1_real_gdp_growth_size_of_real_gdp_growth_shock_of_standard_deviations: float | str, input6_standard_b2_primary_balance_size_of_pb_gdp_shock_of_standard_deviations: float | str, input6_standard_b3_exports_size_of_exports_growth_shock_of_standard_deviations: float | str, input6_standard_b4_other_non_debt_creating_flows_other_flows_current_transfers_shock_of_standard_deviations: float | str, input6_standard_b4_other_non_debt_creating_flows_other_flows_fdi_shock_of_standard_deviations: float | str) -> data.Series[int | str | None]:
    """Collect Input 6 standardized stress-test shock parameters into a catalog-indexed series.

    Resolve the B1–B4 standardized shock sizes from Input 6 into typed series values keyed by lic_dsf field names.

    Args:
        input6_standard_b1_real_gdp_growth_size_of_real_gdp_growth_shock_of_standard_deviations: Standardized shock size, in standard deviations, applied to real GDP growth for the B1 standard stress scenario; accepts a numeric value or workbook string reference.
        input6_standard_b2_primary_balance_size_of_pb_gdp_shock_of_standard_deviations: Standardized shock size, in standard deviations, applied to the primary balance as a share of GDP for the B2 standard stress scenario; accepts a numeric value or workbook string reference.
        input6_standard_b3_exports_size_of_exports_growth_shock_of_standard_deviations: Standardized shock size, in standard deviations, applied to exports growth for the B3 standard stress scenario; accepts a numeric value or workbook string reference.
        input6_standard_b4_other_non_debt_creating_flows_other_flows_current_transfers_shock_of_standard_deviations: Standardized shock size, in standard deviations, applied to other non-debt-creating flows through current transfers for the B4 standard stress scenario; accepts a numeric value or workbook string reference.
        input6_standard_b4_other_non_debt_creating_flows_other_flows_fdi_shock_of_standard_deviations: Standardized shock size, in standard deviations, applied to other non-debt-creating flows through FDI for the B4 standard stress scenario; accepts a numeric value or workbook string reference.

    Returns:
        A data.Series[int | str | None] over Input 6 standard-parameter coordinates containing the resolved standardized shock values for the input6.standard_test fields.
    """
    def formula(parameter: str, variant: str) -> int | str | None:
        if parameter == 'b1_real_gdp_growth':
            return as_measure(input6_standard_b1_real_gdp_growth_size_of_real_gdp_growth_shock_of_standard_deviations, 'int')
        elif parameter == 'b2_primary_balance':
            return as_measure(input6_standard_b2_primary_balance_size_of_pb_gdp_shock_of_standard_deviations, 'int')
        elif parameter == 'b3_exports':
            return as_measure(input6_standard_b3_exports_size_of_exports_growth_shock_of_standard_deviations, 'int')
        elif parameter == 'b4_other_flows':
            return as_measure(input6_standard_b4_other_non_debt_creating_flows_other_flows_current_transfers_shock_of_standard_deviations, 'int')
        return as_measure(input6_standard_b4_other_non_debt_creating_flows_other_flows_fdi_shock_of_standard_deviations, 'int')

    return data.INPUT6_STANDARD_PARAMS.collect(evaluate(formula, data.INPUT6_STANDARD_PARAMS.required))

@publish(data.INPUT6_TAILORED_PARAMS_3.schema, cells=data.INPUT6_TAILORED_PARAMS_3.cells)
def input6_tailored_params_3(*, in6_tailored_commodity_interaction_defaults: data.Series[float | str | None], in6_tailored_natdisaster_interaction_defaults: data.Series[float | str | None], in6_tailored_mkt_fin_fx_passthrough_default: float | str) -> data.Series[float | str | None]:
    """Compute the Input 6 tailored-test parameter series.

    Resolve leftover Input 6 tailored-test fields to their commodity-interaction, natural-disaster-interaction, or FX-passthrough sources by lic_dsf parameter name.

    Args:
        in6_tailored_commodity_interaction_defaults: Named-axis series of default values for the Input 6 tailored commodity-interaction fields, keyed by lic_dsf field name and allowing float, str, or None cells.
        in6_tailored_natdisaster_interaction_defaults: Named-axis series of default values for the Input 6 tailored natural-disaster-interaction fields, keyed by lic_dsf field name and allowing float, str, or None cells.
        in6_tailored_mkt_fin_fx_passthrough_default: Scalar default for the market-financing FX passthrough parameter.

    Returns:
        A named-axis series of resolved Input 6 tailored-test parameter values with a float, str, or None element type.
    """
    def formula(parameter: str) -> float | str | None:
        PARAMETER_TO_IN6_TAILORED_NATDISASTER_INTERACTION_DEFAULTS_INDICATOR = {'disaster_shock_pct_gdp': 'Size of associated real GDP growth shock', 'disaster_export_growth_shock': 'Size of associated exports growth shock'}
        PARAMETER_TO_IN6_TAILORED_COMMODITY_INTERACTION_DEFAULTS_INDICATOR = {'commodity_export_gdp_gap_years': 'Size of associated real GDP growth shock', 'disaster_revenue_drop': 'Revenue (fiscal-revenue to GDP) drop'}
        if parameter == 'fx_depreciation':
            return as_measure(in6_tailored_mkt_fin_fx_passthrough_default)
        elif parameter in ('disaster_shock_pct_gdp', 'disaster_export_growth_shock'):
            return as_measure(in6_tailored_natdisaster_interaction_defaults[PARAMETER_TO_IN6_TAILORED_NATDISASTER_INTERACTION_DEFAULTS_INDICATOR[parameter]])
        return as_measure(in6_tailored_commodity_interaction_defaults[PARAMETER_TO_IN6_TAILORED_COMMODITY_INTERACTION_DEFAULTS_INDICATOR[parameter]])

    return data.INPUT6_TAILORED_PARAMS_3.collect(evaluate(formula, data.INPUT6_TAILORED_PARAMS_3.required))

@publish(data.LEFTOVER_US_GDP_DEFLATOR.schema, cells=data.LEFTOVER_US_GDP_DEFLATOR.cells)
def leftover_us_gdp_deflator(*, input6_standard_params_2: data.Series[float | str | None], input6_tailored_params_3: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute the leftover US GDP deflator series from standardized and tailored scenario stress parameters.

    Select scenario-specific deflator leftover values for DSA scenario sheets.

    Args:
        input6_standard_params_2: A data.Series[float | str | None] keyed by SCENARIO containing standardized stress parameters for exports, depreciation, and combination scenarios.
        input6_tailored_params_3: A data.Series[float | str | None] keyed by SCENARIO containing tailored stress parameters, including disaster revenue drop.

    Returns:
        A data.Series[float | str | None] keyed by SCENARIO holding the leftover US GDP deflator values on DSA scenario sheets.
    """
    def formula(scenario: str) -> float | str | None:
        if scenario == 'B3':
            return as_measure(input6_standard_params_2['b3_exports', 'default'])
        elif scenario == 'B5':
            return as_measure(input6_standard_params_2['b5_depreciation_1', 'default'])
        elif scenario == 'C3':
            return as_measure(input6_tailored_params_3['disaster_revenue_drop'])
        return as_measure(input6_standard_params_2['b6_combination', 'default'])

    return data.LEFTOVER_US_GDP_DEFLATOR.collect(evaluate(formula, data.LEFTOVER_US_GDP_DEFLATOR.required))

@publish(data.CUSTOM_EXT_AVERAGE_INTEREST_RATE_NEW_DEBT_BY_ROW.schema, cells=data.CUSTOM_EXT_AVERAGE_INTEREST_RATE_NEW_DEBT_BY_ROW.cells)
def custom_ext_average_interest_rate_new_debt_by_row(*, in7_resfin_ext_mlt_effective: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Derive the average interest rate on new external debt for each row of the custom series.

    Maps effective multilateral financing terms onto the authored row identities of the custom external-debt interest-rate series.

    Args:
        in7_resfin_ext_mlt_effective: Typed data series of effective financing terms for new external debt, supplying the nominal USD borrowing rate, the USD discount rate, the grace period, and the maturity used to resolve each row label; scalar or string entries are passed through as measures.

    Returns:
        A coordinate-keyed data series of the average interest rate on new debt, one entry per row label of the custom identity, with scalar or string values preserved where the underlying term is not numeric.
    """
    def formula(indicator: str) -> float | str | None:
        if indicator == 'Average interest rate on new debt':
            return as_measure(in7_resfin_ext_mlt_effective['Avg. nominal interest rate on new borrowing in USD'])
        elif indicator == 'USD Discount rate':
            return as_measure(in7_resfin_ext_mlt_effective[indicator])
        elif indicator == 'Average grace period on new debt':
            return as_measure(in7_resfin_ext_mlt_effective['Avg. grace period'])
        return as_measure(in7_resfin_ext_mlt_effective['Avg. maturity (incl. grace period)'])

    return data.CUSTOM_EXT_AVERAGE_INTEREST_RATE_NEW_DEBT_BY_ROW.collect(evaluate(formula, data.CUSTOM_EXT_AVERAGE_INTEREST_RATE_NEW_DEBT_BY_ROW.required))

@publish(data.IN7_RESFIN_AVG_NOMINAL_INTEREST_RATE_NEW_BORROWING_USD_BY_ROW.schema, cells=data.IN7_RESFIN_AVG_NOMINAL_INTEREST_RATE_NEW_BORROWING_USD_BY_ROW.cells)
def in7_resfin_avg_nominal_interest_rate_new_borrowing_usd_by_row(*, in7_resfin_ext_mlt_default: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Evaluate the row-wise average nominal interest rate on new external borrowing, in USD terms.

    Materializes the by-row interest-rate series that residual-financing and debt-service aggregates consume during Input 7 calculations.

    Args:
        in7_resfin_ext_mlt_default: Keyword-only ``data.Series[float | str | None]`` keyed by catalog coordinate whose entry at each row supplies the authored formula input for the average nominal interest rate on new external borrowing; graph-coverage chrome rather than a public economist entry point.

    Returns:
        ``data.Series[float | str | None]`` of the average nominal interest rate on new external borrowing, aligned to the same row coordinates as the input series.
    """
    def formula(indicator: str) -> float | str | None:
        return as_measure(in7_resfin_ext_mlt_default[indicator])

    return data.IN7_RESFIN_AVG_NOMINAL_INTEREST_RATE_NEW_BORROWING_USD_BY_ROW.collect(evaluate(formula, data.IN7_RESFIN_AVG_NOMINAL_INTEREST_RATE_NEW_BORROWING_USD_BY_ROW.required))

@publish(data.LEFTOVER_REAL_INTEREST_RATE.schema, cells=data.LEFTOVER_REAL_INTEREST_RATE.cells)
def leftover_real_interest_rate(*, input6_standard_params_2: data.Series[float | str | None], input6_tailored_params_3: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Resolve the scenario-keyed leftover real interest rate from the Input 6 standard and tailored stress parameters.

    Supply the residual real interest rate consumed by LIC-DSF stress-scenario projections as a SCENARIO-indexed series.

    Args:
        input6_standard_params_2: Keyword-only named-axis series over catalog coordinates holding the standardized stress-test assumptions; the parameter is a single typed series whose scalar entries are read by coordinate lookup (standard-ladder branch values) rather than a bare Python sequence.
        input6_tailored_params_3: Keyword-only named-axis series over catalog coordinates holding the tailored (customized-scenario) stress assumptions; treated as one typed series, it provides the tailored branch values and the fallback entry used for scenarios outside the standard ladder.

    Returns:
        A data.Series[float | str | None] keyed by SCENARIO giving the leftover real interest rate for each scenario coordinate, with None where the workbook leaves the corresponding entry blank.
    """
    def formula(scenario: str) -> float | str | None:
        if scenario == 'B1':
            return as_measure(input6_standard_params_2['b1_real_gdp_growth', 'default'])
        elif scenario == 'B5':
            return as_measure(input6_standard_params_2['b5_depreciation_1', 'default'])
        elif scenario == 'C2':
            return as_measure(input6_tailored_params_3['disaster_export_growth_shock'])
        return as_measure(input6_tailored_params_3['disaster_revenue_drop'])

