def ci_summary_medium(*, imported_composite_indicator: data.Series[str | int | float | bool | None]) -> data.Series[str | int | float | bool | None]:
    """Computes the CI summary medium series from the imported composite indicator.

    Derives the CI summary medium by selecting the appropriate vintage year from the imported composite indicator based on the indicator label.

    Args:
        imported_composite_indicator: The imported composite indicator series (graph-coverage chrome, not a public series) indexed by year, providing values for 2024 and 2025 that are selected based on the indicator label.

    Returns:
        A data.Series[str | int | float | bool | None] containing the CI summary medium values, where each value is the 2024 or 2025 entry from the imported composite indicator as determined by the indicator label.
    """
    def formula(indicator: str) -> str | int | float | bool | None:
        if indicator == 'Classification based on the previous vintage':
            return as_measure(imported_composite_indicator[2024], 'str')
        return as_measure(imported_composite_indicator[2025], 'str')

    return data.CI_SUMMARY_MEDIUM.collect(evaluate(formula, data.CI_SUMMARY_MEDIUM.required))

