@publish(data.REALISM2_BASELINE_GROWTH.schema, cells=data.REALISM2_BASELINE_GROWTH.cells)
def realism2_baseline_growth(*, realism2_real_gdp_growth: data.Series[float | str | None]) -> data.Realism2BaselineGrowth:
    """Return the baseline real GDP growth path for the Realism 2 fiscal-multiplier chart.

    Collects the Realism 2 baseline real GDP growth series from the authored coordinate identities.

    Args:
        realism2_real_gdp_growth: Real GDP growth series over catalog time-period coordinates, typed data.Series[float | str | None].

    Returns:
        data.Realism2BaselineGrowth dataclass containing the baseline real GDP growth path.
    """
