@publish(data.REALISM4_FISCAL_ADJUSTMENT_SAMPLE_SHARE.schema, cells=data.REALISM4_FISCAL_ADJUSTMENT_SAMPLE_SHARE.cells)
def realism4_fiscal_adjustment_sample_share(*, realism4_fiscal_adjustment_bin_frequencies: data.Series[float | str | None]) -> data.Realism4FiscalAdjustmentSampleShare:
    """Compute each fiscal-adjustment bin's sample share as a percentage of the LIC sample.

    Normalize authored fiscal-adjustment bin frequencies into sample shares for the Realism 4 tool.

    Args:
        realism4_fiscal_adjustment_bin_frequencies: Keyword-only `data.Series[float | str | None]` over fiscal-adjustment bin variants. A named-axis series whose values are the percent of the LIC sample in each 3-year fiscal-adjustment bin; entries may be numeric, string, or missing (`None`).

    Returns:
        A `data.Realism4FiscalAdjustmentSampleShare` series giving the percentage sample share for each fiscal-adjustment bin, computed as the bin frequency divided by the total across bins and multiplied by 100.
    """
    data.REALISM4_FISCAL_ADJUSTMENT_BIN_FREQUENCIES.schema.validate(realism4_fiscal_adjustment_bin_frequencies)
    _realism4_fiscal_adjustment_sample_share_table_0 = view(realism4_fiscal_adjustment_bin_frequencies, rows=data.VARIANT_AXIS_4.keys)
    def formula(variant: int) -> float | str | None:
        return as_measure(xl_mul(xl_div(realism4_fiscal_adjustment_bin_frequencies[variant], xl_sum(_realism4_fiscal_adjustment_sample_share_table_0)), 100))

    return data.REALISM4_FISCAL_ADJUSTMENT_SAMPLE_SHARE.collect(evaluate(formula, data.REALISM4_FISCAL_ADJUSTMENT_SAMPLE_SHARE.required))

@publish(data.REALISM4_FISCAL_ADJUSTMENT_CUMULATIVE_SHARE.schema, cells=data.REALISM4_FISCAL_ADJUSTMENT_CUMULATIVE_SHARE.cells)
def realism4_fiscal_adjustment_cumulative_share(*, realism4_fiscal_adjustment_sample_share: data.Realism4FiscalAdjustmentSampleShare) -> data.Realism4FiscalAdjustmentCumulativeShare:
    """Compute the cumulative share of the LIC sample across fiscal-adjustment bins.

    Derive the cumulative fiscal-adjustment distribution by accumulating the sample-share series over the authored bin coordinates.

    Args:
        realism4_fiscal_adjustment_sample_share: Sample-share series over catalog fiscal-adjustment bins, providing the per-bin percent of the LIC sample to accumulate.

    Returns:
        A data.Realism4FiscalAdjustmentCumulativeShare series giving the cumulative percent of the LIC sample up to each fiscal-adjustment bin.
    """
    def formula(variant: int) -> float | str | None:
        if variant == 2:
            return as_measure(xl_add(realism4_fiscal_adjustment_sample_share[variant - 1], realism4_fiscal_adjustment_sample_share[variant]))
        return as_measure(xl_add(realism4_fiscal_adjustment_cumulative_share[variant - 1], realism4_fiscal_adjustment_sample_share[variant]))

    realism4_fiscal_adjustment_cumulative_share = CoordinateReader('realism4_fiscal_adjustment_cumulative_share', data.REALISM4_FISCAL_ADJUSTMENT_CUMULATIVE_SHARE.required, formula)
    return data.REALISM4_FISCAL_ADJUSTMENT_CUMULATIVE_SHARE.collect((coord, realism4_fiscal_adjustment_cumulative_share[coord]) for coord in data.REALISM4_FISCAL_ADJUSTMENT_CUMULATIVE_SHARE.required)

@publish(data.PROBABILITY_PV_DEBT_TO_GDP.schema, cells=data.PROBABILITY_PV_DEBT_TO_GDP.cells)
def probability_pv_debt_to_gdp(*, probability_borderline_bandwidth: float | str, chart_output_pv_debt_gdp_ratio: data.ChartOutputPvDebtGdpRatio) -> data.ProbabilityPvDebtToGdp:
    """Compute probability PV debt-to-GDP threshold bands.

    Derive lower and upper probability bands from the chart-output PV debt-to-GDP series and a borderline bandwidth scalar or string.

    Args:
        probability_borderline_bandwidth: Scalar or string borderline bandwidth controlling the width of the lower and upper bands around the threshold value.
        chart_output_pv_debt_gdp_ratio: Typed data.ChartOutputPvDebtGdpRatio series providing PV of PPG external debt-to-GDP baseline, historical, MX shock, threshold, and band values over catalog coordinates.

    Returns:
        Typed data.ProbabilityPvDebtToGdp series containing PV of PPG external debt-to-GDP baseline, historical, MX shock, threshold, and lower/upper probability bands over catalog coordinates.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        if scenario == 'Lower Band':
            return as_measure(xl_mul(probability_pv_debt_to_gdp['Threshold', time_period], xl_sub(1, xl_div(probability_borderline_bandwidth, 2))))
        elif scenario == 'Upper Band':
            return as_measure(xl_mul(probability_pv_debt_to_gdp['Threshold', time_period], xl_add(1, xl_div(probability_borderline_bandwidth, 2))))
        return as_measure(chart_output_pv_debt_gdp_ratio[scenario, time_period])

    probability_pv_debt_to_gdp = CoordinateReader('probability_pv_debt_to_gdp', data.PROBABILITY_PV_DEBT_TO_GDP.required, formula)
    return data.PROBABILITY_PV_DEBT_TO_GDP.collect((coord, probability_pv_debt_to_gdp[coord]) for coord in data.PROBABILITY_PV_DEBT_TO_GDP.required)

@publish(data.PROBABILITY_PV_DEBT_TO_EXPORTS.schema, cells=data.PROBABILITY_PV_DEBT_TO_EXPORTS.cells)
def probability_pv_debt_to_exports(*, probability_borderline_bandwidth: float | str, chart_output_pv_debt_to_exports: data.ChartOutputPvDebtToExports) -> data.ProbabilityPvDebtToExports:
    """Compute probability-approach PV of PPG external debt-to-exports series.

    Build baseline, historical, MX shock, threshold, and band paths for the PV of PPG external debt-to-exports indicator.

    Args:
        probability_borderline_bandwidth: Borderline bandwidth scalar (float or string) applied symmetrically to derive lower and upper bands around the threshold.
        chart_output_pv_debt_to_exports: Typed chart-output series holding PV of PPG external debt-to-exports paths by scenario and projection period, supplying all non-band scenarios.

    Returns:
        Typed data.ProbabilityPvDebtToExports series over scenario and time-period coordinates containing baseline, historical, MX shock, threshold, and derived lower/upper band values.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        if scenario == 'Lower Band':
            return as_measure(xl_mul(probability_pv_debt_to_exports['Threshold', time_period], xl_sub(1, xl_div(probability_borderline_bandwidth, 2))))
        elif scenario == 'Upper Band':
            return as_measure(xl_mul(probability_pv_debt_to_exports['Threshold', time_period], xl_add(1, xl_div(probability_borderline_bandwidth, 2))))
        return as_measure(chart_output_pv_debt_to_exports[scenario, time_period])

    probability_pv_debt_to_exports = CoordinateReader('probability_pv_debt_to_exports', data.PROBABILITY_PV_DEBT_TO_EXPORTS.required, formula)
    return data.PROBABILITY_PV_DEBT_TO_EXPORTS.collect((coord, probability_pv_debt_to_exports[coord]) for coord in data.PROBABILITY_PV_DEBT_TO_EXPORTS.required)

@publish(data.PROBABILITY_DEBT_SERVICE_TO_EXPORTS.schema, cells=data.PROBABILITY_DEBT_SERVICE_TO_EXPORTS.cells)
def probability_debt_service_to_exports(*, probability_borderline_bandwidth: float | str, chart_output_debt_service_to_exports: data.ChartOutputDebtServiceToExports) -> data.ProbabilityDebtServiceToExports:
    """Compute the probability-approach series for PPG external debt service to exports, appending threshold-relative lower and upper bands.

    Build the debt-service-to-exports indicator path used by the probability approach from the Chart Data output series and a borderline bandwidth.

    Args:
        probability_borderline_bandwidth: Scalar bandwidth fraction applied around the threshold value; a value of 0 collapses both bands onto the threshold, while nonzero values spread the lower band down and the upper band up by half the fraction in each direction.
        chart_output_debt_service_to_exports: Typed Chart Data series of PPG external debt service to exports, supplying the baseline, historical, MX shock, and threshold paths over the catalog year grid that are copied through unchanged for non-band scenarios.

    Returns:
        Typed `data.ProbabilityDebtServiceToExports` series holding the PPG external debt service-to-exports probability indicator across every required scenario — baseline, historical, MX shock, threshold, and the derived lower and upper bands — over the catalog year grid; band entries are computed as the threshold scaled by one minus or plus half the bandwidth, and remaining scenarios pass through the Chart Data series.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        if scenario == 'Lower Band':
            return as_measure(xl_mul(probability_debt_service_to_exports['Threshold', time_period], xl_sub(1, xl_div(probability_borderline_bandwidth, 2))))
        elif scenario == 'Upper Band':
            return as_measure(xl_mul(probability_debt_service_to_exports['Threshold', time_period], xl_add(1, xl_div(probability_borderline_bandwidth, 2))))
        return as_measure(chart_output_debt_service_to_exports[scenario, time_period])

    probability_debt_service_to_exports = CoordinateReader('probability_debt_service_to_exports', data.PROBABILITY_DEBT_SERVICE_TO_EXPORTS.required, formula)
    return data.PROBABILITY_DEBT_SERVICE_TO_EXPORTS.collect((coord, probability_debt_service_to_exports[coord]) for coord in data.PROBABILITY_DEBT_SERVICE_TO_EXPORTS.required)

