@publish(data.PROBABILITY_PV_DEBT_TO_GDP_DISTRESS.schema, cells=data.PROBABILITY_PV_DEBT_TO_GDP_DISTRESS.cells)
def probability_pv_debt_to_gdp_distress(*, probability_debt_carrying_capacity_paths: data.Series[float | str | None], probability_regression_diagonal: data.Series[float | str | None], probability_distress_thresholds: data.Series[float | str | None], probability_regression_coefficients: data.Series[float | str | None], probability_pv_debt_to_gdp: data.ProbabilityPvDebtToGdp) -> data.ProbabilityPvDebtToGdpDistress:
    """Compute probability of external-debt distress for PV debt-to-GDP under baseline, historical, MX, and threshold scenarios.

    Evaluate distress probabilities using a logistic regression model and compare against distress thresholds.

    Args:
        probability_debt_carrying_capacity_paths: data.Series[float | str | None] of debt-carrying capacity paths (e.g., CPIA, Real GDP Growth, Reserves, Remittances, World Growth) keyed by scenario and time period.
        probability_regression_diagonal: data.Series[float | str | None] of the regression diagonal coefficient for the PV debt-to-GDP term, keyed by 'npvgdp'.
        probability_distress_thresholds: data.Series[float | str | None] of distress thresholds for PV debt-to-GDP, keyed by 'npvgdp'.
        probability_regression_coefficients: data.Series[float | str | None] of logistic regression coefficients for each predictor (e.g., CPIA, Growth, Reserves, Reserves^2, Remittances, World Growth, Constant), keyed by 'npvgdp'.
        probability_pv_debt_to_gdp: data.ProbabilityPvDebtToGdp series of PV debt-to-GDP ratios for each scenario and time period.

    Returns:
        data.ProbabilityPvDebtToGdpDistress series of computed distress probabilities (or threshold values when scenario is 'Threshold') for PV debt-to-GDP across scenarios and time periods.
    """
    data.PROBABILITY_REGRESSION_DIAGONAL.schema.validate(probability_regression_diagonal)
    data.PROBABILITY_DISTRESS_THRESHOLDS.schema.validate(probability_distress_thresholds)
    data.PROBABILITY_REGRESSION_COEFFICIENTS.schema.validate(probability_regression_coefficients)
    def formula(scenario: str, time_period: int) -> float | str | None:
        if scenario == 'Threshold':
            return as_measure(xl_mul(probability_distress_thresholds['npvgdp'], 100))
        return as_measure(xl_mul(xl_normdist(xl_add(xl_add(xl_add(xl_add(xl_add(xl_add(xl_add(xl_div(xl_mul(probability_regression_diagonal['npvgdp'], probability_pv_debt_to_gdp[scenario, time_period]), 100), xl_mul(probability_regression_coefficients['CPIA', 'npvgdp'], probability_debt_carrying_capacity_paths['CPIA', time_period])), xl_div(xl_mul(probability_regression_coefficients['Growth', 'npvgdp'], probability_debt_carrying_capacity_paths['Real GDP Growth', time_period]), 100)), xl_div(xl_mul(probability_regression_coefficients['Reserves', 'npvgdp'], probability_debt_carrying_capacity_paths['Reserves', time_period]), 100)), xl_mul(probability_regression_coefficients['Reserves^2', 'npvgdp'], xl_pow(xl_div(probability_debt_carrying_capacity_paths['Reserves', time_period], 100), 2))), xl_div(xl_mul(probability_regression_coefficients['Remittances', 'npvgdp'], probability_debt_carrying_capacity_paths['Remittances', time_period]), 100)), xl_div(xl_mul(probability_regression_coefficients['World Growth', 'npvgdp'], probability_debt_carrying_capacity_paths['World Growth', time_period]), 100)), probability_regression_coefficients['Constant', 'npvgdp']), 0, 1, 1), 100))

    return data.PROBABILITY_PV_DEBT_TO_GDP_DISTRESS.collect(evaluate(formula, data.PROBABILITY_PV_DEBT_TO_GDP_DISTRESS.required))

@publish(data.PROBABILITY_PV_DEBT_TO_EXPORTS_DISTRESS.schema, cells=data.PROBABILITY_PV_DEBT_TO_EXPORTS_DISTRESS.cells)
def probability_pv_debt_to_exports_distress(*, probability_debt_carrying_capacity_paths: data.Series[float | str | None], probability_regression_diagonal: data.Series[float | str | None], probability_distress_thresholds: data.Series[float | str | None], probability_regression_coefficients: data.Series[float | str | None], probability_pv_debt_to_exports: data.ProbabilityPvDebtToExports) -> data.ProbabilityPvDebtToExportsDistress:
    """Compute external-debt distress probabilities for PV debt-to-exports.

    Evaluate the probability-approach distress equation for PV debt-to-exports across baseline, historical, MX, and threshold scenarios.

    Args:
        probability_debt_carrying_capacity_paths: Typed `data.Series[float | str | None]` over catalog coordinates holding debt-carrying capacity paths for CPIA, real GDP growth, reserves, remittances, and world growth by time period.
        probability_regression_diagonal: Typed `data.Series[float | str | None]` over catalog coordinates containing the regression diagonal terms for the PV debt-to-exports indicator.
        probability_distress_thresholds: Typed `data.Series[float | str | None]` over catalog coordinates providing distress threshold values for PV debt-to-exports.
        probability_regression_coefficients: Typed `data.Series[float | str | None]` over catalog coordinates holding regression coefficients for CPIA, growth, reserves, reserves squared, remittances, world growth, and constant terms by indicator.
        probability_pv_debt_to_exports: Typed `data.ProbabilityPvDebtToExports` collection of PV debt-to-exports projections indexed by scenario and time period.

    Returns:
        A typed `data.ProbabilityPvDebtToExportsDistress` series giving the probability of external-debt distress for PV debt/exports under baseline, historical, MX, and threshold scenarios.
    """
    data.PROBABILITY_REGRESSION_DIAGONAL.schema.validate(probability_regression_diagonal)
    data.PROBABILITY_DISTRESS_THRESHOLDS.schema.validate(probability_distress_thresholds)
    data.PROBABILITY_REGRESSION_COEFFICIENTS.schema.validate(probability_regression_coefficients)
    def formula(scenario: str, time_period: int) -> float | str | None:
        if scenario == 'Threshold':
            return as_measure(xl_mul(probability_distress_thresholds['npvexp'], 100))
        return as_measure(xl_mul(xl_normdist(xl_add(xl_add(xl_add(xl_add(xl_add(xl_add(xl_add(xl_div(xl_mul(probability_regression_diagonal['npvexp'], probability_pv_debt_to_exports[scenario, time_period]), 100), xl_mul(probability_regression_coefficients['CPIA', 'npvexp'], probability_debt_carrying_capacity_paths['CPIA', time_period])), xl_div(xl_mul(probability_regression_coefficients['Growth', 'npvexp'], probability_debt_carrying_capacity_paths['Real GDP Growth', time_period]), 100)), xl_div(xl_mul(probability_regression_coefficients['Reserves', 'npvexp'], probability_debt_carrying_capacity_paths['Reserves', time_period]), 100)), xl_mul(probability_regression_coefficients['Reserves^2', 'npvexp'], xl_pow(xl_div(probability_debt_carrying_capacity_paths['Reserves', time_period], 100), 2))), xl_div(xl_mul(probability_regression_coefficients['Remittances', 'npvexp'], probability_debt_carrying_capacity_paths['Remittances', time_period]), 100)), xl_div(xl_mul(probability_regression_coefficients['World Growth', 'npvexp'], probability_debt_carrying_capacity_paths['World Growth', time_period]), 100)), probability_regression_coefficients['Constant', 'npvexp']), 0, 1, 1), 100))

    return data.PROBABILITY_PV_DEBT_TO_EXPORTS_DISTRESS.collect(evaluate(formula, data.PROBABILITY_PV_DEBT_TO_EXPORTS_DISTRESS.required))

@publish(data.PROBABILITY_DEBT_SERVICE_TO_EXPORTS_DISTRESS.schema, cells=data.PROBABILITY_DEBT_SERVICE_TO_EXPORTS_DISTRESS.cells)
def probability_debt_service_to_exports_distress(*, probability_debt_carrying_capacity_paths: data.Series[float | str | None], probability_regression_diagonal: data.Series[float | str | None], probability_distress_thresholds: data.Series[float | str | None], probability_regression_coefficients: data.Series[float | str | None], probability_debt_service_to_exports: data.ProbabilityDebtServiceToExports) -> data.ProbabilityDebtServiceToExportsDistress:
    """Computes probability-of-distress paths for debt service-to-exports under baseline, historical, MX, and threshold scenarios.

    Evaluates the LIC-DSF probability-approach regression for the debt service-to-exports indicator, applying a logit transform to the indicator and its macro drivers and emitting distress probabilities on the Chart Data year grid.

    Args:
        probability_debt_carrying_capacity_paths: Typed series of carrying-capacity macro paths (CPIA, real GDP growth, reserves, remittances, and world growth) evaluated per projection period.
        probability_regression_diagonal: Typed series supplying the regression scaling applied to the debt service-to-exports ratio before transformation.
        probability_distress_thresholds: Typed series of per-indicator distress thresholds used to produce the fixed Threshold scenario branch.
        probability_regression_coefficients: Typed series of logit coefficients keyed by regressor and indicator for the debt service-to-exports regression.
        probability_debt_service_to_exports: Typed debt service-to-exports series providing the ratio paths indexed by scenario and projection period.

    Returns:
        Typed series of external-debt distress probabilities for debt service-to-exports across the baseline, historical, MX, and threshold scenarios.
    """
    data.PROBABILITY_REGRESSION_DIAGONAL.schema.validate(probability_regression_diagonal)
    data.PROBABILITY_DISTRESS_THRESHOLDS.schema.validate(probability_distress_thresholds)
