@publish(key=(), domain=None, cells=data.TAILORED_STRESS_MARKET_FINANCING_APPLICABLE_CELLS)
def tailored_stress_market_financing_applicable(*, in6_tailored_mkt_financing: str | int | float | bool) -> float | str:
    """Return the market-financing tailored stress applicable flag as a 0/1 measure.

    Translate the Input 6 market-financing tailored-stress choice into the Chart Data applicability signal.

    Args:
        in6_tailored_mkt_financing: Scalar workbook-style boolean indicating whether the market-financing tailored stress test is selected (for example, "Yes" or 1).

    Returns:
        Scalar float, 1.0 when the selection equals "Yes" and 0.0 otherwise, or the Excel error code as a string when evaluation raises an XlError.
    """
    try:
        return as_measure((1 if xl_bool(xl_eq(in6_tailored_mkt_financing, 'Yes')) else 0))
    except XlError as error:
        return error.code

@publish(key=(), domain=None, cells=data.FISCAL_SPACE_MODERATE_RISK_SIGNAL_CELLS)
def fiscal_space_moderate_risk_signal(*, fiscal_space_some_threshold: float | str, fiscal_space_substantial_threshold: float | str, chart_fiscal_space_pv_of_debt_to_gdp_max_baseline_breach: int | str, chart_fiscal_space_pv_of_debt_to_exports_max_baseline_breach: int | str, chart_fiscal_space_debt_service_to_exports_max_baseline_breach: int | str, chart_fiscal_space_debt_service_to_revenue_max_baseline_breach: int | str) -> str | int | float | bool:
    """Return the moderate-risk fiscal-space classification from the maximum baseline breach and threshold comparisons.

    Computes the Chart Data moderate-risk fiscal-space text signal (D23) using the largest baseline breach across four debt indicators against some/substantial thresholds.

    Args:
        fiscal_space_some_threshold: fiscal_space_some_threshold: Scalar threshold used to classify some fiscal space when the maximum baseline breach equals this value.
        fiscal_space_substantial_threshold: fiscal_space_substantial_threshold: Scalar threshold used to classify substantial fiscal space when the maximum baseline breach is below this value.
        chart_fiscal_space_pv_of_debt_to_gdp_max_baseline_breach: chart_fiscal_space_pv_of_debt_to_gdp_max_baseline_breach: Scalar breach indicator (or error string) for the PV of debt-to-GDP baseline; one of the four inputs to the maximum breach comparison.
        chart_fiscal_space_pv_of_debt_to_exports_max_baseline_breach: chart_fiscal_space_pv_of_debt_to_exports_max_baseline_breach: Scalar breach indicator (or error string) for the PV of debt-to-exports baseline; one of the four inputs to the maximum breach comparison.
        chart_fiscal_space_debt_service_to_exports_max_baseline_breach: chart_fiscal_space_debt_service_to_exports_max_baseline_breach: Scalar breach indicator (or error string) for the debt-service-to-exports baseline; one of the four inputs to the maximum breach comparison.
        chart_fiscal_space_debt_service_to_revenue_max_baseline_breach: chart_fiscal_space_debt_service_to_revenue_max_baseline_breach: Scalar breach indicator (or error string) for the debt-service-to-revenue baseline; one of the four inputs to the maximum breach comparison.

    Returns:
        str | int | float | bool: The fiscal-space classification string ('Substantial space', 'Some space', or 'Limited space'), or the workbook error code when an XlError is raised.
    """
    try:
        return as_measure(('Substantial space' if xl_bool(xl_lt(xl_max((chart_fiscal_space_pv_of_debt_to_gdp_max_baseline_breach, chart_fiscal_space_pv_of_debt_to_exports_max_baseline_breach, chart_fiscal_space_debt_service_to_exports_max_baseline_breach, chart_fiscal_space_debt_service_to_revenue_max_baseline_breach)), fiscal_space_substantial_threshold)) else ('Some space' if xl_bool(xl_eq(xl_max((chart_fiscal_space_pv_of_debt_to_gdp_max_baseline_breach, chart_fiscal_space_pv_of_debt_to_exports_max_baseline_breach, chart_fiscal_space_debt_service_to_exports_max_baseline_breach, chart_fiscal_space_debt_service_to_revenue_max_baseline_breach)), fiscal_space_some_threshold)) else 'Limited space')), 'str')
    except XlError as error:
        return error.code

@publish(key=(), domain=None, cells=data.OVERALL_RISK_RATING_SIGNAL_CELLS)
def overall_risk_rating_signal(*, overall_risk_rating_numeric: float | str, chart_numeric_risk_rating: data.Series[int | str | None], chart_risk_labels: data.Series[str | None]) -> str | int | float | bool:
    """Compute the overall combined risk-rating signal.

    Looks up the supplied overall risk-rating value in the authored Chart Data combined rating table to produce the external risk-rating text signal.

    Args:
        overall_risk_rating_numeric: The overall risk rating as a numeric or text value used as the lookup key.
        chart_numeric_risk_rating: A named-axis data.Series of numeric risk-rating values over catalog coordinates, validated against the CHART_NUMERIC_RISK_RATING schema and used for the Low-to-Moderate and High rating rows.
        chart_risk_labels: A named-axis data.Series of risk-label strings over catalog coordinates, validated against the CHART_RISK_LABELS schema and aligned with the numeric rating rows.

    Returns:
        A scalar combined overall risk-rating signal from the lookup as a str, int, float, or bool, or an Excel error code when the lookup fails.
    """
    data.CHART_NUMERIC_RISK_RATING.schema.validate(chart_numeric_risk_rating)
    data.CHART_RISK_LABELS.schema.validate(chart_risk_labels)
    _overall_risk_rating_signal_table_0 = lazy_table(((view(chart_numeric_risk_rating, rows=span(data.VARIANT_AXIS, 'Low', 'Moderate')), view(chart_risk_labels, rows=span(data.VARIANT_AXIS, 'Low', 'Moderate'))), (lambda: None, lambda: None), (lambda: None, lambda: None), (lambda: chart_numeric_risk_rating['High'], lambda: chart_risk_labels['High'])))
    try:
        return as_measure(xl_vlookup(overall_risk_rating_numeric, _overall_risk_rating_signal_table_0, 2, False), 'str')
    except XlError as error:
        return error.code

@publish(key=(), domain=None, cells=data.OVERALL_RISK_RATING_NUMERIC_CELLS)
def overall_risk_rating_numeric(*, external_dsa_risk_rating_numeric: float | str, fiscal_risk_rating_numeric: float | str) -> float | str:
    """Compute the overall combined risk-rating numeric code.

    Combine the external DSA and fiscal risk-rating signals into the workbook's overall rating used on Chart Data.

    Args:
        external_dsa_risk_rating_numeric: Numeric code or string signal for the external DSA risk rating.
        fiscal_risk_rating_numeric: Numeric code or string signal for the fiscal (total public debt) risk rating.

    Returns:
        Overall combined risk-rating numeric code (Chart Data!L11) as 1, 2, or 3; or an XlError code string when evaluation fails.
    """
    try:
        return as_measure((1 if xl_bool(xl_and(xl_eq(external_dsa_risk_rating_numeric, 1), xl_eq(fiscal_risk_rating_numeric, 1))) else (3 if xl_bool(xl_or(xl_eq(external_dsa_risk_rating_numeric, 3), xl_eq(fiscal_risk_rating_numeric, 3))) else 2)))
    except XlError as error:
        return error.code

@publish(data.CHART_OUTPUT_CHART_DATA_PV_OF_DEBT_TO_REVENUE_RATIO_PV_DEBT_TO_REVENUE.schema, cells=data.CHART_OUTPUT_CHART_DATA_PV_OF_DEBT_TO_REVENUE_RATIO_PV_DEBT_TO_REVENUE.cells)
def chart_output_chart_data_pv_of_debt_to_revenue_ratio_pv_debt_to_revenue(*, chart_tailored_test_marker: int | str, dsa_pub_pv_of_public_debt_to_revenue_and_grants_ratio: data.Series[float | str | None], customized_public_include_scenario: str, chart_chart_data_pv_of_debt_to_revenue_ratio_c2_natural_disaster_stres: int | str, chart_chart_data_pv_of_debt_to_revenue_ratio_c3_commodity_price_stress: int | str, chart_chart_data_pv_of_debt_to_revenue_ratio_c4_market_financing_stres: int | str, chart_pv_of_debt_to_revenue_ratio_applicable_flag_b2_1_primary_balance_market: int | str, chart_pv_of_debt_to_revenue_ratio_applicable_flag_combined_market_financing_stress: int | str, chart_internal_chart_data_pv_of_debt_to_revenue_ratio_pv_debt_to_revenue_stress_path: data.Series[float | str | None], chart_internal_chart_data_pv_of_debt_to_revenue_ratio_pv_debt_to_revenue_figure: data.Series[float | str | None], baseline_pub_pv_of_public_debt_revenue_grants_ratio: data.Series[float | str | None], baseline_pub_pv_of_public_debt_revenue_grants_ratio_exports_shock: data.Series[float | str | None], baseline_pub_pv_of_public_debt_revenue_grants_ratio_b4_other: data.Series[float | str | None], custom_pub_pv_of_public_debt_revenue_grants_ratio: data.Series[float | str | None], in6opt_standard_scenario: int | str) -> data.ChartOutputChartDataPvOfDebtToRevenueRatioPvDebtToRevenue:
    """Compute the PV of Debt-to-Revenue chart series across DSA scenarios.

    Assemble the Chart Data PV of debt-to-revenue ratio row series by scenario, applying tailored-stress applicability flags and standardized-scenario gating.

    Args:
        chart_tailored_test_marker: Scalar marker identifying which tailored stress tests are enabled for the chart; compared against each tailored-test applicability flag to decide market versus non-market and blank rows.
        dsa_pub_pv_of_public_debt_to_revenue_and_grants_ratio: Scenario-keyed series of PV of public debt-to-revenue-and-grants ratios supplying the A1, B1, B5, and C1 rows over projection periods.
        customized_public_include_scenario: Scenario-inclusion string for the customized public scenario; a value of 'No' suppresses customized rows with a #N/A error.
        chart_chart_data_pv_of_debt_to_revenue_ratio_c2_natural_disaster_stres: Scalar applicability flag for the C2 natural disaster tailored stress test; when it does not match the tailored-test marker the C2 row is blank.
        chart_chart_data_pv_of_debt_to_revenue_ratio_c3_commodity_price_stress: Scalar applicability flag for the C3 commodity price tailored stress test; when it does not match the tailored-test marker the C3 row is blank.
        chart_chart_data_pv_of_debt_to_revenue_ratio_c4_market_financing_stres: Scalar applicability flag for the C4 market financing tailored stress test; when it does not match the tailored-test marker the C4 row is blank.
        chart_pv_of_debt_to_revenue_ratio_applicable_flag_b2_1_primary_balance_market: Scalar applicability flag selecting the B2.1 market primary-balance stress path when it matches the tailored-test marker, otherwise the B2.2 non-market path.
        chart_pv_of_debt_to_revenue_ratio_applicable_flag_combined_market_financing_stress: Scalar applicability flag selecting the B6.1 market combination stress path when it matches the tailored-test marker, otherwise the B6.2 non-market path.
        chart_internal_chart_data_pv_of_debt_to_revenue_ratio_pv_debt_to_revenue_stress_path: Scenario-labelled series of PV of debt-to-revenue stress paths keyed by the B2.1/B2.2 and B6.1/B6.2 variants over projection periods.
        chart_internal_chart_data_pv_of_debt_to_revenue_ratio_pv_debt_to_revenue_figure: Scenario- and period-indexed figure series providing the C2-C4 tailored-stress values.
        baseline_pub_pv_of_public_debt_revenue_grants_ratio: Baseline PV of public debt-to-revenue-and-grants ratio indexed by projection period.
        baseline_pub_pv_of_public_debt_revenue_grants_ratio_exports_shock: Exports-shock PV of debt-to-revenue-and-grants ratio indexed by projection period, used for the B3 row.
        baseline_pub_pv_of_public_debt_revenue_grants_ratio_b4_other: Other-flows PV of debt-to-revenue-and-grants ratio indexed by projection period, used for the B4 row.
        custom_pub_pv_of_public_debt_revenue_grants_ratio: Customized public scenario PV of debt-to-revenue-and-grants ratio indexed by projection period.
        in6opt_standard_scenario: Scalar standardized-scenario option; a value of 0 zeroes the B3 and B4 contributions.

    Returns:
        A typed data.ChartOutputChartDataPvOfDebtToRevenueRatioPvDebtToRevenue series of PV of debt-to-revenue ratio measures (float, str, or None) keyed by scenario over the projection horizon.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        if scenario == 'Baseline':
            return as_measure(baseline_pub_pv_of_public_debt_revenue_grants_ratio[time_period])
        elif scenario == 'A1. Key variables at their historical averages in 2024-2034 2/':
            return as_measure(dsa_pub_pv_of_public_debt_to_revenue_and_grants_ratio['A1', time_period])
        elif scenario == 'B1. Real GDP growth':
            return as_measure(dsa_pub_pv_of_public_debt_to_revenue_and_grants_ratio['B1', time_period])
        elif scenario == 'B2. Primary balance':
            return as_measure((chart_internal_chart_data_pv_of_debt_to_revenue_ratio_pv_debt_to_revenue_stress_path['B2.1 Primary balance Market', time_period] if xl_bool(xl_eq(chart_tailored_test_marker, chart_pv_of_debt_to_revenue_ratio_applicable_flag_b2_1_primary_balance_market)) else chart_internal_chart_data_pv_of_debt_to_revenue_ratio_pv_debt_to_revenue_stress_path['B2.2 Primary balance Non-Market', time_period]))
        elif scenario == 'B3. Exports':
            return as_measure((0 if xl_bool(xl_eq(in6opt_standard_scenario, 0)) else baseline_pub_pv_of_public_debt_revenue_grants_ratio_exports_shock[time_period]))
        elif scenario == 'B4. Other flows 3/':
            return as_measure((0 if xl_bool(xl_eq(in6opt_standard_scenario, 0)) else baseline_pub_pv_of_public_debt_revenue_grants_ratio_b4_other[time_period]))
        elif scenario == 'B5. Depreciation':
            return as_measure(dsa_pub_pv_of_public_debt_to_revenue_and_grants_ratio['B5', time_period])
        elif scenario == 'B6. Combination of B1-B5':
            return as_measure((chart_internal_chart_data_pv_of_debt_to_revenue_ratio_pv_debt_to_revenue_stress_path['B6.1 Combination of B1-B5 Market', time_period] if xl_bool(xl_eq(chart_tailored_test_marker, chart_pv_of_debt_to_revenue_ratio_applicable_flag_combined_market_financing_stress)) else chart_internal_chart_data_pv_of_debt_to_revenue_ratio_pv_debt_to_revenue_stress_path['B6.2 Combination of B1-B5 Non-Market', time_period]))
        elif scenario == 'C1. Combined contingent liabilities':
            return as_measure(dsa_pub_pv_of_public_debt_to_revenue_and_grants_ratio['C1', time_period])
        elif scenario == 'C2. Natural disaster':
            return as_measure(xl_iferror(lambda: (chart_internal_chart_data_pv_of_debt_to_revenue_ratio_pv_debt_to_revenue_figure[scenario, time_period] if xl_bool(xl_eq(chart_tailored_test_marker, chart_chart_data_pv_of_debt_to_revenue_ratio_c2_natural_disaster_stres)) else ' '), lambda: ' '))
        elif scenario == 'C3. Commodity price':
            return as_measure(xl_iferror(lambda: (chart_internal_chart_data_pv_of_debt_to_revenue_ratio_pv_debt_to_revenue_figure[scenario, time_period] if xl_bool(xl_eq(chart_tailored_test_marker, chart_chart_data_pv_of_debt_to_revenue_ratio_c3_commodity_price_stress)) else ' '), lambda: ' '))
        elif scenario == 'C4. Market Financing':
            return as_measure(xl_iferror(lambda: (chart_internal_chart_data_pv_of_debt_to_revenue_ratio_pv_debt_to_revenue_figure[scenario, time_period] if xl_bool(xl_eq(chart_tailored_test_marker, chart_chart_data_pv_of_debt_to_revenue_ratio_c4_market_financing_stres)) else ' '), lambda: ' '))
        return as_measure((xl_raise('#N/A') if xl_bool(xl_eq(customized_public_include_scenario, 'No')) else custom_pub_pv_of_public_debt_revenue_grants_ratio[time_period]))

    return data.CHART_OUTPUT_CHART_DATA_PV_OF_DEBT_TO_REVENUE_RATIO_PV_DEBT_TO_REVENUE.collect(evaluate(formula, data.CHART_OUTPUT_CHART_DATA_PV_OF_DEBT_TO_REVENUE_RATIO_PV_DEBT_TO_REVENUE.required))

@publish(data.CHART_OUTPUT_CHART_DATA_DEBT_SERVICE_TO_REVENUE_RATIO_DEBT_SERVICE_TO_REVENUE.schema, cells=data.CHART_OUTPUT_CHART_DATA_DEBT_SERVICE_TO_REVENUE_RATIO_DEBT_SERVICE_TO_REVENUE.cells)
def chart_output_chart_data_debt_service_to_revenue_ratio_debt_service_to_revenue(*, chart_tailored_test_marker: int | str, dsa_pub_debt_service_to_revenue_and_grants_ratio_in_percent: data.Series[float | str | None], customized_public_include_scenario: str, chart_chart_data_debt_service_to_revenue_ratio_c2_natural_disaster_str: int | str, chart_chart_data_debt_service_to_revenue_ratio_c3_commodity_price_stre: int | str, chart_chart_data_debt_service_to_revenue_ratio_c4_market_financing_str: int | str, chart_applicable_flag_b2_1_primary_balance_market: int | str, chart_applicable_flag_combined_market_financing_stress: int | str, chart_internal_chart_data_debt_service_to_revenue_ratio_debt_service_to_revenue_stress_path: data.Series[float | str | None], chart_internal_chart_data_debt_service_to_revenue_ratio_debt_service_to_revenue_figure: data.Series[float | str | None], baseline_pub_debt_service_revenue_grants_ratio: data.Series[float | str | None], baseline_pub_debt_service_revenue_grants_ratio_b3_exports: data.Series[float | str | None], baseline_pub_debt_service_revenue_grants_ratio_b4_other_flows: data.Series[float | str | None], custom_pub_debt_service_revenue_grants_ratio: data.Series[float | str | None], in6opt_standard_scenario: int | str) -> data.ChartOutputChartDataDebtServiceToRevenueRatioDebtServiceToRevenue:
    """Compute the Chart Data Debt Service-to-Revenue Ratio stress ladder for each public DSA scenario.

    Produce the scenario-keyed debt service-to-revenue chart series used in the LIC-DSF public debt stress output.

    Args:
        chart_tailored_test_marker: Integer or string scalar marker selecting the tailored stress test used for chart output.
        dsa_pub_debt_service_to_revenue_and_grants_ratio_in_percent: Typed data series of public debt service-to-revenue-and-grants ratios in percent, keyed by scenario name and time period.
        customized_public_include_scenario: String scalar naming the customized public scenario inclusion option.
        chart_chart_data_debt_service_to_revenue_ratio_c2_natural_disaster_str: Integer or string scalar threshold or flag for the C2 natural disaster tailored stress test.
        chart_chart_data_debt_service_to_revenue_ratio_c3_commodity_price_stre: Integer or string scalar threshold or flag for the C3 commodity price tailored stress test.
        chart_chart_data_debt_service_to_revenue_ratio_c4_market_financing_str: Integer or string scalar threshold or flag for the C4 market financing tailored stress test.
        chart_applicable_flag_b2_1_primary_balance_market: Integer or string scalar applicability flag for the B2.1 primary balance market-financing stress path.
        chart_applicable_flag_combined_market_financing_stress: Integer or string scalar applicability flag for the combined market-financing stress test.
        chart_internal_chart_data_debt_service_to_revenue_ratio_debt_service_to_revenue_stress_path: Typed data series of internal Chart Data debt service-to-revenue stress-path values, keyed by stress-path label and time period.
        chart_internal_chart_data_debt_service_to_revenue_ratio_debt_service_to_revenue_figure: Typed data series of internal Chart Data debt service-to-revenue figure values, keyed by scenario name and time period.
        baseline_pub_debt_service_revenue_grants_ratio: Typed data series of baseline public debt service-to-revenue-and-grants ratios, keyed by time period.
        baseline_pub_debt_service_revenue_grants_ratio_b3_exports: Typed data series of baseline B3 exports public debt service-to-revenue-and-grants ratios, keyed by time period.
        baseline_pub_debt_service_revenue_grants_ratio_b4_other_flows: Typed data series of baseline B4 other flows public debt service-to-revenue-and-grants ratios, keyed by time period.
        custom_pub_debt_service_revenue_grants_ratio: Typed data series of customized public debt service-to-revenue-and-grants ratios, keyed by time period.
        in6opt_standard_scenario: Integer or string scalar indicating the Input 6 standard scenario option.

    Returns:
        A typed data.ChartOutputChartDataDebtServiceToRevenueRatioDebtServiceToRevenue chart-output collection holding the Debt Service-to-Revenue Ratio on Chart Data, keyed by scenario and time period.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        if scenario == 'Baseline':
            return as_measure(baseline_pub_debt_service_revenue_grants_ratio[time_period])
        elif scenario == 'A1. Key variables at their historical averages in 2024-2034 2/':
            return as_measure(dsa_pub_debt_service_to_revenue_and_grants_ratio_in_percent['A1', time_period])
        elif scenario == 'B1. Real GDP growth':
            return as_measure(dsa_pub_debt_service_to_revenue_and_grants_ratio_in_percent['B1', time_period])
