@publish(data.PV_BASE_DISCOUNT_DEBT_STOCK.schema, cells=data.PV_BASE_DISCOUNT_DEBT_STOCK.cells)
def pv_base_discount_debt_stock(*, pv_base_opening_percent_of_face: data.Series[int | str | None], pv_base_discount_amortization: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Derive the per-instrument PV-basis discount debt stock from opening face-value percentages and discount amortization.

    Recursively rolls each instrument's discount-basis debt forward, seeding 2024 from the opening percent-of-face balance and each later year from the prior year's stock less current amortization.

    Args:
        pv_base_opening_percent_of_face: data.Series[int | str | None] of opening percent-of-face values indexed by instrument and year, supplying the 2024 seed balance for each catalog instrument.
        pv_base_discount_amortization: data.Series[float | str | None] of discount amortization amounts indexed by instrument and year, subtracted each period from the opening balance or prior stock.

    Returns:
        data.Series[float | str | None] of debt stock on the discount basis, indexed by instrument and projection year.
    """
    data.PV_BASE_OPENING_PERCENT_OF_FACE.schema.validate(pv_base_opening_percent_of_face)
    def formula(instrument: str, time_period: int) -> float | str | None:
        if instrument == 'IMF' and time_period == 2024:
            return as_measure(xl_sub(pv_base_opening_percent_of_face[instrument], pv_base_discount_amortization['IMF', time_period]))
        elif instrument == 'IMF' and time_period == 2025:
            return as_measure(xl_sub(pv_base_discount_debt_stock[instrument, time_period - 1], pv_base_discount_amortization['IMF', time_period]))
        elif instrument == 'IDA - regular' and time_period == 2024:
            return as_measure(xl_sub(pv_base_opening_percent_of_face[instrument], pv_base_discount_amortization['IDA - regular', time_period]))
        elif instrument == 'IDA - regular' and time_period == 2025:
            return as_measure(xl_sub(pv_base_discount_debt_stock[instrument, time_period - 1], pv_base_discount_amortization['IDA - regular', time_period]))
        elif instrument == 'IDA - 50Y loans' and time_period == 2024:
            return as_measure(xl_sub(pv_base_opening_percent_of_face[instrument], pv_base_discount_amortization['IDA - 50Y loans', time_period]))
        elif instrument == 'IDA - 50Y loans' and time_period == 2025:
            return as_measure(xl_sub(pv_base_discount_debt_stock[instrument, time_period - 1], pv_base_discount_amortization['IDA - 50Y loans', time_period]))
        elif instrument == 'IDA - SML' and time_period == 2024:
            return as_measure(xl_sub(pv_base_opening_percent_of_face[instrument], pv_base_discount_amortization['IDA - SML', time_period]))
        elif instrument == 'IDA - SML' and time_period == 2025:
            return as_measure(xl_sub(pv_base_discount_debt_stock[instrument, time_period - 1], pv_base_discount_amortization['IDA - SML', time_period]))
        elif instrument == 'IDA NEW 40-year credits' and time_period == 2024:
            return as_measure(xl_sub(pv_base_opening_percent_of_face[instrument], pv_base_discount_amortization['IDA NEW 40-year credits', time_period]))
        elif instrument == 'IDA NEW 40-year credits' and time_period == 2025:
            return as_measure(xl_sub(pv_base_discount_debt_stock[instrument, time_period - 1], pv_base_discount_amortization['IDA NEW 40-year credits', time_period]))
        elif instrument == 'IDA NEW Regular' and time_period == 2024:
            return as_measure(xl_sub(pv_base_opening_percent_of_face[instrument], pv_base_discount_amortization['IDA NEW Regular', time_period]))
        elif instrument == 'IDA NEW Regular' and time_period == 2025:
            return as_measure(xl_sub(pv_base_discount_debt_stock[instrument, time_period - 1], pv_base_discount_amortization['IDA NEW Regular', time_period]))
        elif instrument == 'IDA NEW Blend floating' and time_period == 2024:
            return as_measure(xl_sub(pv_base_opening_percent_of_face[instrument], pv_base_discount_amortization['IDA NEW Blend floating', time_period]))
        elif instrument == 'IDA NEW Blend floating' and time_period == 2025:
            return as_measure(xl_sub(pv_base_discount_debt_stock[instrument, time_period - 1], pv_base_discount_amortization['IDA NEW Blend floating', time_period]))
        elif instrument == 'IDA NEW 60-year credits' and time_period == 2024:
            return as_measure(xl_sub(pv_base_opening_percent_of_face[instrument], pv_base_discount_amortization['IDA NEW 60-year credits', time_period]))
        elif instrument == 'IDA NEW 60-year credits' and time_period == 2025:
            return as_measure(xl_sub(pv_base_discount_debt_stock[instrument, time_period - 1], pv_base_discount_amortization['IDA NEW 60-year credits', time_period]))
        elif instrument == 'MULTI1' and time_period == 2024:
            return as_measure(xl_sub(pv_base_opening_percent_of_face[instrument], pv_base_discount_amortization['MULTI1', time_period]))
        elif instrument == 'MULTI1' and time_period == 2025:
            return as_measure(xl_sub(pv_base_discount_debt_stock[instrument, time_period - 1], pv_base_discount_amortization['MULTI1', time_period]))
