@publish(data.PV_BASE_DISCOUNT_INTEREST.schema, cells=data.PV_BASE_DISCOUNT_INTEREST.cells)
def pv_base_discount_interest(*, pv_base_multilaterals_by_year: data.Series[int | str | None], pv_base_block_interest: data.Series[float | str | None], pv_base_discount_debt_stock: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute per-instrument interest on the PV-baseline discount schedule from block interest rates and prior-year debt stocks.

    Derive the Interest column of pv_base.discount_schedule by multiplying each instrument's block interest rate by its lagged discounted debt stock, honoring per-instrument horizon cutoffs.

    Args:
        pv_base_multilaterals_by_year: data.Series[int | str | None] over the catalog coordinate grid holding the multilaterals vintage year per time period; consulted for the IMF row so that interest is zeroed out through 2018 and otherwise carried forward, with blanks or string sentinels where undefined.
        pv_base_block_interest: data.Series[float | str | None] of fractional block interest rates, one value per instrument on the discount-schedule instrument axis, with blank or string sentinels where a rate is unavailable.
        pv_base_discount_debt_stock: data.Series[float | str | None] of discounted debt stocks indexed by instrument and time period; the helper reads each instrument's lagged entry (time_period - 1) to pair with its block interest rate.

    Returns:
        data.Series[float | str | None] of computed interest amounts over the discount-schedule instrument/year grid, blank or string sentinel once an instrument's projection horizon is exceeded.
    """
    def formula(instrument: str, time_period: int) -> float | str | None:
        if instrument == 'IDA NEW Blend floating' and time_period <= 2049:
            return as_measure(xl_mul(pv_base_block_interest['IDA NEW Blend floating'], pv_base_discount_debt_stock['IDA NEW Blend floating', time_period - 1]))
        elif instrument == 'IDA NEW Regular' and time_period <= 2058:
            return as_measure(xl_mul(pv_base_block_interest['IDA NEW Regular'], pv_base_discount_debt_stock['IDA NEW Regular', time_period - 1]))
        elif instrument == 'Export Credit Agencies' and time_period <= 2063:
            return as_measure(xl_mul(pv_base_block_interest['Export Credit Agencies'], pv_base_discount_debt_stock['Export Credit Agencies', time_period - 1]))
        elif instrument == 'PC2' and time_period <= 2063:
            return as_measure(xl_mul(pv_base_block_interest['PC2'], pv_base_discount_debt_stock['PC2', time_period - 1]))
        elif instrument == 'PC3' and time_period <= 2063:
            return as_measure(xl_mul(pv_base_block_interest['PC3'], pv_base_discount_debt_stock['PC3', time_period - 1]))
        elif instrument == 'PC4' and time_period <= 2063:
            return as_measure(xl_mul(pv_base_block_interest['PC4'], pv_base_discount_debt_stock['PC4', time_period - 1]))
        elif instrument == 'PC5' and time_period <= 2063:
            return as_measure(xl_mul(pv_base_block_interest['PC5'], pv_base_discount_debt_stock['PC5', time_period - 1]))
        elif instrument == 'Export Import Bank of NPC' and time_period <= 2063:
            return as_measure(xl_mul(pv_base_block_interest['Export Import Bank of NPC'], pv_base_discount_debt_stock['Export Import Bank of NPC', time_period - 1]))
        elif instrument == 'NPC2' and time_period <= 2063:
            return as_measure(xl_mul(pv_base_block_interest['NPC2'], pv_base_discount_debt_stock['NPC2', time_period - 1]))
        elif instrument == 'NPC3' and time_period <= 2063:
            return as_measure(xl_mul(pv_base_block_interest['NPC3'], pv_base_discount_debt_stock['NPC3', time_period - 1]))
        elif instrument == 'NPC4' and time_period <= 2063:
            return as_measure(xl_mul(pv_base_block_interest['NPC4'], pv_base_discount_debt_stock['NPC4', time_period - 1]))
        elif instrument == 'NPC5' and time_period <= 2063:
            return as_measure(xl_mul(pv_base_block_interest['NPC5'], pv_base_discount_debt_stock['NPC5', time_period - 1]))
        elif instrument == 'Eurobond' and time_period <= 2063:
            return as_measure(xl_mul(pv_base_block_interest['Eurobond'], pv_base_discount_debt_stock['Eurobond', time_period - 1]))
        elif instrument == 'Commecial Bank' and time_period <= 2063:
            return as_measure(xl_mul(pv_base_block_interest['Commecial Bank'], pv_base_discount_debt_stock['Commecial Bank', time_period - 1]))
        elif instrument == 'COM3' and time_period <= 2063:
            return as_measure(xl_mul(pv_base_block_interest['COM3'], pv_base_discount_debt_stock['COM3', time_period - 1]))
        elif instrument == 'COM4' and time_period <= 2063:
            return as_measure(xl_mul(pv_base_block_interest['COM4'], pv_base_discount_debt_stock['COM4', time_period - 1]))
        elif instrument == 'COM5' and time_period <= 2063:
            return as_measure(xl_mul(pv_base_block_interest['COM5'], pv_base_discount_debt_stock['COM5', time_period - 1]))
        elif instrument == 'IDA NEW 40-year credits' and time_period <= 2064:
            return as_measure(xl_mul(pv_base_block_interest['IDA NEW 40-year credits'], pv_base_discount_debt_stock['IDA NEW 40-year credits', time_period - 1]))
        elif instrument == 'IDA - 50Y loans' and time_period <= 2074:
            return as_measure(xl_mul(pv_base_block_interest['IDA - 50Y loans'], pv_base_discount_debt_stock['IDA - 50Y loans', time_period - 1]))
        elif instrument == 'IMF' and time_period <= 2076:
            return as_measure((0 if xl_bool(xl_le(pv_base_multilaterals_by_year[time_period], 2018)) else xl_mul(pv_base_block_interest['IMF'], pv_base_discount_debt_stock['IMF', time_period - 1])))
        elif instrument == 'IDA - regular' and time_period <= 2076:
            return as_measure(xl_mul(pv_base_block_interest['IDA - regular'], pv_base_discount_debt_stock['IDA - regular', time_period - 1]))
        elif instrument == 'IDA - SML' and time_period <= 2076:
            return as_measure(xl_mul(pv_base_block_interest['IDA - SML'], pv_base_discount_debt_stock['IDA - SML', time_period - 1]))
        elif instrument == 'MULTI1' and time_period <= 2076:
            return as_measure(xl_mul(pv_base_block_interest['MULTI1'], pv_base_discount_debt_stock['MULTI1', time_period - 1]))
        elif instrument == 'MULTI2' and time_period <= 2076:
            return as_measure(xl_mul(pv_base_block_interest['MULTI2'], pv_base_discount_debt_stock['MULTI2', time_period - 1]))
        elif instrument == 'OTH_MULTI1' and time_period <= 2076:
            return as_measure(xl_mul(pv_base_block_interest['OTH_MULTI1'], pv_base_discount_debt_stock['OTH_MULTI1', time_period - 1]))
        elif instrument == 'OTH_MULTI2' and time_period <= 2076:
            return as_measure(xl_mul(pv_base_block_interest['OTH_MULTI2'], pv_base_discount_debt_stock['OTH_MULTI2', time_period - 1]))
        elif instrument == 'OTH_MULTI3' and time_period <= 2076:
            return as_measure(xl_mul(pv_base_block_interest['OTH_MULTI3'], pv_base_discount_debt_stock['OTH_MULTI3', time_period - 1]))
        return as_measure(xl_mul(pv_base_block_interest['IDA NEW 60-year credits'], pv_base_discount_debt_stock['IDA NEW 60-year credits', time_period - 1]))

    return data.PV_BASE_DISCOUNT_INTEREST.collect(evaluate(formula, data.PV_BASE_DISCOUNT_INTEREST.required))

@publish(data.PV_BASE_DISCOUNT_TOTAL_DEBT_SERVICE.schema, cells=data.PV_BASE_DISCOUNT_TOTAL_DEBT_SERVICE.cells)
def pv_base_discount_total_debt_service(*, pv_base_discount_amortization: data.Series[float | str | None], pv_base_discount_interest: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Add amortization and interest to produce total debt service per instrument and year on the PV base discount schedule.

    Computes the `pv_base.discount_schedule` total-debt-service series by summing the two component schedules coordinate-wise across the instrument and time-period grid.

    Args:
        pv_base_discount_amortization: Per-instrument scheduled principal amortization on the PV base discount schedule, as a `data.Series[float | str | None]` indexed by instrument (28 members) and time-period coordinates.
        pv_base_discount_interest: Per-instrument interest on the PV base discount schedule, as a `data.Series[float | str | None]` sharing the same instrument and time-period coordinates.

    Returns:
        A `data.Series[float | str | None]` of total debt service (amortization plus interest) aligned to the instrument and time-period coordinates of `data.PV_BASE_DISCOUNT_TOTAL_DEBT_SERVICE`, carrying blanks where either component is missing.
    """
    def formula(instrument: str, time_period: int) -> float | str | None:
        if instrument == 'IDA NEW Blend floating' and time_period <= 2049:
            return as_measure(xl_add(pv_base_discount_amortization['IDA NEW Blend floating', time_period], pv_base_discount_interest['IDA NEW Blend floating', time_period]))
        elif instrument == 'IDA NEW Regular' and time_period <= 2058:
            return as_measure(xl_add(pv_base_discount_amortization['IDA NEW Regular', time_period], pv_base_discount_interest['IDA NEW Regular', time_period]))
        elif instrument == 'Export Credit Agencies' and time_period <= 2063:
            return as_measure(xl_add(pv_base_discount_amortization['Export Credit Agencies', time_period], pv_base_discount_interest['Export Credit Agencies', time_period]))
