@publish(data.PV_BASE_OUTPUT_NEW_FOREX_BORROWING_GROSS_USD.schema, cells=data.PV_BASE_OUTPUT_NEW_FOREX_BORROWING_GROSS_USD.cells)
def pv_base_output_new_forex_borrowing_gross_usd(*, ext_debt_new_disbursements_external: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Assemble the pv_base new forex borrowing (gross, USD) series from external debt disbursements.

    Produce the gross new foreign-currency borrowing output used by the LIC-DSF external debt projection.

    Args:
        ext_debt_new_disbursements_external: A data.Series[float | str | None] over instrument and time_period catalog coordinates giving new external debt disbursements from the external financing input, spanning the 28 instruments (IDA, IMF, MULTI, NPC, PC, Eurobond, commercial, and others) that feed the gross forex borrowing calculation.

    Returns:
        A data.Series[float | str | None] over instrument and time_period containing the new forex borrowing (gross, USD) output, assembled per instrument with schedule-dependent cutoffs and fallback to the IDA - 50Y loans schedule.
    """
    def formula(instrument: str, time_period: int) -> float | str | None:
        if instrument == 'IDA NEW 60-year credits' and time_period >= 2070:
            return as_measure(0)
        elif instrument == 'IDA NEW Blend floating' and time_period <= 2049:
            return as_measure(ext_debt_new_disbursements_external['IDA NEW Blend (also enter) -->', time_period])
        elif instrument == 'IMF' and time_period <= 2051:
            return as_measure(ext_debt_new_disbursements_external['IMF', time_period])
        elif instrument == 'IDA - SML' and time_period <= 2051:
            return as_measure(ext_debt_new_disbursements_external['IDA - SML', time_period])
        elif instrument == 'MULTI1' and time_period <= 2051:
            return as_measure(ext_debt_new_disbursements_external['MULTI1', time_period])
        elif instrument == 'MULTI2' and time_period <= 2051:
            return as_measure(ext_debt_new_disbursements_external['MULTI2', time_period])
        elif instrument == 'OTH_MULTI1' and time_period <= 2051:
            return as_measure(ext_debt_new_disbursements_external['OTH_MULTI1', time_period])
        elif instrument == 'OTH_MULTI2' and time_period <= 2051:
            return as_measure(ext_debt_new_disbursements_external['OTH_MULTI2', time_period])
        elif instrument == 'OTH_MULTI3' and time_period <= 2051:
            return as_measure(ext_debt_new_disbursements_external['OTH_MULTI3', time_period])
        elif instrument == 'Export Credit Agencies' and time_period <= 2051:
            return as_measure(ext_debt_new_disbursements_external['Export Credit Agencies', time_period])
        elif instrument == 'PC2' and time_period <= 2051:
            return as_measure(ext_debt_new_disbursements_external['PC2', time_period])
        elif instrument == 'PC3' and time_period <= 2051:
            return as_measure(ext_debt_new_disbursements_external['PC3', time_period])
        elif instrument == 'PC4' and time_period <= 2051:
            return as_measure(ext_debt_new_disbursements_external['PC4', time_period])
        elif instrument == 'PC5' and time_period <= 2051:
            return as_measure(ext_debt_new_disbursements_external['PC5', time_period])
        elif instrument == 'Export Import Bank of NPC' and time_period <= 2051:
            return as_measure(ext_debt_new_disbursements_external['Export Import Bank of NPC', time_period])
        elif instrument == 'NPC2' and time_period <= 2051:
            return as_measure(ext_debt_new_disbursements_external['NPC2', time_period])
        elif instrument == 'NPC3' and time_period <= 2051:
            return as_measure(ext_debt_new_disbursements_external['NPC3', time_period])
        elif instrument == 'NPC4' and time_period <= 2051:
            return as_measure(ext_debt_new_disbursements_external['NPC4', time_period])
        elif instrument == 'NPC5' and time_period <= 2051:
            return as_measure(ext_debt_new_disbursements_external['NPC5', time_period])
        elif instrument == 'Eurobond' and time_period <= 2051:
            return as_measure(ext_debt_new_disbursements_external['Eurobond', time_period])
        elif instrument == 'Commecial Bank' and time_period <= 2051:
            return as_measure(ext_debt_new_disbursements_external['Commecial Bank', time_period])
        elif instrument == 'COM3' and time_period <= 2051:
            return as_measure(ext_debt_new_disbursements_external['COM3', time_period])
        elif instrument == 'COM4' and time_period <= 2051:
            return as_measure(ext_debt_new_disbursements_external['COM4', time_period])
        elif instrument == 'COM5' and time_period <= 2051:
            return as_measure(ext_debt_new_disbursements_external['COM5', time_period])
        elif instrument == 'IDA NEW Regular' and time_period <= 2058:
            return as_measure(ext_debt_new_disbursements_external['IDA NEW Regular', time_period])
        elif instrument == 'IDA - regular' and time_period <= 2062:
            return as_measure(ext_debt_new_disbursements_external['IDA - regular', time_period])
        elif instrument == 'IDA NEW 40-year credits' and time_period <= 2064:
            return as_measure(ext_debt_new_disbursements_external['IDA NEW 40-year credits', time_period])
        elif instrument == 'IDA NEW 60-year credits' and time_period <= 2069:
            return as_measure(ext_debt_new_disbursements_external['IDA NEW 60-year credits', time_period])
        return as_measure(ext_debt_new_disbursements_external['IDA - 50Y loans', time_period])

    return data.PV_BASE_OUTPUT_NEW_FOREX_BORROWING_GROSS_USD.collect(evaluate(formula, data.PV_BASE_OUTPUT_NEW_FOREX_BORROWING_GROSS_USD.required))

@publish(data.PV_BASE_OUTPUT_CUMULATIVE.schema, cells=data.PV_BASE_OUTPUT_CUMULATIVE.cells)
def pv_base_output_cumulative(*, pv_base_output_new_forex_borrowing_gross_usd: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Accumulate gross new foreign-currency borrowing into cumulative output by instrument and year.

    Provides the `pv_base_output_cumulative` series consumed by the LIC-DSF PV Base output layer, replacing the workbook's per-instrument running-sum formulas.

    Args:
        pv_base_output_new_forex_borrowing_gross_usd: Keyword-only named-axis `data.Series[float | str | None]` of gross new foreign-currency borrowing in USD over catalog instrument and TIME_PERIOD coordinates, evaluated on the `PV_BASE_OUTPUT_CUMULATIVE` required domain.

    Returns:
        A `data.Series[float | str | None]` over the same instrument and TIME_PERIOD coordinates, holding each cell's cumulative gross borrowing (running sum from 2024, with instrument-specific windows and blank/string passthrough).
    """
    def formula(instrument: str, time_period: int) -> float | str | None:
        if instrument in ('IDA NEW Regular', 'IDA NEW 60-year credits') and time_period == 2025:
            return as_measure(xl_sum(view(pv_base_output_new_forex_borrowing_gross_usd, rows=(instrument,), cols=span(data.TIME_PERIOD_AXIS, 2024, time_period))))
        elif instrument == 'IDA NEW Blend floating' and 2026 <= time_period <= 2049:
            return as_measure(xl_sum(view(pv_base_output_new_forex_borrowing_gross_usd, rows=('IDA NEW Blend floating',), cols=span(data.TIME_PERIOD_AXIS, 2024, time_period))))
        elif instrument in ('IMF', 'IDA - regular', 'IDA - 50Y loans', 'IDA - SML', 'IDA NEW 40-year credits', 'IDA NEW Blend floating', 'MULTI1', 'MULTI2', 'OTH_MULTI1', 'OTH_MULTI2', 'OTH_MULTI3', 'Export Credit Agencies', 'PC2', 'PC3', 'PC4', 'PC5', 'Export Import Bank of NPC', 'NPC2', 'NPC3', 'NPC4', 'NPC5', 'Eurobond', 'Commecial Bank', 'COM3', 'COM4', 'COM5') and time_period == 2025:
            return as_measure(xl_sum(view(pv_base_output_new_forex_borrowing_gross_usd, rows=(instrument,), cols=span(data.TIME_PERIOD_AXIS, time_period - 1, time_period))))
        elif instrument == 'IMF' and 2026 <= time_period <= 2051:
            return as_measure(xl_sum(view(pv_base_output_new_forex_borrowing_gross_usd, rows=('IMF',), cols=span(data.TIME_PERIOD_AXIS, 2024, time_period))))
        elif instrument == 'IDA - SML' and 2026 <= time_period <= 2051:
            return as_measure(xl_sum(view(pv_base_output_new_forex_borrowing_gross_usd, rows=('IDA - SML',), cols=span(data.TIME_PERIOD_AXIS, 2024, time_period))))
        elif instrument == 'MULTI1' and 2026 <= time_period <= 2051:
            return as_measure(xl_sum(view(pv_base_output_new_forex_borrowing_gross_usd, rows=('MULTI1',), cols=span(data.TIME_PERIOD_AXIS, 2024, time_period))))
        elif instrument == 'MULTI2' and 2026 <= time_period <= 2051:
            return as_measure(xl_sum(view(pv_base_output_new_forex_borrowing_gross_usd, rows=('MULTI2',), cols=span(data.TIME_PERIOD_AXIS, 2024, time_period))))
        elif instrument == 'OTH_MULTI1' and 2026 <= time_period <= 2051:
            return as_measure(xl_sum(view(pv_base_output_new_forex_borrowing_gross_usd, rows=('OTH_MULTI1',), cols=span(data.TIME_PERIOD_AXIS, 2024, time_period))))
        elif instrument == 'OTH_MULTI2' and 2026 <= time_period <= 2051:
            return as_measure(xl_sum(view(pv_base_output_new_forex_borrowing_gross_usd, rows=('OTH_MULTI2',), cols=span(data.TIME_PERIOD_AXIS, 2024, time_period))))
        elif instrument == 'OTH_MULTI3' and 2026 <= time_period <= 2051:
            return as_measure(xl_sum(view(pv_base_output_new_forex_borrowing_gross_usd, rows=('OTH_MULTI3',), cols=span(data.TIME_PERIOD_AXIS, 2024, time_period))))
        elif instrument == 'Export Credit Agencies' and 2026 <= time_period <= 2051:
            return as_measure(xl_sum(view(pv_base_output_new_forex_borrowing_gross_usd, rows=('Export Credit Agencies',), cols=span(data.TIME_PERIOD_AXIS, 2024, time_period))))
        elif instrument == 'PC2' and 2026 <= time_period <= 2051:
            return as_measure(xl_sum(view(pv_base_output_new_forex_borrowing_gross_usd, rows=('PC2',), cols=span(data.TIME_PERIOD_AXIS, 2024, time_period))))
        elif instrument == 'PC3' and 2026 <= time_period <= 2051:
            return as_measure(xl_sum(view(pv_base_output_new_forex_borrowing_gross_usd, rows=('PC3',), cols=span(data.TIME_PERIOD_AXIS, 2024, time_period))))
        elif instrument == 'PC4' and 2026 <= time_period <= 2051:
            return as_measure(xl_sum(view(pv_base_output_new_forex_borrowing_gross_usd, rows=('PC4',), cols=span(data.TIME_PERIOD_AXIS, 2024, time_period))))
        elif instrument == 'PC5' and 2026 <= time_period <= 2051:
            return as_measure(xl_sum(view(pv_base_output_new_forex_borrowing_gross_usd, rows=('PC5',), cols=span(data.TIME_PERIOD_AXIS, 2024, time_period))))
        elif instrument == 'Export Import Bank of NPC' and 2026 <= time_period <= 2051:
            return as_measure(xl_sum(view(pv_base_output_new_forex_borrowing_gross_usd, rows=('Export Import Bank of NPC',), cols=span(data.TIME_PERIOD_AXIS, 2024, time_period))))
        elif instrument == 'NPC2' and 2026 <= time_period <= 2051:
            return as_measure(xl_sum(view(pv_base_output_new_forex_borrowing_gross_usd, rows=('NPC2',), cols=span(data.TIME_PERIOD_AXIS, 2024, time_period))))
        elif instrument == 'NPC3' and 2026 <= time_period <= 2051:
            return as_measure(xl_sum(view(pv_base_output_new_forex_borrowing_gross_usd, rows=('NPC3',), cols=span(data.TIME_PERIOD_AXIS, 2024, time_period))))
        elif instrument == 'NPC4' and 2026 <= time_period <= 2051:
            return as_measure(xl_sum(view(pv_base_output_new_forex_borrowing_gross_usd, rows=('NPC4',), cols=span(data.TIME_PERIOD_AXIS, 2024, time_period))))
        elif instrument == 'NPC5' and 2026 <= time_period <= 2051:
            return as_measure(xl_sum(view(pv_base_output_new_forex_borrowing_gross_usd, rows=('NPC5',), cols=span(data.TIME_PERIOD_AXIS, 2024, time_period))))
        elif instrument == 'Eurobond' and 2026 <= time_period <= 2051:
            return as_measure(xl_sum(view(pv_base_output_new_forex_borrowing_gross_usd, rows=('Eurobond',), cols=span(data.TIME_PERIOD_AXIS, 2024, time_period))))
        elif instrument == 'Commecial Bank' and 2026 <= time_period <= 2051:
            return as_measure(xl_sum(view(pv_base_output_new_forex_borrowing_gross_usd, rows=('Commecial Bank',), cols=span(data.TIME_PERIOD_AXIS, 2024, time_period))))
        elif instrument == 'COM3' and 2026 <= time_period <= 2051:
            return as_measure(xl_sum(view(pv_base_output_new_forex_borrowing_gross_usd, rows=('COM3',), cols=span(data.TIME_PERIOD_AXIS, 2024, time_period))))
        elif instrument == 'COM4' and 2026 <= time_period <= 2051:
            return as_measure(xl_sum(view(pv_base_output_new_forex_borrowing_gross_usd, rows=('COM4',), cols=span(data.TIME_PERIOD_AXIS, 2024, time_period))))
        elif instrument == 'COM5' and 2026 <= time_period <= 2051:
            return as_measure(xl_sum(view(pv_base_output_new_forex_borrowing_gross_usd, rows=('COM5',), cols=span(data.TIME_PERIOD_AXIS, 2024, time_period))))
        elif time_period == 2024:
            return as_measure(pv_base_output_new_forex_borrowing_gross_usd[instrument, time_period])
        elif instrument == 'IDA NEW Regular' and 2026 <= time_period <= 2058:
            return as_measure(xl_sum(view(pv_base_output_new_forex_borrowing_gross_usd, rows=('IDA NEW Regular',), cols=span(data.TIME_PERIOD_AXIS, 2024, time_period))))
        elif instrument == 'IDA - regular' and 2026 <= time_period <= 2062:
            return as_measure(xl_sum(view(pv_base_output_new_forex_borrowing_gross_usd, rows=('IDA - regular',), cols=span(data.TIME_PERIOD_AXIS, 2024, time_period))))
        elif instrument == 'IDA NEW 40-year credits' and 2026 <= time_period <= 2064:
            return as_measure(xl_sum(view(pv_base_output_new_forex_borrowing_gross_usd, rows=('IDA NEW 40-year credits',), cols=span(data.TIME_PERIOD_AXIS, 2024, time_period))))
        elif instrument == 'IDA - 50Y loans' and 2026 <= time_period <= 2074:
            return as_measure(xl_sum(view(pv_base_output_new_forex_borrowing_gross_usd, rows=('IDA - 50Y loans',), cols=span(data.TIME_PERIOD_AXIS, 2024, time_period))))
        return as_measure(xl_sum(view(pv_base_output_new_forex_borrowing_gross_usd, rows=('IDA NEW 60-year credits',), cols=span(data.TIME_PERIOD_AXIS, 2024, time_period))))

    return data.PV_BASE_OUTPUT_CUMULATIVE.collect(evaluate(formula, data.PV_BASE_OUTPUT_CUMULATIVE.required))

@publish(data.PV_BASE_OUTPUT_STOCK_OF_NEW_FOREX_DEBT_IN_USD.schema, cells=data.PV_BASE_OUTPUT_STOCK_OF_NEW_FOREX_DEBT_IN_USD.cells)
def pv_base_output_stock_of_new_forex_debt_in_usd(*, pv_base_output_new_forex_borrowing_gross_usd: data.Series[float | str | None], pv_base_output_amortization: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute the per-instrument stock of new forex debt in USD on the pv_base output grid.

    Rolls each instrument's prior-period stock forward by adding gross new forex borrowing and subtracting amortization, over the projection years on the catalog's instrument-by-time-period coordinates.

    Args:
        pv_base_output_new_forex_borrowing_gross_usd: Gross new forex borrowing in USD as a named-axis data.Series over the instrument and time-period coordinates, supplying the flow added to the prior-period stock.
        pv_base_output_amortization: Amortization as a named-axis data.Series over the same instrument and time-period coordinates, supplying the flow subtracted from the prior-period stock.

    Returns:
        A data.Series[float | str | None] of the stock of new forex debt in USD indexed by instrument and time period.
    """
    def formula(instrument: str, time_period: int) -> float | str | None:
        if instrument == 'IMF' and time_period >= 2026:
            return as_measure(xl_sub(xl_add(pv_base_output_stock_of_new_forex_debt_in_usd['IMF', time_period - 1], pv_base_output_new_forex_borrowing_gross_usd['IMF', time_period]), pv_base_output_amortization['IMF', time_period]))
        elif instrument == 'IDA - regular' and time_period >= 2026:
            return as_measure(xl_sub(xl_add(pv_base_output_stock_of_new_forex_debt_in_usd['IDA - regular', time_period - 1], pv_base_output_new_forex_borrowing_gross_usd['IDA - regular', time_period]), pv_base_output_amortization['IDA - regular', time_period]))
        elif instrument == 'IDA - 50Y loans' and time_period >= 2026:
            return as_measure(xl_sub(xl_add(pv_base_output_stock_of_new_forex_debt_in_usd['IDA - 50Y loans', time_period - 1], pv_base_output_new_forex_borrowing_gross_usd['IDA - 50Y loans', time_period]), pv_base_output_amortization['IDA - 50Y loans', time_period]))
        elif instrument == 'IDA - SML' and time_period >= 2026:
            return as_measure(xl_sub(xl_add(pv_base_output_stock_of_new_forex_debt_in_usd['IDA - SML', time_period - 1], pv_base_output_new_forex_borrowing_gross_usd['IDA - SML', time_period]), pv_base_output_amortization['IDA - SML', time_period]))
        elif instrument == 'IDA NEW 40-year credits' and time_period >= 2026:
            return as_measure(xl_sub(xl_add(pv_base_output_stock_of_new_forex_debt_in_usd['IDA NEW 40-year credits', time_period - 1], pv_base_output_new_forex_borrowing_gross_usd['IDA NEW 40-year credits', time_period]), pv_base_output_amortization['IDA NEW 40-year credits', time_period]))
        elif instrument == 'IDA NEW Regular' and time_period >= 2026:
            return as_measure(xl_sub(xl_add(pv_base_output_stock_of_new_forex_debt_in_usd['IDA NEW Regular', time_period - 1], pv_base_output_new_forex_borrowing_gross_usd['IDA NEW Regular', time_period]), pv_base_output_amortization['IDA NEW Regular', time_period]))
        elif instrument == 'IDA NEW Blend floating' and time_period >= 2026:
            return as_measure(xl_sub(xl_add(pv_base_output_stock_of_new_forex_debt_in_usd['IDA NEW Blend floating', time_period - 1], pv_base_output_new_forex_borrowing_gross_usd['IDA NEW Blend floating', time_period]), pv_base_output_amortization['IDA NEW Blend floating', time_period]))
        elif instrument == 'IDA NEW 60-year credits' and time_period >= 2026:
            return as_measure(xl_sub(xl_add(pv_base_output_stock_of_new_forex_debt_in_usd['IDA NEW 60-year credits', time_period - 1], pv_base_output_new_forex_borrowing_gross_usd['IDA NEW 60-year credits', time_period]), pv_base_output_amortization['IDA NEW 60-year credits', time_period]))
        elif instrument == 'MULTI1' and time_period >= 2026:
            return as_measure(xl_sub(xl_add(pv_base_output_stock_of_new_forex_debt_in_usd['MULTI1', time_period - 1], pv_base_output_new_forex_borrowing_gross_usd['MULTI1', time_period]), pv_base_output_amortization['MULTI1', time_period]))
        elif instrument == 'MULTI2' and time_period >= 2026:
            return as_measure(xl_sub(xl_add(pv_base_output_stock_of_new_forex_debt_in_usd['MULTI2', time_period - 1], pv_base_output_new_forex_borrowing_gross_usd['MULTI2', time_period]), pv_base_output_amortization['MULTI2', time_period]))
        elif instrument == 'OTH_MULTI1' and time_period >= 2026:
            return as_measure(xl_sub(xl_add(pv_base_output_stock_of_new_forex_debt_in_usd['OTH_MULTI1', time_period - 1], pv_base_output_new_forex_borrowing_gross_usd['OTH_MULTI1', time_period]), pv_base_output_amortization['OTH_MULTI1', time_period]))
        elif instrument == 'OTH_MULTI2' and time_period >= 2026:
            return as_measure(xl_sub(xl_add(pv_base_output_stock_of_new_forex_debt_in_usd['OTH_MULTI2', time_period - 1], pv_base_output_new_forex_borrowing_gross_usd['OTH_MULTI2', time_period]), pv_base_output_amortization['OTH_MULTI2', time_period]))
        elif instrument == 'OTH_MULTI3' and time_period >= 2026:
            return as_measure(xl_sub(xl_add(pv_base_output_stock_of_new_forex_debt_in_usd['OTH_MULTI3', time_period - 1], pv_base_output_new_forex_borrowing_gross_usd['OTH_MULTI3', time_period]), pv_base_output_amortization['OTH_MULTI3', time_period]))
