            return as_measure(xl_sub(xl_add(pv_base_output_stock_of_new_forex_debt_in_usd['COM4', time_period - 1], pv_base_output_new_forex_borrowing_gross_usd['COM4', time_period]), pv_base_output_amortization['COM4', time_period]))
