@publish(data.PV_BASE_INSTRUMENT_TITLE.schema, cells=data.PV_BASE_INSTRUMENT_TITLE.cells)
def pv_base_instrument_title(*, input4_instrument_names: data.Input4InstrumentNames) -> data.Series[str | int | float | bool | None]:
    """Return the PV_Base instrument title for each IDA instrument.

    Resolves the instrument-title identity used by the PV_Base calculations for every catalogued IDA instrument.

    Args:
        input4_instrument_names: Keyword-only data.Input4InstrumentNames series over catalog coordinates, supplying the IDA instrument names that select the corresponding instrument-title identity.

    Returns:
        data.Series[str | int | float | bool | None] indexed over the instrument axis, holding the instrument_title string for each of the five IDA instruments (IDA - 50Y loans, IDA - regular, IDA NEW 40-year credits, IDA NEW 60-year credits, IDA NEW Regular), propagated from the internal instrument_title series.
    """
    data.INPUT4_INSTRUMENT_NAMES.schema.validate(input4_instrument_names)
    def formula(instrument: str) -> str | int | float | bool | None:
        return as_measure(input4_instrument_names[instrument], 'str')

    return data.PV_BASE_INSTRUMENT_TITLE.collect(evaluate(formula, data.PV_BASE_INSTRUMENT_TITLE.required))

@publish(data.PV_BASE_DISCOUNT_SCHEDULE_PERIOD.schema, cells=data.PV_BASE_DISCOUNT_SCHEDULE_PERIOD.cells)
def pv_base_discount_schedule_period(*, pv_base_constant_discount_schedule_period: int | str) -> data.Series[int | str | None]:
    """Build the pv_base.discount_schedule period series, seeding 2025 from the scalar base constant period and incrementing prior-period values for later years.

    Compute the Schedule period series for IDA - regular instruments on pv_base.discount_schedule.

    Args:
        pv_base_constant_discount_schedule_period: Scalar base constant discount-schedule period (int or str) used to seed the 2025 period.

    Returns:
        A typed data.Series of int | str | None over catalog coordinates on pv_base.discount_schedule for IDA - regular, giving each coordinate's discount-schedule period.
    """
    def formula(instrument: str, time_period: int) -> int | str | None:
        if time_period == 2025:
            return as_measure(xl_add(pv_base_constant_discount_schedule_period, 1), 'int')
        return as_measure(xl_add(pv_base_discount_schedule_period['IDA - regular', time_period - 1], 1), 'int')

    pv_base_discount_schedule_period = CoordinateReader('pv_base_discount_schedule_period', data.PV_BASE_DISCOUNT_SCHEDULE_PERIOD.required, formula)
    return data.PV_BASE_DISCOUNT_SCHEDULE_PERIOD.collect((coord, pv_base_discount_schedule_period[coord]) for coord in data.PV_BASE_DISCOUNT_SCHEDULE_PERIOD.required)

@publish(data.PV_BASE_DISCOUNT_SELECTED_INSTRUMENT.schema, cells=data.PV_BASE_DISCOUNT_SELECTED_INSTRUMENT.cells)
def pv_base_discount_selected_instrument(*, input4_blend_scale_key: data.Input4BlendScaleKey, input4_ida_scale_name: data.Series[str | None], pv_base_instrument_title: data.Series[str | int | float | bool | None]) -> data.Series[str | int | float | bool | None]:
    """Selects the PV base discount instrument series from pv_base.discount_schedule.

    Resolves the active discount instrument by replacing blend-marked instrument titles with their corresponding blend scale keys.

    Args:
        input4_blend_scale_key: Typed data.Input4BlendScaleKey series mapping instrument names to blend-scale keys for use when an instrument title matches the IDA blend sentinel.
        input4_ida_scale_name: data.Series of IDA scale names (str | None), including the 'IDA NEW Blend (also enter) -->' sentinel used to detect blend instruments.
        pv_base_instrument_title: data.Series of instrument titles (str | int | float | bool | None) from pv_base.discount_schedule, covering the 'IDA - 50Y loans' and 'IDA - regular' instruments.

    Returns:
        data.Series of the selected discount instrument title (str | int | float | bool | None), where blend-marked titles are replaced by the corresponding blend scale key (with 'IDA - regular' mapped to 'IDA NEW Regular'), otherwise the original instrument title.
    """
    data.INPUT4_BLEND_SCALE_KEY.schema.validate(input4_blend_scale_key)
    data.INPUT4_IDA_SCALE_NAME.schema.validate(input4_ida_scale_name)
    def formula(instrument: str) -> str | int | float | bool | None:
        if instrument == 'IDA - regular':
            return as_measure((input4_blend_scale_key['IDA NEW Regular'] if xl_bool(xl_eq(pv_base_instrument_title[instrument], input4_ida_scale_name['IDA NEW Blend (also enter) -->'])) else pv_base_instrument_title[instrument]), 'str')
        return as_measure((input4_blend_scale_key[instrument] if xl_bool(xl_eq(pv_base_instrument_title[instrument], input4_ida_scale_name['IDA NEW Blend (also enter) -->'])) else pv_base_instrument_title[instrument]), 'str')

    return data.PV_BASE_DISCOUNT_SELECTED_INSTRUMENT.collect(evaluate(formula, data.PV_BASE_DISCOUNT_SELECTED_INSTRUMENT.required))

@publish(data.PV_BASE_BLOCK_INDEX.schema, cells=data.PV_BASE_BLOCK_INDEX.cells)
def pv_base_block_index(*, pv_base_constant_discount_schedule_period: int | str, pv_base_discount_schedule_period: data.Series[int | str | None]) -> data.Series[int | str | None]:
    """Resolve PV_BASE_BLOCK_INDEX block indices by instrument and time period from discount schedule periods.

    Supports the PV base block lookup by applying authored instrument identities, base-year handling, and an IDA regular fallback.

    Args:
        pv_base_constant_discount_schedule_period: Scalar int or str period identifier in the constant discount schedule, used as the block index for the base-year entries of the directly mapped instruments.
        pv_base_discount_schedule_period: Named-axis data.Series[int | str | None] over catalog coordinates providing discount schedule periods, including the IDA regular period used as the fallback for instruments not covered by the constant or forward-mapped identities.

    Returns:
        A data.Series[int | str | None] over PV_BASE_BLOCK_INDEX catalog coordinates giving the resolved block index for each instrument and time-period coordinate.
    """
    def formula(instrument: str, time_period: int) -> int | str | None:
        INSTRUMENT_TO_PV_BASE_BLOCK_INDEX = {'IDA - SML': 'IDA - 50Y loans', 'IDA NEW 40-year credits': 'IDA - SML', 'IDA NEW Regular': 'IDA NEW 40-year credits', 'IDA NEW Blend floating': 'IDA NEW Regular'}
        if instrument in ('IDA - 50Y loans', 'IDA NEW 60-year credits', 'MULTI1', 'MULTI2', 'OTH_MULTI1', 'OTH_MULTI2', 'OTH_MULTI3', 'Export Credit Agencies', 'PC2', 'PC3', 'PC4', 'PC5', 'Export Import Bank of NPC', 'NPC2', 'NPC3', 'NPC4', 'NPC5', 'Eurobond', 'Commecial Bank', 'COM3', 'COM4', 'COM5') and time_period == 2024:
            return as_measure(pv_base_constant_discount_schedule_period, 'int')
        elif instrument in ('IDA - SML', 'IDA NEW 40-year credits', 'IDA NEW Regular', 'IDA NEW Blend floating') and time_period in (2024, 2025, 2026, 2027, 2028, 2029, 2030, 2031, 2032, 2033, 2034, 2035, 2036, 2037, 2038, 2039, 2040, 2041, 2042, 2043, 2044, 2045, 2046, 2047, 2048, 2049, 2050, 2051, 2052, 2053, 2054, 2055, 2056, 2057, 2058, 2059, 2060, 2061, 2062, 2063, 2064, 2065, 2066, 2067, 2068, 2069, 2070, 2071, 2072, 2073, 2074):
            return as_measure(pv_base_block_index[INSTRUMENT_TO_PV_BASE_BLOCK_INDEX[instrument], time_period], 'int')
        return as_measure(pv_base_discount_schedule_period['IDA - regular', time_period], 'int')

    pv_base_block_index = CoordinateReader('pv_base_block_index', data.PV_BASE_BLOCK_INDEX.required, formula)
    return data.PV_BASE_BLOCK_INDEX.collect((coord, pv_base_block_index[coord]) for coord in data.PV_BASE_BLOCK_INDEX.required)

@publish(data.PV_BASE_BLOCK_INDEX_FX.schema, cells=data.PV_BASE_BLOCK_INDEX_FX.cells)
def pv_base_block_index_fx(*, pv_base_constant_discount_schedule_period: int | str, pv_base_discount_schedule_period: data.Series[int | str | None]) -> data.Series[int | str | None]:
    """Compute the FX block index for PV-base discount-schedule periods.

    Resolve the block-index coordinates used by the PV base FX schedule, applying a scalar period value for 2024 and the IDA-regular discount-schedule period otherwise.

    Args:
        pv_base_constant_discount_schedule_period: Keyword-only scalar supplying the discount-schedule period value for the 2024 time period.
        pv_base_discount_schedule_period: Keyword-only named-axis tensor series over catalog coordinates carrying discount-schedule period values as integers, strings, or missing values, read at the IDA-regular instrument for non-2024 time periods.

    Returns:
        Named-axis tensor series over the FX block-index catalog coordinates with integer, string, or missing values; it mirrors the six internal block-index series spanning three bond instruments and non-resident/resident holders, with time-period values sourced from the scalar for 2024 and from the discount-schedule series otherwise.
    """
    def formula(instrument: str, holder: str, time_period: int) -> int | str | None:
        if time_period == 2024:
            return as_measure(pv_base_constant_discount_schedule_period, 'int')
        return as_measure(pv_base_discount_schedule_period['IDA - regular', time_period], 'int')

    return data.PV_BASE_BLOCK_INDEX_FX.collect(evaluate(formula, data.PV_BASE_BLOCK_INDEX_FX.required))

