@publish(data.PV_BASE_ADD_COST_MKT_DISCOUNT_POST_MATURITY_CUMULATIVE.schema, cells=data.PV_BASE_ADD_COST_MKT_DISCOUNT_POST_MATURITY_CUMULATIVE.cells)
def pv_base_add_cost_mkt_discount_post_maturity_cumulative(*, pv_base_add_cost_mkt_discount_t_m_condition: data.Series[int | str | None], pv_base_add_cost_mkt_output_cumulative: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute post-maturity cumulative market-discount add-costs by instrument and time period.

    Derives each instrument's cumulative post-maturity discount values over 2024–2051, zeroing periods where the maturity condition is zero and otherwise selecting from the cumulative output series.

    Args:
        pv_base_add_cost_mkt_discount_t_m_condition: A data.Series[int | str | None] over instrument and time-period coordinates; zero entries force the corresponding post-maturity cumulative discount to zero, while nonzero values act as selectors into the cumulative output series.
        pv_base_add_cost_mkt_output_cumulative: A data.Series[float | str | None] of cumulative market-discount output values by instrument and time period, viewed over the 2024–2051 time span and used as the source for condition-driven selection.

    Returns:
        A data.Series[float | str | None] of post-maturity cumulative market-discount add-costs aligned to the result coordinates, containing zero where the condition is zero and otherwise values selected from the cumulative output series.
    """
    _pv_base_add_cost_mkt_discount_post_maturity_cumulative_table_0 = view(pv_base_add_cost_mkt_output_cumulative, rows=('Eurobond',), cols=span(data.TIME_PERIOD_AXIS, 2024, 2051))
    _pv_base_add_cost_mkt_discount_post_maturity_cumulative_table_1 = view(pv_base_add_cost_mkt_output_cumulative, rows=('Commecial Bank',), cols=span(data.TIME_PERIOD_AXIS, 2024, 2051))
    _pv_base_add_cost_mkt_discount_post_maturity_cumulative_table_2 = view(pv_base_add_cost_mkt_output_cumulative, rows=('COM3',), cols=span(data.TIME_PERIOD_AXIS, 2024, 2051))
    _pv_base_add_cost_mkt_discount_post_maturity_cumulative_table_3 = view(pv_base_add_cost_mkt_output_cumulative, rows=('COM4',), cols=span(data.TIME_PERIOD_AXIS, 2024, 2051))
    _pv_base_add_cost_mkt_discount_post_maturity_cumulative_table_4 = view(pv_base_add_cost_mkt_output_cumulative, rows=('COM5',), cols=span(data.TIME_PERIOD_AXIS, 2024, 2051))
    def formula(instrument: str, time_period: int) -> float | str | None:
        if instrument == 'Eurobond':
            return as_measure((0 if xl_bool(xl_eq(pv_base_add_cost_mkt_discount_t_m_condition['Eurobond', time_period], 0)) else xl_choose_range(pv_base_add_cost_mkt_discount_t_m_condition['Eurobond', time_period], _pv_base_add_cost_mkt_discount_post_maturity_cumulative_table_0)))
        elif instrument == 'Commecial Bank':
            return as_measure((0 if xl_bool(xl_eq(pv_base_add_cost_mkt_discount_t_m_condition['Commecial Bank', time_period], 0)) else xl_choose_range(pv_base_add_cost_mkt_discount_t_m_condition['Commecial Bank', time_period], _pv_base_add_cost_mkt_discount_post_maturity_cumulative_table_1)))
        elif instrument == 'COM3':
            return as_measure((0 if xl_bool(xl_eq(pv_base_add_cost_mkt_discount_t_m_condition['COM3', time_period], 0)) else xl_choose_range(pv_base_add_cost_mkt_discount_t_m_condition['COM3', time_period], _pv_base_add_cost_mkt_discount_post_maturity_cumulative_table_2)))
        elif instrument == 'COM4':
            return as_measure((0 if xl_bool(xl_eq(pv_base_add_cost_mkt_discount_t_m_condition['COM4', time_period], 0)) else xl_choose_range(pv_base_add_cost_mkt_discount_t_m_condition['COM4', time_period], _pv_base_add_cost_mkt_discount_post_maturity_cumulative_table_3)))
        return as_measure((0 if xl_bool(xl_eq(pv_base_add_cost_mkt_discount_t_m_condition['COM5', time_period], 0)) else xl_choose_range(pv_base_add_cost_mkt_discount_t_m_condition['COM5', time_period], _pv_base_add_cost_mkt_discount_post_maturity_cumulative_table_4)))

    return data.PV_BASE_ADD_COST_MKT_DISCOUNT_POST_MATURITY_CUMULATIVE.collect(evaluate(formula, data.PV_BASE_ADD_COST_MKT_DISCOUNT_POST_MATURITY_CUMULATIVE.required))

@publish(data.PV_BASE_ADD_COST_MKT_OUTPUT_NEW_FOREX_BORROWING_GROSS_USD.schema, cells=data.PV_BASE_ADD_COST_MKT_OUTPUT_NEW_FOREX_BORROWING_GROSS_USD.cells)
def pv_base_add_cost_mkt_output_new_forex_borrowing_gross_usd(*, ext_debt_new_disbursements_external: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Derive the PV_Base-add-cost market-output series for new forex borrowing (gross, USD) from external new disbursements.

    Maps each of the five external-debt instruments (Eurobond, Commercial Bank, COM3, COM4, COM5) onto its corresponding new forex borrowing gross USD value, preserving catalog coordinates over time periods.

    Args:
        ext_debt_new_disbursements_external: Keyword-only data.Series[float | str | None] of new external debt disbursements indexed by instrument and time period.

    Returns:
        data.Series[float | str | None] of new forex borrowing (gross, USD) over the same instrument and time-period coordinates.
    """
    def formula(instrument: str, time_period: int) -> float | str | None:
        if instrument == 'Eurobond':
            return as_measure(ext_debt_new_disbursements_external['Eurobond', time_period])
        elif instrument == 'Commecial Bank':
            return as_measure(ext_debt_new_disbursements_external['Commecial Bank', time_period])
        elif instrument == 'COM3':
            return as_measure(ext_debt_new_disbursements_external['COM3', time_period])
        elif instrument == 'COM4':
            return as_measure(ext_debt_new_disbursements_external['COM4', time_period])
        return as_measure(ext_debt_new_disbursements_external['COM5', time_period])

    return data.PV_BASE_ADD_COST_MKT_OUTPUT_NEW_FOREX_BORROWING_GROSS_USD.collect(evaluate(formula, data.PV_BASE_ADD_COST_MKT_OUTPUT_NEW_FOREX_BORROWING_GROSS_USD.required))

