@publish(data.PV_LC_OUTPUT_STOCK_OF_DEBT_IN_USD.schema, cells=data.PV_LC_OUTPUT_STOCK_OF_DEBT_IN_USD.cells)
def pv_lc_output_stock_of_debt_in_usd(*, pv_lc_nr1_terms_fx_eop: data.Series[float | str | None], pv_lc_output_stock_of_debt_in_lc: data.Series[float | str | None], pv_lc_terms_fx_eop: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Convert PV_LC local-currency debt stocks to USD using instrument-specific end-of-period FX rates.

    Produce the PV_LC stock of debt in USD for LIC-DSF IDA21 outputs by applying the appropriate NR1 or terms FX rate to each local-currency balance.

    Args:
        pv_lc_nr1_terms_fx_eop: Named-axis data series of end-of-period FX rates for the PV_LC_NR1 terms grouping, applied to 1–3 year local-currency bonds.
        pv_lc_output_stock_of_debt_in_lc: Named-axis data series of local-currency stock of debt on PV_LC, keyed by instrument, holder, issuance year, and time period.
        pv_lc_terms_fx_eop: Named-axis data series of end-of-period FX rates for the PV_LC terms grouping, applied to 4–7 year and beyond-7-year local-currency bonds.

    Returns:
        Named-axis data series of the USD stock of debt on PV_LC, keyed by INSTRUMENT across PV_LC_NR1, PV_LC_NR2, and PV_LC_NR3; values are 0 when the local-currency balance is 0, otherwise the local-currency balance divided by the applicable end-of-period FX rate.
    """
    def formula(instrument: str, holder: str, issuance_year: int, time_period: int) -> float | str | None:
        if instrument == 'Bonds (1 to 3 years)-LC' and issuance_year == 2024:
            return as_measure((0 if xl_bool(xl_eq(pv_lc_output_stock_of_debt_in_lc[instrument, holder, 2024, time_period], 0)) else xl_div(pv_lc_output_stock_of_debt_in_lc[instrument, holder, 2024, time_period], pv_lc_nr1_terms_fx_eop[instrument, holder, time_period])))
        elif instrument == 'Bonds (1 to 3 years)-LC' and issuance_year == 2025:
            return as_measure((0 if xl_bool(xl_eq(pv_lc_output_stock_of_debt_in_lc[instrument, holder, 2025, time_period], 0)) else xl_div(pv_lc_output_stock_of_debt_in_lc[instrument, holder, 2025, time_period], pv_lc_nr1_terms_fx_eop[instrument, holder, time_period])))
