@publish(data.PV_RESFIN_PUB_ASSUMPTIONS_AVG_INTEREST_RATE.schema, cells=data.PV_RESFIN_PUB_ASSUMPTIONS_AVG_INTEREST_RATE.cells)
def pv_resfin_pub_assumptions_avg_interest_rate(*, pv_resfin_pub_assumptions_inflation_gdp_deflator: data.Series[float | str | None], pv_resfin_pub_avg_real_interest_rate: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute the average nominal interest rate on domestic short-term public debt.

    Combines the average real interest rate with the inflation GDP deflator to produce the public residual-financing assumption series.

    Args:
        pv_resfin_pub_assumptions_inflation_gdp_deflator: Inflation GDP deflator as a data.Series[float | str | None] over catalog coordinates, indexed by time period.
        pv_resfin_pub_avg_real_interest_rate: Average real interest rate for the domestic short-term instrument as a data.Series[float | str | None] over catalog coordinates, indexed by time period.

    Returns:
        Average interest rate as a data.Series[float | str | None] over catalog coordinates, indexed by instrument and time period.
    """
