@publish(data.PV_RESFIN_PUB_AVG_REAL_INTEREST_RATE.schema, cells=data.PV_RESFIN_PUB_AVG_REAL_INTEREST_RATE.cells)
def pv_resfin_pub_avg_real_interest_rate(*, pv_resfin_pub_assumptions_avg_real_interest_rate: float | str) -> data.Series[float | str | None]:
    """Return the public residual-financing average real interest rate series.

    Construct the `pv_resfin_pub_avg_real_interest_rate` series by seeding 2025 with the supplied assumption and carrying the Domestic short-term value across projection periods.

    Args:
        pv_resfin_pub_assumptions_avg_real_interest_rate: Average real interest rate assumption for 2025, supplied as a scalar float or string label.

    Returns:
        A `data.Series[float | str | None]` over the public residual-financing average real interest rate coordinate grid, indexed by the Domestic short-term instrument and time period, with 2025 taken from the assumption and later periods propagated from the preceding period.
    """
    def formula(instrument: str, time_period: int) -> float | str | None:
        if time_period == 2025:
            return as_measure(pv_resfin_pub_assumptions_avg_real_interest_rate)
        return as_measure(pv_resfin_pub_avg_real_interest_rate['Domestic short-term', time_period - 1])

    pv_resfin_pub_avg_real_interest_rate = CoordinateReader('pv_resfin_pub_avg_real_interest_rate', data.PV_RESFIN_PUB_AVG_REAL_INTEREST_RATE.required, formula)
    return data.PV_RESFIN_PUB_AVG_REAL_INTEREST_RATE.collect((coord, pv_resfin_pub_avg_real_interest_rate[coord]) for coord in data.PV_RESFIN_PUB_AVG_REAL_INTEREST_RATE.required)

@publish(data.PV_RESFIN_PUB_ASSUMPTIONS_INFLATION_GDP_DEFLATOR.schema, cells=data.PV_RESFIN_PUB_ASSUMPTIONS_INFLATION_GDP_DEFLATOR.cells)
def pv_resfin_pub_assumptions_inflation_gdp_deflator(*, macro_debt_change_in_gdp_deflator_factor: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Scale the Macro-Debt GDP-deflator change factor into the PV_ResFin_pub inflation assumption series.

    Populate the public residual-financing inflation (GDP deflator) assumption for each projection year by dividing the named-axis change factor by 100.

    Args:
        macro_debt_change_in_gdp_deflator_factor: Inflation (GDP deflator) change factor (in percentage points) from the Macro-Debt data, as a float, string, or null per projection year.

    Returns:
        A data.Series keyed by projection years (from row 2) giving the inflation (GDP deflator) assumption for PV_ResFin_pub, with each year's factor divided by 100; entries are floats, strings, or null.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure(xl_div(macro_debt_change_in_gdp_deflator_factor[time_period], 100))

    return data.PV_RESFIN_PUB_ASSUMPTIONS_INFLATION_GDP_DEFLATOR.collect(evaluate(formula, data.PV_RESFIN_PUB_ASSUMPTIONS_INFLATION_GDP_DEFLATOR.required))

@publish(data.PV_RESFIN_PUB_ASSUMPTIONS_AVERAGE_INTEREST_RATE_ON_DOMESTIC_DEBT.schema, cells=data.PV_RESFIN_PUB_ASSUMPTIONS_AVERAGE_INTEREST_RATE_ON_DOMESTIC_DEBT.cells)
def pv_resfin_pub_assumptions_average_interest_rate_on_domestic_debt(*, pv_resfin_pub_assumptions_share_of_marginal_debt: data.Series[float | str | None], pv_resfin_pub_assumptions_domestic_mlt_debt: data.Series[float | str | None], pv_resfin_pub_assumptions_avg_interest_rate: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Blend domestic medium-and-long-term debt and short-term interest rates into the average interest rate on domestic debt.

    Compute the PV_ResFin_pub assumption for the average interest rate on domestic debt from shares of marginal debt.

    Args:
        pv_resfin_pub_assumptions_share_of_marginal_debt: Named-axis data.Series of the shares of marginal (new) domestic debt allocated to each instrument category, keyed by domestic-debt instrument and projection year; the domestic medium-and-long-term and short-term entries act as weights.
        pv_resfin_pub_assumptions_domestic_mlt_debt: Named-axis data.Series of domestic medium-and-long-term debt levels keyed by domestic-debt instrument and projection year, supplying the medium-and-long-term level used in the weighted average and as the fallback when total marginal-debt share is zero.
        pv_resfin_pub_assumptions_avg_interest_rate: Named-axis data.Series of the average interest rate on domestic short-term debt keyed by domestic-debt instrument and projection year, contributing the short-term term of the weighted average.

    Returns:
        data.Series of the average interest rate on domestic debt keyed by projection years, with float rates or str/None placeholders where the underlying cells are blank.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure((pv_resfin_pub_assumptions_domestic_mlt_debt['Domestic medium and long-term', time_period] if xl_bool(xl_eq(xl_add(pv_resfin_pub_assumptions_share_of_marginal_debt['Domestic medium and long-term'], pv_resfin_pub_assumptions_share_of_marginal_debt['Domestic short-term']), 0)) else xl_add(xl_div(xl_mul(pv_resfin_pub_assumptions_domestic_mlt_debt['Domestic medium and long-term', time_period], pv_resfin_pub_assumptions_share_of_marginal_debt['Domestic medium and long-term']), xl_add(pv_resfin_pub_assumptions_share_of_marginal_debt['Domestic medium and long-term'], pv_resfin_pub_assumptions_share_of_marginal_debt['Domestic short-term'])), xl_div(xl_mul(pv_resfin_pub_assumptions_share_of_marginal_debt['Domestic short-term'], pv_resfin_pub_assumptions_avg_interest_rate['Domestic short-term', time_period]), xl_add(pv_resfin_pub_assumptions_share_of_marginal_debt['Domestic medium and long-term'], pv_resfin_pub_assumptions_share_of_marginal_debt['Domestic short-term'])))))

    return data.PV_RESFIN_PUB_ASSUMPTIONS_AVERAGE_INTEREST_RATE_ON_DOMESTIC_DEBT.collect(evaluate(formula, data.PV_RESFIN_PUB_ASSUMPTIONS_AVERAGE_INTEREST_RATE_ON_DOMESTIC_DEBT.required))

