@publish(data.PV_BASELINE_COM_DISCOUNT_PERIOD.schema, cells=data.PV_BASELINE_COM_DISCOUNT_PERIOD.cells)
def pv_baseline_com_discount_period(*, pv_baseline_com_discount_schedule_period: int | str) -> data.Series[int | str | None]:
    """Compute the baseline commercial discount period series for the discount-schedule instruments.

    Provides the period values used by the baseline commercial discount schedule, seeded for Eurobond 2024 and incremented across projection years.

    Args:
        pv_baseline_com_discount_schedule_period: Keyword-only scalar period seed for the Eurobond 2024 discount schedule; accepts an integer or string period.

    Returns:
        A data.Series[int | str | None] over the pv_baseline_com_discount_period coordinates (instruments COM3, COM4, COM5, Commecial Bank, Eurobond across time periods), with the Eurobond path initialized from the seed and incremented by one for 2025 onward while other instruments inherit the Eurobond period at the same time period.
    """
    def formula(instrument: str, time_period: int) -> int | str | None:
        if instrument == 'Eurobond' and time_period == 2024:
            return as_measure(pv_baseline_com_discount_schedule_period, 'int')
        elif instrument == 'Eurobond' and time_period == 2025:
            return as_measure(xl_add(pv_baseline_com_discount_period[instrument, time_period - 1], 1), 'int')
        elif instrument == 'Eurobond' and time_period >= 2026:
            return as_measure(xl_add(pv_baseline_com_discount_period['Eurobond', time_period - 1], 1), 'int')
        return as_measure(pv_baseline_com_discount_period['Eurobond', time_period], 'int')

    pv_baseline_com_discount_period = CoordinateReader('pv_baseline_com_discount_period', data.PV_BASELINE_COM_DISCOUNT_PERIOD.required, formula)
    return data.PV_BASELINE_COM_DISCOUNT_PERIOD.collect((coord, pv_baseline_com_discount_period[coord]) for coord in data.PV_BASELINE_COM_DISCOUNT_PERIOD.required)

