@publish(data.PV_BASELINE_COM_DISCOUNT_DEBT_STOCK.schema, cells=data.PV_BASELINE_COM_DISCOUNT_DEBT_STOCK.cells)
def pv_baseline_com_discount_debt_stock(*, pv_baseline_com_opening_percent_of_face: data.Series[int | str | None], pv_baseline_com_discount_amortization: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Computes the baseline commercial discount debt stock by instrument and year.

    Rolls forward opening face-value balances and discount amortization into the debt stock for the PV baseline commercial discount schedule.

    Args:
        pv_baseline_com_opening_percent_of_face: Typed data series of opening percent-of-face amounts over instrument and time-period catalog coordinates, with int, string, or None entries.
        pv_baseline_com_discount_amortization: Typed data series of discount amortization amounts over instrument and time-period catalog coordinates, with float, string, or None entries.

    Returns:
        A typed data.Series containing float, string, or None debt stock values over the same instrument and time-period catalog coordinates.
    """
    data.PV_BASELINE_COM_OPENING_PERCENT_OF_FACE.schema.validate(pv_baseline_com_opening_percent_of_face)
    def formula(instrument: str, time_period: int) -> float | str | None:
        if instrument == 'Eurobond' and time_period == 2024:
            return as_measure(xl_sub(pv_baseline_com_opening_percent_of_face[instrument], pv_baseline_com_discount_amortization['Eurobond', time_period]))
        elif instrument == 'Eurobond' and time_period == 2025:
            return as_measure(xl_sub(pv_baseline_com_discount_debt_stock[instrument, time_period - 1], pv_baseline_com_discount_amortization['Eurobond', time_period]))
        elif instrument == 'Commecial Bank' and time_period == 2024:
            return as_measure(xl_sub(pv_baseline_com_opening_percent_of_face[instrument], pv_baseline_com_discount_amortization['Commecial Bank', time_period]))
        elif instrument == 'Commecial Bank' and time_period == 2025:
            return as_measure(xl_sub(pv_baseline_com_discount_debt_stock[instrument, time_period - 1], pv_baseline_com_discount_amortization['Commecial Bank', time_period]))
        elif instrument == 'COM3' and time_period == 2024:
            return as_measure(xl_sub(pv_baseline_com_opening_percent_of_face[instrument], pv_baseline_com_discount_amortization['COM3', time_period]))
        elif instrument == 'COM3' and time_period == 2025:
            return as_measure(xl_sub(pv_baseline_com_discount_debt_stock[instrument, time_period - 1], pv_baseline_com_discount_amortization['COM3', time_period]))
        elif instrument == 'COM4' and time_period == 2024:
            return as_measure(xl_sub(pv_baseline_com_opening_percent_of_face[instrument], pv_baseline_com_discount_amortization['COM4', time_period]))
        elif instrument == 'COM4' and time_period == 2025:
            return as_measure(xl_sub(pv_baseline_com_discount_debt_stock[instrument, time_period - 1], pv_baseline_com_discount_amortization['COM4', time_period]))
        elif instrument == 'COM5' and time_period == 2024:
            return as_measure(xl_sub(pv_baseline_com_opening_percent_of_face[instrument], pv_baseline_com_discount_amortization['COM5', time_period]))
        elif instrument == 'COM5' and time_period == 2025:
            return as_measure(xl_sub(pv_baseline_com_discount_debt_stock[instrument, time_period - 1], pv_baseline_com_discount_amortization['COM5', time_period]))
        elif instrument == 'Eurobond' and time_period >= 2026:
            return as_measure(xl_sub(pv_baseline_com_discount_debt_stock['Eurobond', time_period - 1], pv_baseline_com_discount_amortization['Eurobond', time_period]))
        elif instrument == 'Commecial Bank' and time_period >= 2026:
            return as_measure(xl_sub(pv_baseline_com_discount_debt_stock['Commecial Bank', time_period - 1], pv_baseline_com_discount_amortization['Commecial Bank', time_period]))
        elif instrument == 'COM3' and time_period >= 2026:
            return as_measure(xl_sub(pv_baseline_com_discount_debt_stock['COM3', time_period - 1], pv_baseline_com_discount_amortization['COM3', time_period]))
        elif instrument == 'COM4' and time_period >= 2026:
            return as_measure(xl_sub(pv_baseline_com_discount_debt_stock['COM4', time_period - 1], pv_baseline_com_discount_amortization['COM4', time_period]))
        return as_measure(xl_sub(pv_baseline_com_discount_debt_stock['COM5', time_period - 1], pv_baseline_com_discount_amortization['COM5', time_period]))

    pv_baseline_com_discount_debt_stock = CoordinateReader('pv_baseline_com_discount_debt_stock', data.PV_BASELINE_COM_DISCOUNT_DEBT_STOCK.required, formula)
    return data.PV_BASELINE_COM_DISCOUNT_DEBT_STOCK.collect((coord, pv_baseline_com_discount_debt_stock[coord]) for coord in data.PV_BASELINE_COM_DISCOUNT_DEBT_STOCK.required)

