@publish(data.PV_BASELINE_COM_DISCOUNT_AMORTIZATION.schema, cells=data.PV_BASELINE_COM_DISCOUNT_AMORTIZATION.cells)
def pv_baseline_com_discount_amortization(*, pv_baseline_com_discount_period: data.Series[int | str | None], pv_baseline_com_grace: data.Series[int | str | None], pv_baseline_com_maturity: data.Series[int | str | None], pv_baseline_com_opening_percent_of_face: data.Series[int | str | None]) -> data.Series[float | str | None]:
    """Compute baseline commercial discount-schedule amortization by instrument and time period.

    Derive each instrument's linear amortization of opening percent of face across the post-grace maturity window, returning zero outside that window for COM3, COM4, COM5, Commecial Bank, and Eurobond.

    Args:
        pv_baseline_com_discount_period: data.Series[int | str | None] coordinate series of discount periods by instrument and time period, used to measure periods elapsed since the 2024 base and against grace/maturity.
        pv_baseline_com_grace: data.Series[int | str | None] series of grace periods by instrument; amortization begins only after this many periods past the 2024 base.
        pv_baseline_com_maturity: data.Series[int | str | None] series of maturity horizons by instrument; amortization ends at this period and is zero thereafter.
        pv_baseline_com_opening_percent_of_face: data.Series[int | str | None] series of opening percent-of-face amounts by instrument; the numerator prorated linearly over maturity minus grace.

    Returns:
        data.Series[float | str | None] amortization values aligned to the instrument/time-period coordinate: zero before grace and after maturity, otherwise the opening percent of face divided by the maturity-minus-grace interval, with string and null values propagated.
    """
    data.PV_BASELINE_COM_OPENING_PERCENT_OF_FACE.schema.validate(pv_baseline_com_opening_percent_of_face)
    def formula(instrument: str, time_period: int) -> float | str | None:
        if instrument == 'Eurobond':
            return as_measure((0 if xl_bool(xl_lt(xl_sub(xl_sub(pv_baseline_com_discount_period['Eurobond', time_period], pv_baseline_com_discount_period['Eurobond', 2024]), 1), pv_baseline_com_grace['Eurobond'])) else (xl_div(pv_baseline_com_opening_percent_of_face['Eurobond'], xl_sub(pv_baseline_com_maturity['Eurobond'], pv_baseline_com_grace['Eurobond'])) if xl_bool(xl_lt(xl_sub(xl_sub(pv_baseline_com_discount_period['Eurobond', time_period], pv_baseline_com_discount_period['Eurobond', 2024]), 1), pv_baseline_com_maturity['Eurobond'])) else 0)))
        elif instrument == 'Commecial Bank':
            return as_measure((0 if xl_bool(xl_lt(xl_sub(xl_sub(pv_baseline_com_discount_period['Commecial Bank', time_period], pv_baseline_com_discount_period['Commecial Bank', 2024]), 1), pv_baseline_com_grace['Commecial Bank'])) else (xl_div(pv_baseline_com_opening_percent_of_face['Commecial Bank'], xl_sub(pv_baseline_com_maturity['Commecial Bank'], pv_baseline_com_grace['Commecial Bank'])) if xl_bool(xl_lt(xl_sub(xl_sub(pv_baseline_com_discount_period['Commecial Bank', time_period], pv_baseline_com_discount_period['Commecial Bank', 2024]), 1), pv_baseline_com_maturity['Commecial Bank'])) else 0)))
        elif instrument == 'COM3':
            return as_measure((0 if xl_bool(xl_lt(xl_sub(xl_sub(pv_baseline_com_discount_period['COM3', time_period], pv_baseline_com_discount_period['COM3', 2024]), 1), pv_baseline_com_grace['COM3'])) else (xl_div(pv_baseline_com_opening_percent_of_face['COM3'], xl_sub(pv_baseline_com_maturity['COM3'], pv_baseline_com_grace['COM3'])) if xl_bool(xl_lt(xl_sub(xl_sub(pv_baseline_com_discount_period['COM3', time_period], pv_baseline_com_discount_period['COM3', 2024]), 1), pv_baseline_com_maturity['COM3'])) else 0)))
        elif instrument == 'COM4':
            return as_measure((0 if xl_bool(xl_lt(xl_sub(xl_sub(pv_baseline_com_discount_period['COM4', time_period], pv_baseline_com_discount_period['COM4', 2024]), 1), pv_baseline_com_grace['COM4'])) else (xl_div(pv_baseline_com_opening_percent_of_face['COM4'], xl_sub(pv_baseline_com_maturity['COM4'], pv_baseline_com_grace['COM4'])) if xl_bool(xl_lt(xl_sub(xl_sub(pv_baseline_com_discount_period['COM4', time_period], pv_baseline_com_discount_period['COM4', 2024]), 1), pv_baseline_com_maturity['COM4'])) else 0)))
        return as_measure((0 if xl_bool(xl_lt(xl_sub(xl_sub(pv_baseline_com_discount_period['COM5', time_period], pv_baseline_com_discount_period['COM5', 2024]), 1), pv_baseline_com_grace['COM5'])) else (xl_div(pv_baseline_com_opening_percent_of_face['COM5'], xl_sub(pv_baseline_com_maturity['COM5'], pv_baseline_com_grace['COM5'])) if xl_bool(xl_lt(xl_sub(xl_sub(pv_baseline_com_discount_period['COM5', time_period], pv_baseline_com_discount_period['COM5', 2024]), 1), pv_baseline_com_maturity['COM5'])) else 0)))

    return data.PV_BASELINE_COM_DISCOUNT_AMORTIZATION.collect(evaluate(formula, data.PV_BASELINE_COM_DISCOUNT_AMORTIZATION.required))

@publish(data.PV_BASELINE_COM_DISCOUNT_DISCOUNT_RATE.schema, cells=data.PV_BASELINE_COM_DISCOUNT_DISCOUNT_RATE.cells)
def pv_baseline_com_discount_discount_rate(*, input4_discount_rate: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute the per-instrument PV baseline COM discount rate series.

    Derives the discount-rate series used by PV baseline COM terms by evaluating authored coordinate identities against the provided input rate series.

    Args:
        input4_discount_rate: Keyword-only data.Series[float | str | None] of discount rates indexed by instrument coordinates, with values preserved as floats, text, or None.

    Returns:
        data.Series[float | str | None] containing the computed PV baseline COM discount rate for each required instrument (COM3, COM4, COM5, Commercial Bank, Eurobond), preserving scalar float, str, and None values.
    """
    def formula(instrument: str) -> float | str | None:
        return as_measure(input4_discount_rate[instrument])

    return data.PV_BASELINE_COM_DISCOUNT_DISCOUNT_RATE.collect(evaluate(formula, data.PV_BASELINE_COM_DISCOUNT_DISCOUNT_RATE.required))

@publish(data.PV_BASELINE_COM_DISCOUNT_INTEREST.schema, cells=data.PV_BASELINE_COM_DISCOUNT_INTEREST.cells)
def pv_baseline_com_discount_interest(*, pv_baseline_com_discount_debt_stock: data.Series[float | str | None], pv_baseline_com_discount_interest_rate: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute baseline commercial discount-schedule interest by instrument and period.

    Multiply each instrument's prior-period debt stock by its applicable discount interest rate.

    Args:
        pv_baseline_com_discount_debt_stock: Baseline commercial discount-schedule debt stock series over instruments and time periods; values may be float, str, or None.
        pv_baseline_com_discount_interest_rate: Baseline commercial discount-schedule interest rate series over instruments, providing the per-instrument rate applied to lagged debt stock.

    Returns:
        A data.Series[float | str | None] of computed interest values over instrument and time-period coordinates, preserving str/None values from the source series.
    """
    def formula(instrument: str, time_period: int) -> float | str | None:
        if instrument == 'Eurobond':
            return as_measure(xl_mul(pv_baseline_com_discount_interest_rate['Eurobond'], pv_baseline_com_discount_debt_stock['Eurobond', time_period - 1]))
        elif instrument == 'Commecial Bank':
            return as_measure(xl_mul(pv_baseline_com_discount_interest_rate['Commecial Bank'], pv_baseline_com_discount_debt_stock['Commecial Bank', time_period - 1]))
        elif instrument == 'COM3':
            return as_measure(xl_mul(pv_baseline_com_discount_interest_rate['COM3'], pv_baseline_com_discount_debt_stock['COM3', time_period - 1]))
        elif instrument == 'COM4':
            return as_measure(xl_mul(pv_baseline_com_discount_interest_rate['COM4'], pv_baseline_com_discount_debt_stock['COM4', time_period - 1]))
        return as_measure(xl_mul(pv_baseline_com_discount_interest_rate['COM5'], pv_baseline_com_discount_debt_stock['COM5', time_period - 1]))

    return data.PV_BASELINE_COM_DISCOUNT_INTEREST.collect(evaluate(formula, data.PV_BASELINE_COM_DISCOUNT_INTEREST.required))

@publish(data.PV_BASELINE_COM_DISCOUNT_TOTAL_DEBT_SERVICE.schema, cells=data.PV_BASELINE_COM_DISCOUNT_TOTAL_DEBT_SERVICE.cells)
def pv_baseline_com_discount_total_debt_service(*, pv_baseline_com_discount_amortization: data.Series[float | str | None], pv_baseline_com_discount_interest: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute total debt service by instrument as amortization plus interest on the baseline commercial discount schedule.

    Derive the per-instrument total debt service series for the baseline commercial discount schedule.

    Args:
        pv_baseline_com_discount_amortization: Amortization component for each instrument and time period, as a named-axis series over the discount-schedule catalog coordinates.
        pv_baseline_com_discount_interest: Interest component for each instrument and time period, as a named-axis series over the discount-schedule catalog coordinates.

    Returns:
        Total debt service as a named-axis series over the same instrument and time period coordinates, with each cell equal to the corresponding amortization plus interest.
    """
    def formula(instrument: str, time_period: int) -> float | str | None:
        if instrument == 'Eurobond':
            return as_measure(xl_add(pv_baseline_com_discount_amortization['Eurobond', time_period], pv_baseline_com_discount_interest['Eurobond', time_period]))
        elif instrument == 'Commecial Bank':
            return as_measure(xl_add(pv_baseline_com_discount_amortization['Commecial Bank', time_period], pv_baseline_com_discount_interest['Commecial Bank', time_period]))
        elif instrument == 'COM3':
            return as_measure(xl_add(pv_baseline_com_discount_amortization['COM3', time_period], pv_baseline_com_discount_interest['COM3', time_period]))
        elif instrument == 'COM4':
            return as_measure(xl_add(pv_baseline_com_discount_amortization['COM4', time_period], pv_baseline_com_discount_interest['COM4', time_period]))
        return as_measure(xl_add(pv_baseline_com_discount_amortization['COM5', time_period], pv_baseline_com_discount_interest['COM5', time_period]))

    return data.PV_BASELINE_COM_DISCOUNT_TOTAL_DEBT_SERVICE.collect(evaluate(formula, data.PV_BASELINE_COM_DISCOUNT_TOTAL_DEBT_SERVICE.required))

@publish(data.PV_BASELINE_COM_DISCOUNT_PV_OF_DEBT.schema, cells=data.PV_BASELINE_COM_DISCOUNT_PV_OF_DEBT.cells)
def pv_baseline_com_discount_pv_of_debt(*, pv_baseline_com_discount_debt_stock: data.Series[float | str | None], pv_baseline_com_discount_interest_rate: data.Series[float | str | None], pv_baseline_com_discount_discount_rate: data.Series[float | str | None], pv_baseline_com_discount_total_debt_service: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute the baseline commercial discount schedule's present value of debt across the five instruments (COM3, COM4, COM5, Commercial Bank, Eurobond).

    Derive each instrument-time period's PV of debt as debt stock when the interest rate is at least the discount rate, otherwise as the NPV of remaining total debt service through 2063.

    Args:
        pv_baseline_com_discount_debt_stock: data.Series[float | str | None] of baseline commercial discount debt stock indexed by instrument and time period.
        pv_baseline_com_discount_interest_rate: data.Series[float | str | None] of interest rates indexed by instrument, compared with the discount rate to choose debt stock or NPV treatment.
        pv_baseline_com_discount_discount_rate: data.Series[float | str | None] of discount rates indexed by instrument, used as the rate for discounting future total debt service.
        pv_baseline_com_discount_total_debt_service: data.Series[float | str | None] of total debt service indexed by instrument and time period, supplying the cash flows discounted over future periods.

    Returns:
        data.Series[float | str | None] of present value of debt by instrument and time period, with numeric PVs or text/None placeholders from the source series.
    """
    def formula(instrument: str, time_period: int) -> float | str | None:
        return as_measure((pv_baseline_com_discount_debt_stock[instrument, time_period] if xl_bool(xl_ge(pv_baseline_com_discount_interest_rate[instrument], pv_baseline_com_discount_discount_rate[instrument])) else xl_npv(pv_baseline_com_discount_discount_rate[instrument], view(pv_baseline_com_discount_total_debt_service, rows=(instrument,), cols=span(data.TIME_PERIOD_AXIS, time_period + 1, 2063)))))

    return data.PV_BASELINE_COM_DISCOUNT_PV_OF_DEBT.collect(evaluate(formula, data.PV_BASELINE_COM_DISCOUNT_PV_OF_DEBT.required))

@publish(data.PV_BASELINE_COM_DISCOUNT_T_G_0.schema, cells=data.PV_BASELINE_COM_DISCOUNT_T_G_0.cells)
def pv_baseline_com_discount_t_g_0(*, pv_baseline_com_discount_period: data.Series[int | str | None], pv_baseline_com_grace: data.Series[int | str | None]) -> data.Series[int | str | None]:
    """Compute the residual discount tenor (t − g > 0) for each COM baseline discount instrument.

    Derive, per instrument and time period, the positive discount period remaining after subtracting the grace period.

    Args:
        pv_baseline_com_discount_period: Per-instrument discount period in years from the COM baseline discount schedule, indexed by instrument and time period.
        pv_baseline_com_grace: Per-instrument grace period in years subtracted from the matching discount period on the same schedule.

    Returns:
        Instrument-major series of non-negative residual tenors (discount period minus grace, floored at zero) across the five COM instruments and their time periods.
    """
    def formula(instrument: str, time_period: int) -> int | str | None:
        if instrument == 'Eurobond':
            return as_measure((xl_sub(pv_baseline_com_discount_period['Eurobond', time_period], pv_baseline_com_grace['Eurobond']) if xl_bool(xl_gt(xl_sub(pv_baseline_com_discount_period['Eurobond', time_period], pv_baseline_com_grace['Eurobond']), 0)) else 0), 'int')
        elif instrument == 'Commecial Bank':
            return as_measure((xl_sub(pv_baseline_com_discount_period['Commecial Bank', time_period], pv_baseline_com_grace['Commecial Bank']) if xl_bool(xl_gt(xl_sub(pv_baseline_com_discount_period['Commecial Bank', time_period], pv_baseline_com_grace['Commecial Bank']), 0)) else 0), 'int')
        elif instrument == 'COM3':
            return as_measure((xl_sub(pv_baseline_com_discount_period['COM3', time_period], pv_baseline_com_grace['COM3']) if xl_bool(xl_gt(xl_sub(pv_baseline_com_discount_period['COM3', time_period], pv_baseline_com_grace['COM3']), 0)) else 0), 'int')
        elif instrument == 'COM4':
            return as_measure((xl_sub(pv_baseline_com_discount_period['COM4', time_period], pv_baseline_com_grace['COM4']) if xl_bool(xl_gt(xl_sub(pv_baseline_com_discount_period['COM4', time_period], pv_baseline_com_grace['COM4']), 0)) else 0), 'int')
        return as_measure((xl_sub(pv_baseline_com_discount_period['COM5', time_period], pv_baseline_com_grace['COM5']) if xl_bool(xl_gt(xl_sub(pv_baseline_com_discount_period['COM5', time_period], pv_baseline_com_grace['COM5']), 0)) else 0), 'int')

    return data.PV_BASELINE_COM_DISCOUNT_T_G_0.collect(evaluate(formula, data.PV_BASELINE_COM_DISCOUNT_T_G_0.required))

