        if instrument == 'Eurobond' and time_period == 2028:
            return as_measure(xl_sum(view(pv_baseline_com_output_new_forex_borrowing_gross_usd, rows=('Eurobond',), cols=span(data.TIME_PERIOD_AXIS, 2025, time_period - 1))))
